window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0216", [{"word":"control group","ipa_uk":"/kənˈtrəʊl ɡruːp/","ipa_us":"/kənˈtroʊl ɡruːp/","definition_zh":"对照组；实验或比较研究中不接受处理、用作比较基准的那一组；统计模型中的参照类别","definition_en":"the group in an experiment or comparison study that receives no treatment and serves as a standard","core_image":"两只同样的托盘并排摆着，一只滴了药液，一只只滴清水，旁边一块牌子写着比较基准","scene":"实验室里两只同样的托盘并排摆着，一只滴了药液，另一只只滴清水，记录员每天比对两只托盘里的变化。The control group received only plain water, so any change in the treated trays could be credited to the drug.","sceneCN":"这里指不接受处理、只作比较基准的那一组（第 1 个义项：实验里不接受处理、被用作比较标准的一组）；句意为对照组只拿到清水，因此处理组托盘里的任何变化都可归到药物上。图中可辨识物件：两只托盘、滴管、记录本、标签牌。","pos":[{"tag":"n.","zh":"对照组；比较基准组；参照组"}],"collocations":[{"phrase":"untreated control group","zh":"未处理对照组"},{"phrase":"matched control group","zh":"匹配对照组"},{"phrase":"control group design","zh":"对照组设计"},{"phrase":"serve as a control group","zh":"充当对照组"},{"phrase":"placebo control group","zh":"安慰剂对照组"},{"phrase":"control group comparison","zh":"与对照组的比较"}],"forms":[{"label":"单数","form":"control group"},{"label":"复数","form":"control groups"},{"label":"相关动词（控制）","form":"control"},{"label":"相关名词（组）","form":"group"},{"label":"形容词（受控的）","form":"controlled"},{"label":"复合形式（对照条件）","form":"control condition"}],"derivatives":[{"word":"control","pos":"n./v.","zh":"控制；核对；对照"},{"word":"controlled","pos":"adj.","zh":"受控的；有对照的"},{"word":"controller","pos":"n.","zh":"控制者；控制器"},{"word":"controlling","pos":"adj.","zh":"控制的；支配的"},{"word":"group","pos":"n./v.","zh":"组；分组"},{"word":"grouping","pos":"n.","zh":"分组；归类"}],"senses":[{"no":"01","title":"The group left untreated","titleCN":"不作处理的那一组","definition":"the group in an experiment that receives no treatment and is used as the standard","definitionCN":"实验里不接受处理、被用作比较标准的那一组","example":"The control group stayed on the old routine while the others tried the new one.","exampleCN":"对照组沿用旧流程，其余各组试用新流程。","why":"Control first meant a check copy of an account, and this group is the check copy of an experiment.","whyCN":"这个词最初指账目的核对副本，而这一组正是实验的核对副本。"},{"no":"02","title":"The placebo arm of a trial","titleCN":"试验中的安慰剂组","definition":"the group in a clinical trial that receives a placebo or standard care instead of the tested drug","definitionCN":"临床试验中接受安慰剂或标准治疗、而非受试药物的那一组","example":"Half the patients joined the control group and received a sugar pill.","exampleCN":"一半病人进入对照组，服用了糖丸。","why":"A drug must be compared with something, and the placebo arm supplies that something.","whyCN":"药物总要有个比较对象，安慰剂组就提供这个对象。"},{"no":"03","title":"The group without the variable","titleCN":"未施加自变量的被试组","definition":"the participants in a psychology study who are kept out of the condition being tested","definitionCN":"心理学研究中没有被放进所测条件的被试","example":"In the memory study, the control group watched the same film without any instruction.","exampleCN":"在记忆研究中，对照组看了同一部影片，却没有收到任何指示。","why":"Psychology borrowed the design from medicine and kept the name for the group given no instruction.","whyCN":"心理学借用了医学的设计，也沿用这个名字来指得不到指示的那一组。"},{"no":"04","title":"The ordinary class","titleCN":"沿用原教法的对照班","definition":"the class in a teaching experiment that continues with the ordinary syllabus","definitionCN":"教学实验中继续使用原有课程的班级","example":"The control group in the second school followed the ordinary syllabus.","exampleCN":"第二所学校里的对照班沿用原有课程。","why":"Once a new method is tried in one class, the ordinary class becomes the measure of its effect.","whyCN":"新教法在一个班试用后，照常上课的那个班就成了衡量效果的尺子。"},{"no":"05","title":"The comparison group in the field","titleCN":"实地研究中的比较组","definition":"a group followed in an observational study for comparison, without any assigned treatment","definitionCN":"观察研究中被追踪、用于比较、并未被指派处理的一组","example":"A control group of untreated patients was followed for the same period.","exampleCN":"一组未接受治疗的患者在同一时期被追踪。","why":"Even without random assignment, a comparable group keeps the comparison honest.","whyCN":"即便没有随机分配，一个可比组也能让比较站得住。"},{"no":"06","title":"The batch left at room temperature","titleCN":"常温放置的对照批","definition":"a batch of material or product kept under ordinary conditions to show what the treatment did","definitionCN":"在普通条件下保存、用来检验处理效果的一批材料或产品","example":"A control group of uncoated panels was exposed on the same roof.","exampleCN":"一组未涂层的板材被放在同一座屋顶上暴露。","why":"The laboratory extended the word from people to batches, because the logic of a baseline does not change.","whyCN":"实验室把这个词从人扩展到批次，因为基准的逻辑并没有变。"},{"no":"07","title":"The reference category in a model","titleCN":"统计模型中的参照类别","definition":"the category against which other categories are compared in a statistical model","definitionCN":"统计模型中用来与其它类别比较的那个类别","example":"The untreated condition became the control group in the regression model.","exampleCN":"未处理的条件在回归模型里成为参照组。","why":"In a model one category must stand still while the others move, and the old name suits that stillness.","whyCN":"模型里总要有一个类别站着不动、其它类别相对它变动，旧名字正好适合这种不动。"},{"no":"08","title":"The untreated half of a matched pair","titleCN":"配对研究里未受处理的一方","definition":"the member of a matched pair that is deliberately left without the supplement or treatment","definitionCN":"配对研究中被有意不给补充剂或不给处理的那一方","example":"In the matched-pair study the control group was the twin who received no supplement.","exampleCN":"在那项配对研究中，对照组就是没有服用补充剂的那位双胞胎。","why":"Pairing makes the comparison local: the untreated twin is the baseline for the treated one.","whyCN":"配对把比较拉到近处：未受处理的双胞胎就是受处理那一位的基准。"},{"no":"09","title":"The yardstick in daily life","titleCN":"生活里的比较参照","definition":"a person or standard against which someone measures ordinary life","definitionCN":"日常生活中被人拿来衡量自己的对象或标准","example":"For a dieter, the control group is the friend who never counts calories.","exampleCN":"对节食者来说，对照组就是那个从不计算热量的朋友。","why":"The experiment's baseline escaped the lab and became any steady point of comparison.","whyCN":"实验的基准走出了实验室，成了任何稳定的比较点。"}],"etymology":{"intro":{"en":"Control is a bookkeeping word that became a laboratory word. Its first element is Medieval Latin contrarotulus, a counter-roll kept to check another roll, and group came through French from Italian. The phrase itself is a modern compound; its source chain is clear, while the exact year of its first written use is not known.","cn":"前一词从记账语境走进实验室，前身是中世纪拉丁 contrarotulus，即用来核对另一本账的副本账；后一词经法语来自意大利语。这个短语本身是近现代复合词，词源链清楚，只是最早书面用例的年代不确定。"},"items":[{"era":"MEDIEVAL LATIN","en":"Contrarotulus joined contra- against and rotulus roll, naming a duplicate roll kept to check the accounts.","cn":"中世纪拉丁的 contrarotulus 由意为「对着」的前缀与意为「卷册」的词根合成，指用来核对账目的副本账。"},{"era":"OLD FRENCH","en":"Contrerole carried the checking sense into English, and the early verb control meant to verify a record rather than to command.","cn":"古法语 contrerole 把这个核对义带进英语，早期动词义为核实记录，而不是发号施令。"},{"era":"MODERN CONTROL","en":"By the seventeenth century control had widened from checking a record to regulating and commanding a course of events.","cn":"到十七世纪，这个词从核对记录扩展到调节与支配事态。"},{"era":"FRENCH GROUPE","en":"Groupe came from Italian gruppo cluster or knot, and English took it in the seventeenth century as a set of things or people.","cn":"法语 groupe 来自意大利语 gruppo「一团、一结」，英语在十七世纪把它借来表示一组事物或一群人。"},{"era":"THE PHRASE","en":"Control group belongs to the vocabulary of controlled experiments, which took shape in the nineteenth and twentieth centuries; its first recorded use is date uncertain.","cn":"这个短语属于受控实验的词汇，这类方法在十九至二十世纪成形；其最早书面用例的年代不确定。"},{"era":"STATISTICAL USE","en":"Twentieth-century statistics gave the same name to the reference category of a model, where no treatment is assigned at all.","cn":"二十世纪的统计学又把同一个名字给了模型的参照类别，那一类完全不被施加处理。"}]},"similar":{"note":{"en":"The first group looks or sounds like control group; the second group names neighbouring ideas in experimental design.","cn":"第一组在形音上与「对照组」相近；第二组是实验设计里意思相邻的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"control","ipa":"/kənˈtrəʊl/","tag":"different sense","definition":"The verb and noun for checking, regulating or commanding; the phrase borrows its checking sense.","definitionCN":"表示核对、调节或支配的动词与名词；短语借的是其中的核对义。"},{"word":"controller","ipa":"/kənˈtrəʊlə/","tag":"same root","definition":"A person who controls, or a device that regulates a machine.","definitionCN":"控制者，或调节机器的装置。"},{"word":"controlled","ipa":"/kənˈtrəʊld/","tag":"same root","definition":"Kept under a rule or a comparison, as in a controlled experiment.","definitionCN":"受规则或对照约束的，如受控实验。"},{"word":"group","ipa":"/ɡruːp/","tag":"same phrase","definition":"A set of people or things placed together; the second half of the phrase.","definitionCN":"放在一起的一群人或物；短语的后一半。"},{"word":"grouping","ipa":"/ˈɡruːpɪŋ/","tag":"same root","definition":"The act or result of putting things into groups.","definitionCN":"把事物分组的行为或结果。"}]},{"heading":"NEAR MEANING","entries":[{"word":"comparison group","ipa":"/kəmˈpærɪsn ɡruːp/","tag":"near meaning","definition":"A broader name for any group used as a standard in a comparison.","definitionCN":"泛指比较研究中用作标准的任何一组。"},{"word":"reference group","ipa":"/ˈrefrəns ɡruːp/","tag":"near meaning","definition":"A group whose results are used as the point of reference.","definitionCN":"其结果被用作参照的那一组。"},{"word":"placebo group","ipa":"/pləˈsiːbəʊ ɡruːp/","tag":"near meaning","definition":"The arm of a trial that receives an inactive treatment.","definitionCN":"试验中接受无效处理的那一组。"},{"word":"baseline group","ipa":"/ˈbeɪslaɪn ɡruːp/","tag":"near meaning","definition":"The group measured before any change, giving the starting point.","definitionCN":"在任何变动之前测量、提供起点的那一组。"},{"word":"experimental group","ipa":"/ɪkˌsperɪˈmentl ɡruːp/","tag":"opposite role","definition":"The group that does receive the treatment, the partner of a control group.","definitionCN":"接受处理的那一组，是对照组的搭档。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real bookkeeping source, the real compounds and real fixed phrases.","cn":"正常联想使用真实的记账来源、真实的复合方式与真实固定搭配。"},"normal":[{"en":"Control began as a counter-roll kept to check another roll, so a control group is the checking copy of an experiment.","cn":"control 最初是核对另一本账的副本账，所以对照组就是实验的核对副本。"},{"en":"The phrase is simply control plus group: the group used for checking.","cn":"这个短语就是「核对」加「组」：用来核对的那一组。"},{"en":"Fixed phrases include untreated control group, matched control group and placebo control group.","cn":"固定说法有未处理对照组、匹配对照组与安慰剂对照组。"},{"en":"In a drug trial the control group often takes a sugar pill, so that the real drug must prove itself against it.","cn":"药物试验里对照组常吃糖丸，真药得在它面前证明自己。"},{"en":"Statistics reuses the name for the reference category of a model.","cn":"统计学又把这个名字用在模型的参照类别上。"}],"abstract":[{"en":"A control group is a mirror that shows what the treatment actually changed.","cn":"对照组是一面镜子，照出处理到底改变了什么。"},{"en":"It stands still on purpose, so that the other groups can show their movement.","cn":"它故意站着不动，好让别的组显出移动。"},{"en":"Without it, every change in the experiment belongs to nobody in particular.","cn":"没有它，实验里的每一种变化都说不清是谁造成的。"}]},"examples":[{"en":"The control group was chosen before the first dose was given.","cn":"对照组在第一次给药之前就已选定。"},{"en":"Without a control group, the improvement could have come from the season.","cn":"若没有对照组，好转也可能只是季节带来的。"},{"en":"The report compared the control group with two treated groups.","cn":"报告把对照组与两个处理组作了比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「控住组」——把变量控住不动的那一组：对照组","word":"control group"},"root":"前一词源自中世纪拉丁 contrarotulus「对照账簿」，经古法语 contrerole 进入英语，由「核对」引申为「控制」；后一词源自法语 groupe，更早为意大利语 gruppo「一团、一结」。短语 control group 随十九至二十世纪的受控实验方法通行，词源清楚，最早书面用例的年代不确定。","sensesIntro":{"en":"Nine senses follow one baseline: the untreated group, the placebo arm, the psychology condition, the ordinary class, the field comparison, the batch left plain, the reference category, the members, and finally the yardstick of daily life.","cn":"九个义项跟着同一条基准：不作处理的组、安慰剂组、心理学条件组、照常上课的班、实地比较组、常温放置的批次、统计参照类别、组内成员，最后是生活里的比较参照。"},"semanticMap":{"core":{"en":"CORE IMAGE: two identical trays side by side, one treated and one plain, so any difference can be traced to the treatment.","cn":"核心意象：两只同样的托盘并排摆着，一只处理过、一只原样，任何差别都能追到处理上。"},"chain":["BASELINE","UNTREATED GROUP","PLACEBO ARM","FIELD COMPARISON","REFERENCE CATEGORY","DAILY YARDSTICK"],"branches":[{"senses":"01 · 08","en":"THE SET AND THE UNTREATED TWIN: the group as a whole, and the untreated member of a matched pair.","cn":"整体与未处理的配对一方：作为一个整体的组，以及配对研究中被有意留作基准的那一方。"},{"senses":"02 · 03","en":"THE TWO ARMS OF A TRIAL: the placebo arm in medicine and the no-instruction condition in psychology.","cn":"试验的两臂：医学里的安慰剂组与心理学里的无指示条件。"},{"senses":"04 · 05","en":"THE COMPARISON OUTSIDE THE LAB: an ordinary class and a field group followed without assignment.","cn":"实验室外的比较：照常上课的班级与未被指派处理的实地群体。"},{"senses":"06 · 07","en":"THE BATCH AND THE MODEL: material kept plain, and a category held still in a regression.","cn":"批次与模型：保持原样的材料，以及在回归里保持不动的类别。"},{"senses":"09","en":"THE EVERYDAY YARDSTICK: the baseline becomes any person or standard someone measures life against.","cn":"日常的尺子：基准变成人们拿来衡量生活的任何对象或标准。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin bookkeeping word and a French loanword; the Latin list covers the control side, while group has no Latin ancestor.","cn":"这个短语把拉丁记账词与法语借词合在一起；拉丁词条只覆盖 control 一侧，group 没有拉丁语祖先。"},"latinIntro":{"en":"Latin contrarotulus and rotulus give the control half; group came from French groupe, itself from Italian gruppo.","cn":"拉丁 contrarotulus 与 rotulus 构成 control 一半；group 来自法语 groupe，更早为意大利语 gruppo。"},"items":[{"word":"contrarotulus","structure":"Medieval Latin compound","meaning":"a counter-roll kept for checking","meaningCN":"用来核对的副本账","example":"The word began as a clerk's safeguard.","exampleCN":"这个词起初是账房的自保手段。"},{"word":"rotulus","structure":"Latin noun, diminutive of rota","meaning":"a roll; a schedule","meaningCN":"卷册；清单","example":"Accounts were kept on rolls before books.","exampleCN":"在册页之前，账目记在卷轴上。"},{"word":"contrerole","structure":"Old French noun","meaning":"a duplicate register","meaningCN":"副本登记册","example":"The French form carried the checking sense across the Channel.","exampleCN":"法语词形把核对义带过了海峡。"},{"word":"control","structure":"English verb and noun","meaning":"to check; later to regulate","meaningCN":"核对；后来指调节、控制","example":"The meaning widened from verifying to commanding.","exampleCN":"词义从核实扩展到了支配。"},{"word":"controller","structure":"control plus -er","meaning":"one who checks or regulates","meaningCN":"核对者；控制者","example":"The agent suffix names the person or device that checks.","exampleCN":"施动后缀指核对的人或装置。"},{"word":"groupe","structure":"French noun","meaning":"a cluster; a set","meaningCN":"一团；一组","example":"The French word named things gathered together.","exampleCN":"法语词指聚在一起的一群事物。"},{"word":"gruppo","structure":"Italian noun","meaning":"a knot; a cluster","meaningCN":"结；一团","example":"The Italian source is the knot at the centre of the word.","exampleCN":"意大利语源头是这个词中间的「结」。"},{"word":"group","structure":"English noun and verb","meaning":"a set; to put into a set","meaningCN":"组；分组","example":"The second half of the phrase is an ordinary English word.","exampleCN":"短语的后一半是一个普通英语词。"},{"word":"controlled","structure":"control plus -ed","meaning":"kept under control","meaningCN":"受控的","example":"The adjective marks a study with a comparison.","exampleCN":"这个形容词标出带有对照的研究。"}],"latinEntries":[{"word":"contrarotulus","structure":"contrarotulus, contrarotuli (n., second declension)","meaning":"counter-roll; duplicate register","meaningCN":"对照卷册；副本账簿"},{"word":"rotulus","structure":"rotulus, rotuli (n., second declension)","meaning":"roll; list","meaningCN":"卷轴；名册"},{"word":"contra","structure":"Latin preposition","meaning":"against; opposite","meaningCN":"对着；相反"}],"derivatives":[{"word":"control","pos":"n./v.","zh":"控制；核对"},{"word":"controlled","pos":"adj.","zh":"受控的"},{"word":"controller","pos":"n.","zh":"控制者；控制器"},{"word":"controlling","pos":"adj.","zh":"支配的"},{"word":"group","pos":"n./v.","zh":"组；分组"},{"word":"grouping","pos":"n.","zh":"分组"}]}},{"word":"experimental group","ipa_uk":"/ɪkˌsperɪˈmentl ɡruːp/","ipa_us":"/ɪkˌsperɪˈmentl ɡruːp/","definition_zh":"实验组；接受实验处理或所测条件的那一组；与对照组配对的受试组","definition_en":"the group in an experiment that receives the treatment or the condition under study","core_image":"同一间实验室里两排架子并排，一排贴接受处理的标签，另一排贴不作处理的标签","scene":"同一间实验室里两排架子并排摆着，一排贴着接受处理的标签，另一排不作处理，管理员按标签分发不同的培养液。The experimental group took the new compound every morning for six weeks.","sceneCN":"这里指接受处理、与对照组配对的那一组（第 1 个义项：实验里接受处理或所测条件的组）；句意为实验组连续六周每天早晨服用新化合物。图中可辨识物件：两排架子、培养皿、标签、移液器。","pos":[{"tag":"n.","zh":"实验组；处理组"}],"collocations":[{"phrase":"experimental group and control group","zh":"实验组与对照组"},{"phrase":"assign to the experimental group","zh":"分配到实验组"},{"phrase":"experimental group members","zh":"实验组成员"},{"phrase":"experimental group condition","zh":"实验组条件"},{"phrase":"experimental group received","zh":"实验组接受了"},{"phrase":"treatment in the experimental group","zh":"实验组所接受的处理"}],"forms":[{"label":"单数","form":"experimental group"},{"label":"复数","form":"experimental groups"},{"label":"形容词（实验的）","form":"experimental"},{"label":"名词（实验）","form":"experiment"},{"label":"动词（做实验）","form":"experiment"},{"label":"相关名词（组）","form":"group"},{"label":"复合形式（实验条件）","form":"experimental condition"}],"derivatives":[{"word":"experiment","pos":"n./v.","zh":"实验；做实验"},{"word":"experimental","pos":"adj.","zh":"实验的；试验性的"},{"word":"experimentally","pos":"adv.","zh":"以实验方式"},{"word":"experimentation","pos":"n.","zh":"实验；实验过程"},{"word":"experimenter","pos":"n.","zh":"实验者"},{"word":"group","pos":"n./v.","zh":"组；分组"}],"senses":[{"no":"01","title":"The group that gets the treatment","titleCN":"接受处理的那一组","definition":"the group in an experiment that receives the treatment or the condition being tested","definitionCN":"实验里接受处理或所测条件的那一组","example":"The experimental group worked in a room with soft light, while the others did not.","exampleCN":"实验组在光线柔和的房间里工作，其余各组则没有。","why":"Experiment first meant a trial, and this is the arm on which the trial is actually tried.","whyCN":"这个词最初指一次试验，而这一组正是试验真正施加于其上的那一臂。"},{"no":"02","title":"The treated arm of a trial","titleCN":"临床试验中的用药组","definition":"the arm of a clinical trial that receives the drug or procedure under test","definitionCN":"临床试验中接受受试药物或受试操作的那一臂","example":"The experimental group received the drug twice daily for a month.","exampleCN":"实验组每天两次服药，连续一个月。","why":"Medicine needs a name for the side that actually gets the new substance.","whyCN":"医学需要一个名字来指真正拿到新药的那一边。"},{"no":"03","title":"The condition group in psychology","titleCN":"心理学中的条件组","definition":"the participants placed in the condition whose effect the study measures","definitionCN":"被放进所测条件、其效果由研究衡量的被试","example":"In the memory task, the experimental group studied the list twice.","exampleCN":"在记忆任务中，实验组把词表学习了两遍。","why":"The word experiment covers mental as well as physical trials, so the treated side keeps the name.","whyCN":"这个词既指物理试验也指心理试验，接受条件的一边因此沿用这个名字。"},{"no":"04","title":"The class trying a new method","titleCN":"试用新教法的班级","definition":"the class in a teaching experiment that uses the new method or material","definitionCN":"教学实验中使用新方法或新材料的班级","example":"The experimental group in the second school used the new textbook.","exampleCN":"第二所学校里的实验班使用了新教材。","why":"Once a method is tested on learners, the class that tries it becomes the experimental side.","whyCN":"一种方法在学习者身上试用后，试用的班级就成了实验的一边。"},{"no":"05","title":"The treated animals","titleCN":"动物实验中的处理组","definition":"the animals in a laboratory study that receive the substance or procedure being tested","definitionCN":"实验室研究中接受受试物质或操作的动物","example":"The experimental group of mice ran on a wheel each night.","exampleCN":"实验组的老鼠每晚在轮子上跑动。","why":"Animal studies use the same pairing, and the treated cage keeps the name.","whyCN":"动物研究使用同样的配对，接受处理的笼子沿用这个名字。"},{"no":"06","title":"The trial batch in the field","titleCN":"田间或工厂的试验批","definition":"a batch of seeds, plants or products given the new treatment in a field or factory trial","definitionCN":"在田间或工厂试验中接受新处理的一批种子、植株或产品","example":"The experimental group of seeds was sown a week earlier.","exampleCN":"实验组的那批种子早了一周播种。","why":"The design travels from wards to fields and workshops without changing its shape.","whyCN":"这种设计从病房走到田里与车间，形状没有改变。"},{"no":"07","title":"The group that receives a programme","titleCN":"项目评估中接受项目的一组","definition":"the group that receives a social programme or service in an evaluation study","definitionCN":"在项目评估中接受某项社会项目或服务的那一组","example":"In the literacy programme evaluation the experimental group received the new classes.","exampleCN":"在那项扫盲项目评估中，实验组接受了新的课程。","why":"Evaluation extends the laboratory pair to social programmes, where the treated side is a group of recipients.","whyCN":"项目评估把实验室里的两臂扩展到社会项目，受项目照顾的一边就是一组受助者。"},{"no":"08","title":"The matched partner","titleCN":"与对照组配对的一方","definition":"the group seen in its relation to the control group that mirrors it","definitionCN":"在与对照组的镜像关系中被看待的那一组","example":"The experimental group and its matched comparison came from the same ward.","exampleCN":"实验组与和它配对的比较组来自同一间病房。","why":"A treated group exists as such only because another group is deliberately left alone.","whyCN":"处理组之所以成立，正因为另有一组被有意留在一旁。"},{"no":"09","title":"The intervention group in a quasi-experiment","titleCN":"准实验中的干预组","definition":"the group receiving an intervention in a study where assignment is not random","definitionCN":"在分配并非随机的研究中接受干预的那一组","example":"In the quasi-experiment, the experimental group was the class that had already chosen the course.","exampleCN":"在那项准实验里，实验组是已经选了这门课的那个班。","why":"When assignment is not random, the treated side is still named by its role, not by its origin.","whyCN":"分配不随机时，接受处理的一边仍按角色命名，而不是按来历命名。"}],"etymology":{"intro":{"en":"Experiment comes from Latin experimentum, a trial or proof, built on experiri to try. Group is the same French loanword used in control group. The compound is a modern label from experimental design, and its first recorded use is date uncertain.","cn":"前一词源自拉丁 experimentum「试验、验证」，由 experiri「尝试」构成；后一词与前一短语里的后一词是同一个法语借词。这个复合词是近现代实验设计的标签，最早书面用例的年代不确定。"},"items":[{"era":"LATIN EXPERIMENTUM","en":"Experimentum meant a trial, a test or a proof, and it named the act before it named the thing.","cn":"experimentum 指试验、检验或证明，先命名行动，再命名事物。"},{"era":"LATIN EXPERIRI","en":"Experiri meant to try or test; it also gave English experience, expert and perilous, all sharing the idea of going through something.","cn":"experiri 意为尝试、检验；它还衍生出表示「经历」「专家」「危险的」三个英语词。"},{"era":"FRENCH EXPERIMENT","en":"Old French experiment brought the word into English, where it first named a trial of a claim.","cn":"古法语 experiment 把这个词带进英语，最初指对某种说法的检验。"},{"era":"FRENCH GROUPE","en":"Groupe came from Italian gruppo cluster or knot, and entered English as a set of people or things.","cn":"法语 groupe 来自意大利语 gruppo「一团、一结」，进入英语后指一组人或物。"},{"era":"THE PHRASE","en":"Experimental group belongs to the vocabulary of controlled comparison, which developed in the nineteenth and twentieth centuries; its first recorded use is date uncertain.","cn":"这个短语属于受控比较的词汇，这类方法在十九至二十世纪发展起来；其最早书面用例的年代不确定。"},{"era":"MODERN TRIALS","en":"Randomized trials in the twentieth century fixed the pair experimental group and control group as standard terms.","cn":"二十世纪的随机试验把这组对立固定为标准术语：实验组与对照组。"}]},"similar":{"note":{"en":"The first group looks or sounds like experimental group; the second names roles that sit beside it in a study.","cn":"第一组在形音上与「实验组」相近；第二组是研究里与它相邻的其他角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"experiment","ipa":"/ɪkˈsperɪmənt/","tag":"same root","definition":"A trial or test, and the verb for carrying one out.","definitionCN":"试验或检验，也指进行试验。"},{"word":"experimental","ipa":"/ɪkˌsperɪˈmentl/","tag":"same root","definition":"The adjective for anything belonging to an experiment or still being tested.","definitionCN":"指属于实验的，或仍处于试验阶段的。"},{"word":"experimentally","ipa":"/ɪkˌsperɪˈmentli/","tag":"same root","definition":"The adverb for doing something by experiment.","definitionCN":"指以实验方式做某事。"},{"word":"experimentation","ipa":"/ɪkˌsperɪmenˈteɪʃn/","tag":"same root","definition":"The activity of running experiments, often over time.","definitionCN":"反复进行实验的活动。"},{"word":"experimenter","ipa":"/ɪkˈsperɪmentə/","tag":"same root","definition":"The person who designs or runs the experiment.","definitionCN":"设计或执行实验的人。"},{"word":"group","ipa":"/ɡruːp/","tag":"same phrase","definition":"A set of participants; the second half of the phrase.","definitionCN":"一组参与者；短语的后一半。"}]},{"heading":"NEAR MEANING","entries":[{"word":"treatment group","ipa":"/ˈtriːtmənt ɡruːp/","tag":"near meaning","definition":"The group receiving the treatment, common in medical writing.","definitionCN":"接受处理的那一组，常见于医学写作。"},{"word":"intervention group","ipa":"/ˌɪntəˈvenʃn ɡruːp/","tag":"near meaning","definition":"The group given a deliberate intervention in a study.","definitionCN":"研究中被给予有意干预的那一组。"},{"word":"study group","ipa":"/ˈstʌdi ɡruːp/","tag":"near meaning","definition":"A general name for any group being studied.","definitionCN":"泛指任何被研究的一组。"},{"word":"active arm","ipa":"/ˈæktɪv ɑːm/","tag":"near meaning","definition":"The arm of a trial that receives the active substance rather than a placebo.","definitionCN":"试验中接受活性物质而非安慰剂的那一臂。"},{"word":"control group","ipa":"/kənˈtrəʊl ɡruːp/","tag":"opposite role","definition":"The group left untreated, the partner of an experimental group.","definitionCN":"不接受处理的那一组，是实验组的搭档。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin source, the real trial vocabulary and real fixed phrases.","cn":"正常联想使用真实的拉丁来源、真实的试验词汇与真实固定搭配。"},"normal":[{"en":"Experimentum meant a trial, so the experimental group is the side on which the trial is tried.","cn":"experimentum 指一次试验，所以实验组就是试验施加其上的那一边。"},{"en":"The phrase is experiment plus group, and it always implies a partner left untreated.","cn":"这个短语是「实验」加「组」，而且总暗示另有一组不作处理。"},{"en":"In medicine the same role is often called the treatment group or the active arm.","cn":"在医学里，同样的角色常叫作治疗组或活性治疗臂。"},{"en":"Fixed phrases include assign to the experimental group and experimental group members.","cn":"固定说法有「分配到实验组」与「实验组成员」。"},{"en":"Randomized trials fixed the pair experimental group and control group as standard terms.","cn":"随机试验把「实验组」与「对照组」这一对说法固定为标准术语。"}],"abstract":[{"en":"The experimental group is the hand that touches the change, while the other hand stays still.","cn":"实验组是去碰变化的那只手，另一只手则保持不动。"},{"en":"Its identity is relational: it is experimental only because something else is not.","cn":"它的身份是相对的：它之所以是实验的，只因为另有一组不是。"},{"en":"Every claim about a treatment is really a claim about the gap between these two groups.","cn":"关于处理的每个结论，其实都是关于这两组之间差距的结论。"}]},"examples":[{"en":"The experimental group was given the new fertilizer, and the other field was not.","cn":"实验组施用了新肥料，另一块田则没有。"},{"en":"Researchers assigned every third volunteer to the experimental group.","cn":"研究者把每第三名志愿者分配到实验组。"},{"en":"The experimental group improved faster than the group left untreated.","cn":"实验组的改善比未处理的组更快。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「试一组」——先被试上新办法的那一组：实验组","word":"experimental group"},"root":"前一词源自拉丁 experimentum「试验、验证」，来自 experiri「尝试、检验」；后一词源自法语 groupe，更早为意大利语 gruppo「一团」。短语 experimental group 随十九至二十世纪的受控比较方法通行，词源清楚，最早书面用例的年代不确定。","sensesIntro":{"en":"Nine senses follow the treated side: the general treatment group, the drug arm, the psychology condition, the trial class, the treated animals, the field batch, the members, the matched partner, and the intervention group of a quasi-experiment.","cn":"九个义项跟着接受处理的一边：一般处理组、用药组、心理学条件组、试教班、受处理动物、田间试验批、组内成员、配对的一方，以及准实验中的干预组。"},"semanticMap":{"core":{"en":"CORE IMAGE: two rows of shelves, one labelled as treated and one left plain, so the difference belongs to the labelled row.","cn":"核心意象：两排架子，一排标明接受处理、一排保持原样，差别便归到标明的那一排。"},"chain":["TREATED SIDE","CLINICAL ARM","VARIABLE CONDITION","FIELD TRIAL","MATCHED PARTNER","QUASI-EXPERIMENT"],"branches":[{"senses":"01 · 07","en":"THE SET AND THE RECIPIENTS: the treated set as a whole, and the group that receives a programme.","cn":"整体与受助者：接受处理的整体，以及项目评估中接受项目的一组。"},{"senses":"02 · 09","en":"THE MEDICAL AND THE NON-RANDOM ARM: the drug arm and the intervention group assigned without randomisation.","cn":"医学臂与非随机臂：用药组，以及未随机分配而形成的干预组。"},{"senses":"03 · 04","en":"THE MIND AND THE CLASSROOM: a condition given to participants and a method given to learners.","cn":"心智与课堂：给予被试的条件，以及给予学习者的方法。"},{"senses":"05 · 06","en":"THE OTHER BODIES: treated animals in a laboratory and a treated batch in a field.","cn":"别的身体：实验室里受处理的动物与田里受处理的一批。"},{"senses":"08","en":"THE PARTNER: the group exists only in its mirror relation to the control group.","cn":"配对者：这一组只在它与对照组的镜像关系中成立。"}]},"affixes":{"intro":{"en":"Experiment carries a Latin trial word, and group is the same French loanword seen in control group; the Latin list covers the first element.","cn":"experiment 带着一个拉丁「试验」词，group 则是 control group 里那个法语借词；拉丁词条覆盖前一成分。"},"latinIntro":{"en":"Latin experimentum and experiri supply the first half; group has no Latin ancestor and came through French from Italian.","cn":"拉丁 experimentum 与 experiri 提供前半部分；group 没有拉丁语祖先，是经法语从意大利语来的。"},"items":[{"word":"experimentum","structure":"Latin noun of action","meaning":"a trial; a proof","meaningCN":"试验；证明","example":"The noun names the act of testing before the thing tested.","exampleCN":"这个名词先指检验的行动，再指被检验之物。"},{"word":"experiri","structure":"Latin verb, deponent","meaning":"to try; to test","meaningCN":"尝试；检验","example":"The verb carries the idea of going through a test.","exampleCN":"这个动词带着「经历一番检验」的意思。"},{"word":"periri","structure":"Latin verb root","meaning":"to attempt; to risk","meaningCN":"尝试；冒险","example":"The root links trial with danger and experience.","exampleCN":"这个词根把试验、危险与经历连在一起。"},{"word":"experiment","structure":"English noun and verb","meaning":"a test; to carry out a test","meaningCN":"试验；做试验","example":"English kept both the noun and the verb.","exampleCN":"英语把名词与动词都保留了下来。"},{"word":"experimental","structure":"experiment plus -al","meaning":"relating to an experiment","meaningCN":"与实验有关的","example":"The adjective marks the treated side of a study.","exampleCN":"这个形容词标出研究中接受处理的一边。"},{"word":"experimentally","structure":"experimental plus -ly","meaning":"by means of experiment","meaningCN":"以实验方式","example":"The adverb describes how a claim was tested.","exampleCN":"这个副词描述一个说法是怎样被检验的。"},{"word":"experimentation","structure":"experiment plus -ation","meaning":"the practice of experimenting","meaningCN":"实验活动","example":"The suffix names the activity rather than one trial.","exampleCN":"后缀指活动，而不是单次试验。"},{"word":"groupe","structure":"French noun","meaning":"a cluster; a set","meaningCN":"一团；一组","example":"The French word supplies the second half.","exampleCN":"这个法语词提供后半部分。"},{"word":"gruppo","structure":"Italian noun","meaning":"a knot; a cluster","meaningCN":"结；一团","example":"The Italian source pictures things tied together.","exampleCN":"意大利语源头画出事物被系在一起的样子。"}],"latinEntries":[{"word":"experimentum","structure":"experimentum, experimenti (n., second declension)","meaning":"trial; test; proof","meaningCN":"试验；检验；证明"},{"word":"experiri","structure":"experior, expertus sum (v., deponent)","meaning":"to try; to test","meaningCN":"尝试；检验"},{"word":"periri","structure":"Latin verb root","meaning":"to attempt; to risk","meaningCN":"尝试；冒险"}],"derivatives":[{"word":"experiment","pos":"n./v.","zh":"实验；做实验"},{"word":"experimental","pos":"adj.","zh":"实验的"},{"word":"experimentally","pos":"adv.","zh":"以实验方式"},{"word":"experimentation","pos":"n.","zh":"实验活动"},{"word":"experimenter","pos":"n.","zh":"实验者"},{"word":"group","pos":"n./v.","zh":"组；分组"}]}},{"word":"sample","ipa_uk":"/ˈsɑːmpl/","ipa_us":"/ˈsæmpl/","definition_zh":"样本；样品；标本；抽样；品尝；试用体验","definition_en":"a small part or quantity taken from a larger whole to show what the whole is like","core_image":"一只装满谷物的大桶旁，长勺舀出一小撮倒进透明小袋，袋口扎紧贴上手写标签","scene":"粮仓里一只大桶装着谷物，检验员用长勺舀出一小撮倒进透明小袋，袋口扎紧后送去化验。The inspector took a sample from the top of the silo before the grain was loaded.","sceneCN":"这里指从大批货物里取出的一小份检验用料（第 1 个义项：从总体中取出的、用来代表整体的一小部分）；句意为检验员在装车之前从筒仓顶部取了一份样本。图中可辨识物件：大桶、长勺、透明小袋、标签。","pos":[{"tag":"n.","zh":"样本；样品；标本"},{"tag":"v.","zh":"抽样；取样；品尝；试用"},{"tag":"adj.","zh":"样品的；抽样的"}],"collocations":[{"phrase":"random sample","zh":"随机样本"},{"phrase":"representative sample","zh":"代表性样本"},{"phrase":"blood sample","zh":"血样"},{"phrase":"sample survey","zh":"抽样调查"},{"phrase":"free sample","zh":"免费样品"},{"phrase":"sample collection","zh":"样本采集"},{"phrase":"soil sample","zh":"土壤样本"}],"forms":[{"label":"单数","form":"sample"},{"label":"复数","form":"samples"},{"label":"过去式","form":"sampled"},{"label":"现在分词","form":"sampling"},{"label":"名词（取样者或采样器）","form":"sampler"},{"label":"形容词（抽样的）","form":"sampled"}],"derivatives":[{"word":"sampling","pos":"n.","zh":"抽样；采样"},{"word":"sampler","pos":"n.","zh":"采样器；品尝者"},{"word":"sampled","pos":"adj.","zh":"取样的；被抽样的"},{"word":"resample","pos":"v.","zh":"重新采样"},{"word":"subsample","pos":"n./v.","zh":"子样本；二次抽样"},{"word":"oversample","pos":"v.","zh":"过度抽样"}],"senses":[{"no":"01","title":"A part that stands for the whole","titleCN":"代表整体的一小部分","definition":"a small part taken from a larger whole so that the whole can be judged from it","definitionCN":"从较大整体中取出的一小部分，用以判断整体","example":"A sample of two hundred voters predicted the national result.","exampleCN":"两百名选民构成的样本预测了全国结果。","why":"The word is a clipped form of example, and an example is a part taken out to show the rest.","whyCN":"这个词是「例子」一词的缩略，而例子正是取出来以显示其余的一小部分。"},{"no":"02","title":"A specimen sent for testing","titleCN":"送去检验的样品","definition":"a portion of material taken from a larger quantity and sent to be tested","definitionCN":"从大量物质中取出、送去检验的一份","example":"The lab received a sample of the river water every hour.","exampleCN":"实验室每小时收到一份河水样品。","why":"Industry and inspection needed a word for the portion that travels to the bench.","whyCN":"工业与检验需要一个词来指被送到实验台前的那一份。"},{"no":"03","title":"A medical specimen","titleCN":"医学标本","definition":"a small quantity of blood, tissue or other material taken from a patient for analysis","definitionCN":"从病人身上取出、供分析用的一小份血液、组织或其他物质","example":"The nurse sent a blood sample to the laboratory.","exampleCN":"护士把一份血样送到实验室。","why":"Medicine narrowed the general word to the body, where a small portion must speak for the patient.","whyCN":"医学把这个一般词收窄到身体上，那里一小份必须替病人说话。"},{"no":"04","title":"A free trial portion","titleCN":"免费试用的小份","definition":"a small portion of a product given to a customer to try","definitionCN":"给顾客试用的一小份产品","example":"The bakery gave a free sample of the new bread.","exampleCN":"面包店给了新面包的免费样品。","why":"Commerce uses the oldest logic of the word: a little of the thing must sell the rest.","whyCN":"商业用的是这个词最古老的逻辑：一点点东西要为其余部分招徕买主。"},{"no":"05","title":"The set of people surveyed","titleCN":"被调查的那批人","definition":"the set of people or cases chosen for a survey, seen as a body","definitionCN":"为调查选出的一批人或案例，作为一个整体看待","example":"The survey sample included people from every district.","exampleCN":"调查样本包括了来自每个区的人。","why":"Once a part is chosen, the part itself becomes a countable body with its own size.","whyCN":"一旦选出某一部分，这部分本身就成为一个有规模的可数群体。"},{"no":"06","title":"To take a portion","titleCN":"抽取样本","definition":"to take a small part from a whole for testing or study","definitionCN":"从整体中取出一小部分用于检验或研究","example":"We sample the soil at ten points across the field.","exampleCN":"我们在田里选十个点取土壤样本。","why":"The noun turned into a verb without changing its picture: a portion is taken out.","whyCN":"名词转成动词，画面没变：取出一份。"},{"no":"07","title":"To taste a little","titleCN":"尝一小口","definition":"to taste a small amount of food or drink to judge it","definitionCN":"尝少量食物或饮料以作判断","example":"She will sample the soup before serving it.","exampleCN":"上汤之前她会先尝一口。","why":"A cook takes a spoonful as a sample, so the verb widened from testing to tasting.","whyCN":"厨师舀一勺当作样品，动词于是从检验扩展到品尝。"},{"no":"08","title":"To try something for a while","titleCN":"试用一段时间","definition":"to use or experience something for a limited period before deciding","definitionCN":"在决定之前有限期地使用或体验某物","example":"New users can sample the software for thirty days.","exampleCN":"新用户可以试用这款软件三十天。","why":"A free portion is a trial in time as well as in quantity.","whyCN":"免费的一份既是数量上的，也是时间上的试用。"},{"no":"09","title":"A reused piece of sound","titleCN":"被借用的音频片段","definition":"a short piece of recorded sound taken from one recording and used in another","definitionCN":"从一段录音中取出、用到另一段录音里的短小声音片段","example":"The track opens with a sample of an old speech.","exampleCN":"这首曲子以一段旧演讲的采样开头。","why":"Digital music borrowed the word because a snippet is literally cut from a larger recording.","whyCN":"数字音乐借这个词，因为片段确实是从较长录音里剪下来的。"}],"etymology":{"intro":{"en":"Sample is a clipped form of example, from Old French essample and Latin exemplum, something taken out. The statistical and audio senses are later extensions of the same picture. The word's source is clear; only the date of its first English record is uncertain.","cn":"这个词是「例子」一词的缩略形式，来自古法语 essample 与拉丁 exemplum，意为「取出来的东西」。统计义与音频义都是同一画面的后起延伸。词源清楚，只有最早英语书面记录的年代不确定。"},"items":[{"era":"LATIN EXIMERE","en":"Eximere joined ex- out and emere to take, giving the picture of something taken out of a larger stock.","cn":"拉丁语 eximere 由意为「出」的前缀与意为「取」的词根合成，画出从大量存货中取出一份的画面。"},{"era":"LATIN EXEMPLUM","en":"Exemplum meant a sample, a pattern or a copy, and it also gave English example.","cn":"拉丁语 exemplum 指样本、范型或副本，也衍生出英语里表示「例子」的词。"},{"era":"OLD FRENCH ESSAMPLE","en":"Old French essample carried the word to English, where the first syllable was dropped in everyday speech.","cn":"古法语 essample 把词带到英语，日常口语里又丢掉了第一个音节。"},{"era":"MIDDLE ENGLISH SAMPLE","en":"The clipped form sample is recorded from the Middle English period; the exact date of its first record is uncertain.","cn":"缩略后的形式在中古英语时期已有记录，但首次记录的确切年代不确定。"},{"era":"STATISTICAL SAMPLE","en":"Statistics gave the word its modern technical weight in the nineteenth and twentieth centuries.","cn":"统计学在十九至二十世纪给了这个词现代技术上的分量。"},{"era":"AUDIO SAMPLE","en":"In the late twentieth century the same word named a snippet of recorded sound reused in a new track.","cn":"二十世纪后期，同一个词又指一段被重复使用的录音片段。"}]},"similar":{"note":{"en":"The first group looks or sounds like sample; the second group names portions and examples in the same field.","cn":"第一组在形音上与「本词」相近；第二组是同一领域里表示「一份、一例」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"example","ipa":"/ɪɡˈzɑːmpl/","tag":"same source","definition":"The fuller word from which sample was clipped; a case that shows a rule.","definitionCN":"sample 所由缩略的完整词；显示规则的一个例子。"},{"word":"sampling","ipa":"/ˈsɑːmplɪŋ/","tag":"same root","definition":"The act or method of taking samples.","definitionCN":"取样的行为或方法。"},{"word":"sampler","ipa":"/ˈsɑːmplə/","tag":"same root","definition":"A device or person that takes samples, or a collection of samples.","definitionCN":"取样器、取样者，或样品集。"},{"word":"specimen","ipa":"/ˈspesɪmən/","tag":"near form","definition":"An individual item taken as an example of its kind, often for science.","definitionCN":"作为同类范例取出的单个样本，多用于科学。"},{"word":"same","ipa":"/seɪm/","tag":"different root","definition":"Identical; it merely looks close and is not related to sample.","definitionCN":"相同的；只是形近，与 sample 并无关联。"}]},{"heading":"NEAR MEANING","entries":[{"word":"specimen","ipa":"/ˈspesɪmən/","tag":"near meaning","definition":"A single item used to represent a group, especially in biology.","definitionCN":"用来代表一类事物的单个样本，尤用于生物学。"},{"word":"swatch","ipa":"/swɒtʃ/","tag":"near meaning","definition":"A small piece of cloth shown as a sample of the whole bolt.","definitionCN":"从整匹布上取下一小块作样品。"},{"word":"excerpt","ipa":"/ˈeksɜːpt/","tag":"near meaning","definition":"A short passage taken from a longer text.","definitionCN":"从较长文本中取出的一小段。"},{"word":"trial","ipa":"/ˈtraɪəl/","tag":"near meaning","definition":"A short period of use to see whether something suits.","definitionCN":"短期试用，以判断是否合适。"},{"word":"instance","ipa":"/ˈɪnstəns/","tag":"near meaning","definition":"A single case that illustrates a general pattern.","definitionCN":"说明一般模式的单个事例。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real clipping from example, the real Latin picture and real fixed phrases.","cn":"正常联想使用从「例子」一词缩略而来的真实路径、真实的拉丁画面与真实固定搭配。"},"normal":[{"en":"Sample is example with the first syllable dropped, so a sample is a small example of the whole.","cn":"sample 是丢掉了首音的 example，所以样本就是整体的一小份例子。"},{"en":"Latin exemplum came from eximere, to take out, and every sense keeps that picture of taking a portion.","cn":"拉丁 exemplum 来自 eximere「取出」，每个义项都保留「取出一份」的画面。"},{"en":"Fixed phrases include random sample, representative sample and blood sample.","cn":"固定说法有随机样本、代表性样本与血样。"},{"en":"A cook samples soup, a customer samples bread, and both take a little to judge the rest.","cn":"厨师尝汤、顾客尝面包，都是取一点来判断其余。"},{"en":"Digital music calls a reused snippet a sample because it is cut from a longer recording.","cn":"数字音乐把重复使用的片段叫作采样，因为它从较长录音里剪下。"}],"abstract":[{"en":"A sample is a promise that a small part can speak for a large whole.","cn":"样本是一个承诺：一小部分可以替整体说话。"},{"en":"The spoonful is not the soup, yet it tells you what the pot tastes like.","cn":"一勺不是整锅汤，却能告诉你锅里的味道。"},{"en":"Every sample is an act of trust in the part, and a risk about the whole.","cn":"每次取样都是对部分的信任，也是对整体的冒险。"}]},"examples":[{"en":"The clinic stores every sample in a sealed tube.","cn":"诊所把每份样本存放在密封管里。"},{"en":"A sample taken only from the front row would mislead the survey.","cn":"只从第一排取的样本会误导调查。"},{"en":"The band built its first track from a sample of a street recording.","cn":"乐队用一段街头录音的采样做成了第一首曲子。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「三普」——从一大堆里舀出一小份给大家看：样本","word":"sample"},"root":"该词是「例子」一词的缩略，源自拉丁 exemplum「样本、范型、副本」，更早来自 eximere「取出」（前缀意为「出」加词根意为「取」）；经古法语 essample 进入英语。统计抽样义在十九至二十世纪随统计学通行，音频采样义为二十世纪后期新义；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Nine senses follow one taken portion: a statistical sample, a tested specimen, a medical specimen, a free trial portion, a survey set, the act of taking, tasting, trying for a while, and finally a reused piece of sound.","cn":"九个义项跟着同一份「取出来的部分」：统计样本、送检样品、医学标本、免费试用份、调查对象集合、取样动作、品尝、试用一段时间，最后是被借用的音频片段。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long spoon lifts one small scoop from a full barrel and seals it in a clear bag.","cn":"核心意象：长勺从满桶里舀出一小撮，封进透明小袋。"},"chain":["TAKEN PORTION","SPECIMEN","MEDICAL SPECIMEN","TRIAL PORTION","SURVEY SET","REUSED SNIPPET"],"branches":[{"senses":"01 · 06","en":"THE PART AND THE ACT: a portion stands for the whole, and the verb names taking that portion.","cn":"部分与动作：一份代表整体，动词则指取出这一份。"},{"senses":"02 · 03","en":"THE BENCH AND THE BODY: material sent for testing and blood or tissue taken from a patient.","cn":"实验台与身体：送去检验的材料，以及从病人身上取出的血或组织。"},{"senses":"04 · 07 · 08","en":"THE LITTLE TRIAL: a free portion, a taste, and a limited period of use all test before commitment.","cn":"小小的试用：免费的一份、尝一口与限期使用，都在承诺之前先试一试。"},{"senses":"05","en":"THE CHOSEN BODY: the selected respondents become a countable set with a size of its own.","cn":"被选出的群体：被选中的受访者成为一个有自身规模的可数集合。"},{"senses":"09","en":"THE CUT SOUND: a recorded snippet is lifted from one track and placed in another.","cn":"剪下的声音：一段录音从一首曲子里取出，放进另一首。"}]},"affixes":{"intro":{"en":"Sample is a clipped form of a Latin loanword, so its affix story is the story of exemplum, eximere and emere.","cn":"sample 是一个拉丁借词的缩略形式，因此它的词缀故事就是 exemplum、eximere 与 emere 的故事。"},"latinIntro":{"en":"Latin exemplum, eximere and emere all belong to the same taking picture; the English clipping hides the first syllable.","cn":"拉丁 exemplum、eximere 与 emere 都属于同一个「取出」画面；英语的缩略把第一个音节藏了起来。"},"items":[{"word":"exemplum","structure":"Latin noun, second declension","meaning":"a sample; a pattern","meaningCN":"样本；范型","example":"The Latin noun is the direct ancestor of the English word.","exampleCN":"这个拉丁名词是英语词的直系祖先。"},{"word":"eximere","structure":"ex- out plus emere take","meaning":"to take out","meaningCN":"取出","example":"The verb supplies the physical picture of the word.","exampleCN":"这个动词提供这个词的身体画面。"},{"word":"emere","structure":"Latin verb, third conjugation","meaning":"to take; to buy","meaningCN":"取；买","example":"Buying and taking share one Latin verb.","exampleCN":"「买」与「取」在拉丁语里共用一个动词。"},{"word":"essample","structure":"Old French noun","meaning":"an example; a sample","meaningCN":"例子；样本","example":"French passed the word to English.","exampleCN":"法语把这个词传给了英语。"},{"word":"sample","structure":"English clipping of example","meaning":"a taken portion","meaningCN":"取出的一份","example":"The clipping dropped the first syllable.","exampleCN":"缩略丢掉了第一个音节。"},{"word":"sampling","structure":"sample plus -ing","meaning":"the act of taking samples","meaningCN":"取样；抽样","example":"The suffix turns the act into a method and a field.","exampleCN":"后缀把动作变成方法与领域。"},{"word":"sampler","structure":"sample plus -er","meaning":"one who or that which samples","meaningCN":"取样者；采样器","example":"The agent suffix names the tool or the person.","exampleCN":"施动后缀指工具或人。"},{"word":"resample","structure":"re- again plus sample","meaning":"to take a new sample","meaningCN":"重新取样","example":"The prefix marks a second taking.","exampleCN":"前缀标出第二次取样。"},{"word":"subsample","structure":"sub- under plus sample","meaning":"a sample drawn from a sample","meaningCN":"从样本中再取的子样本","example":"The prefix marks a portion of a portion.","exampleCN":"前缀标出「一份中的一份」。"}],"latinEntries":[{"word":"exemplum","structure":"exemplum, exempli (n., second declension)","meaning":"sample; pattern; copy","meaningCN":"样本；范型；副本"},{"word":"eximere","structure":"eximo, exemi, exemptum (v., third conjugation)","meaning":"to take out; remove","meaningCN":"取出；拿走"},{"word":"emere","structure":"emo, emi, emptum (v., third conjugation)","meaning":"to take; buy","meaningCN":"取；买"}],"derivatives":[{"word":"sampling","pos":"n.","zh":"抽样；采样"},{"word":"sampler","pos":"n.","zh":"采样器；品尝者"},{"word":"resample","pos":"v.","zh":"重新采样"},{"word":"subsample","pos":"n./v.","zh":"子样本；二次抽样"},{"word":"oversample","pos":"v.","zh":"过度抽样"},{"word":"example","pos":"n.","zh":"例子；范例"}]}},{"word":"sampling","ipa_uk":"/ˈsɑːmplɪŋ/","ipa_us":"/ˈsæmplɪŋ/","definition_zh":"抽样；采样；抽样方法；抽样调查活动；音频与信号采样","definition_en":"the process or method of taking samples from a larger whole","core_image":"一张方格地图铺在田埂上，每面小旗代表从一块田里随机取土的一个点","scene":"田埂上铺着一张方格地图，农技员按格子随机插上小旗，再从每面旗所在的位置取一撮土装进袋子。Sampling began before sunrise, when the dew still lay on the leaves.","sceneCN":"这里指按一定方法从整体中抽取样本的过程（第 1 个义项：从较大整体中抽取样本的方法）；句意为抽样在天亮之前就开始了，叶子上还挂着露水。图中可辨识物件：方格地图、小旗、取土袋、记录板。","pos":[{"tag":"n.","zh":"抽样；采样；抽样方法；抽样活动"}],"collocations":[{"phrase":"random sampling","zh":"随机抽样"},{"phrase":"stratified sampling","zh":"分层抽样"},{"phrase":"sampling method","zh":"抽样方法"},{"phrase":"sampling error","zh":"抽样误差"},{"phrase":"sampling frame","zh":"抽样框"},{"phrase":"water sampling","zh":"水质采样"},{"phrase":"sampling rate","zh":"采样率"}],"forms":[{"label":"不可数名词","form":"sampling"},{"label":"动词（取样）","form":"sample"},{"label":"名词（样本）","form":"sample"},{"label":"名词（采样器）","form":"sampler"},{"label":"形容词（被抽样的）","form":"sampled"},{"label":"复合形式（抽样框）","form":"sampling frame"}],"derivatives":[{"word":"sample","pos":"n./v.","zh":"样本；取样"},{"word":"sampler","pos":"n.","zh":"采样器；取样者"},{"word":"resampling","pos":"n.","zh":"重采样"},{"word":"subsampling","pos":"n.","zh":"二次抽样；子采样"},{"word":"oversampling","pos":"n.","zh":"过采样；过度抽样"}],"senses":[{"no":"01","title":"The statistical method","titleCN":"统计上的抽样方法","definition":"the method of choosing a part of a population so that conclusions can be drawn about the whole","definitionCN":"从总体中选出一部分、以便对整体下结论的方法","example":"Random sampling gives every member of the population a known chance.","exampleCN":"随机抽样让总体中的每个成员都有已知的被抽中机会。","why":"Sample was a portion taken out, and the ending turns that action into a repeatable method.","whyCN":"词根义为被取出的一份，后缀把这个动作变成可重复的方法。"},{"no":"02","title":"The act of taking one sample","titleCN":"取一次样的动作","definition":"one instance or occasion of taking a portion for testing or study","definitionCN":"为检验或研究取出某一份的一次动作或场合","example":"Sampling took longer than the test itself.","exampleCN":"取样花的时间比检验本身还长。","why":"The ending also names a single act, not only the method in general.","whyCN":"这个后缀也指单次动作，而不只是笼统的方法。"},{"no":"03","title":"The survey built on samples","titleCN":"建立在样本上的调查","definition":"a survey that studies a chosen part of a population instead of counting everyone","definitionCN":"只研究总体中被选出一部分人、而非清点全部人的调查","example":"The survey relied on sampling rather than on a full count.","exampleCN":"这项调查依靠抽样，而不是全面清点。","why":"Once the method names an activity, the activity can be spoken of as a kind of survey.","whyCN":"方法一旦命名一种活动，这种活动就可以被说成一种调查。"},{"no":"04","title":"Field collection of material","titleCN":"野外的实物采样","definition":"the collection of water, soil, air or plant material at a site for later analysis","definitionCN":"在某一地点采集水、土、空气或植物材料供日后分析","example":"Water sampling at the outflow is done twice a week.","exampleCN":"出水口的水质采样每周做两次。","why":"Environmental science uses the word for the physical gathering, because the portion must be carried away.","whyCN":"环境科学用这个词指实物的采集，因为那一份必须被带走。"},{"no":"05","title":"Spot checks in production","titleCN":"生产中的抽检","definition":"the inspection of a few items from a batch to judge the whole batch","definitionCN":"从一批产品里抽取少数几件检查，以判断整批","example":"Sampling of the finished bolts caught the faulty batch.","exampleCN":"对成品螺栓的抽检抓出了那批次品。","why":"Factories apply the same logic as surveys, but the members of the batch are objects.","whyCN":"工厂用的逻辑与调查相同，只是这批「成员」是物件。"},{"no":"06","title":"Audio sampling","titleCN":"音频采样","definition":"the reuse of short recorded fragments in a new piece of music","definitionCN":"在新音乐作品里重复使用短小录音片段","example":"The producer used sampling to rebuild the old chorus.","exampleCN":"制作人用采样重建了那段旧合唱。","why":"A recorded fragment is a portion cut from a longer recording, so music kept the old word.","whyCN":"录音片段是从较长录音里剪下的一份，音乐因此沿用旧词。"},{"no":"07","title":"Signal sampling","titleCN":"信号采样","definition":"the regular measurement of a continuous signal at short intervals so that it can be stored digitally","definitionCN":"按很短的时间间隔对连续信号反复测量，以便数字化存储","example":"Digital sampling turns a smooth wave into a series of numbers.","exampleCN":"数字采样把平滑的波变成一串数字。","why":"Engineering takes portions of time instead of portions of material, and the word stretches to fit.","whyCN":"工程取的是时间上的一份，而不是材料上的一份，词义随之伸展。"},{"no":"08","title":"The subject of a course","titleCN":"作为课程内容的抽样","definition":"the branch of statistics that studies how samples are chosen and what they can prove","definitionCN":"统计学中研究样本如何选取、能证明什么的分支","example":"The course begins with sampling and moves on to inference.","exampleCN":"这门课从抽样讲起，再进入推断。","why":"Any repeatable method can become a subject, and this one became a standard chapter of statistics.","whyCN":"任何可重复的方法都能成为一门科目，而这一方法成了统计学的标准章节。"}],"etymology":{"intro":{"en":"Sampling is sample plus the English noun ending -ing. Sample itself is a clipped form of example, from Latin exemplum. The word's source is clear; only the date of its first record in each technical sense is uncertain.","cn":"这个词由「样本」一词加名词化后缀构成，而该词本身是「例子」一词的缩略，来自拉丁 exemplum。词源清楚，只是各个技术义项最早记录的年代不确定。"},"items":[{"era":"LATIN EXEMPLUM","en":"Exemplum meant a sample or pattern, from eximere to take out; it is the remote source of sample.","cn":"exemplum 指样本或范型，来自 eximere「取出」，是「样本」一词的远源。"},{"era":"MIDDLE ENGLISH SAMPLE","en":"The clipped English form sample is recorded in the Middle English period, with the first date uncertain.","cn":"缩略的英语形式在中古英语时期已有记录，首次年代不确定。"},{"era":"THE ENDING -ING","en":"The Old English noun ending -ing turns a verb or noun into the name of an activity or its result.","cn":"古英语的名词化后缀把动词或名词变成活动或其结果的名称。"},{"era":"STATISTICAL SAMPLING","en":"Statistical sampling took shape in the nineteenth and twentieth centuries, when surveys began to rely on chosen parts rather than full counts.","cn":"统计抽样在十九至二十世纪成形，调查开始依靠选出的部分而不是全数清点。"},{"era":"SIGNAL AND AUDIO","en":"Twentieth-century engineering and music gave sampling the senses of regular signal measurement and reused recorded fragments; the first dates of these uses are uncertain.","cn":"二十世纪的工程与音乐给了这个词定期测量信号与重复使用录音片段这两个义项；这些用法的起始年代不确定。"},{"era":"THE PHRASE SAMPLING FRAME","en":"Modern survey work added fixed compounds such as sampling frame and sampling error.","cn":"现代调查工作又添上「抽样框」「抽样误差」这类固定复合词。"}]},"similar":{"note":{"en":"The first group looks or sounds like sampling; the second names related steps in a study.","cn":"第一组在形音上与「本词」相近；第二组是研究里相邻的步骤。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sample","ipa":"/ˈsɑːmpl/","tag":"same root","definition":"The noun for the portion taken and the verb for taking it.","definitionCN":"指取出的那一份，也指取这份的动作。"},{"word":"sampler","ipa":"/ˈsɑːmplə/","tag":"same root","definition":"A device, person or collection that takes or holds samples.","definitionCN":"取样器、取样者，或样品集。"},{"word":"sampled","ipa":"/ˈsɑːmpld/","tag":"same root","definition":"The adjective for material that has been taken as a sample.","definitionCN":"指已被取作样本的材料。"},{"word":"same","ipa":"/seɪm/","tag":"different root","definition":"Identical; it only looks close and is unrelated.","definitionCN":"相同的；只是形近，并无关联。"},{"word":"sampling frame","ipa":"/ˈsɑːmplɪŋ freɪm/","tag":"compound","definition":"The list or map from which a sample is drawn.","definitionCN":"抽取样本所依据的名单或范围。"}]},{"heading":"NEAR MEANING","entries":[{"word":"selection","ipa":"/sɪˈlekʃn/","tag":"near meaning","definition":"The act of choosing the cases that will be studied.","definitionCN":"挑选将被研究的案例的行为。"},{"word":"collection","ipa":"/kəˈlekʃn/","tag":"near meaning","definition":"The gathering of material or data, often in the field.","definitionCN":"在实地收集材料或数据。"},{"word":"survey","ipa":"/ˈsɜːveɪ/","tag":"near meaning","definition":"A study that asks a chosen set of people for information.","definitionCN":"向选出一批人索取信息的研究。"},{"word":"measurement","ipa":"/ˈmeʒəmənt/","tag":"near meaning","definition":"The act of assigning numbers to observations at intervals.","definitionCN":"按间隔对观测赋予数值的行为。"},{"word":"inspection","ipa":"/ɪnˈspekʃn/","tag":"near meaning","definition":"The checking of a few items to judge a whole batch.","definitionCN":"检查少数几件以判断整批。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real clipping, the real -ing ending and real technical compounds.","cn":"正常联想使用真实的缩略路径、真实的动名词后缀与真实技术复合词。"},"normal":[{"en":"Sampling is sample plus -ing: the activity built on taking portions.","cn":"sampling 是 sample 加 -ing：建立在「取出一份」之上的活动。"},{"en":"Sample goes back to Latin exemplum and eximere, so every sampling keeps the picture of taking out.","cn":"sample 可追到拉丁 exemplum 与 eximere，因此每次抽样都保留「取出」的画面。"},{"en":"Fixed phrases include random sampling, stratified sampling and sampling error.","cn":"固定说法有随机抽样、分层抽样与抽样误差。"},{"en":"Water sampling carries the portion away in a bottle; signal sampling carries away a slice of time.","cn":"水质采样用瓶子带走一份实物；信号采样带走的是一段时间。"},{"en":"A sampling frame is the list from which the choosing starts.","cn":"抽样框就是开始挑选时所依据的名单。"}],"abstract":[{"en":"Sampling is the art of letting a small part carry the weight of the whole.","cn":"抽样是让小部分承担整体重量的技艺。"},{"en":"Every method of choosing is also a method of leaving something out.","cn":"每一种挑选方法，同时也是一种舍弃方法。"},{"en":"The quality of the whole answer depends on how honestly the part was taken.","cn":"整个答案的质量，取决于那一份取得有多诚实。"}]},"examples":[{"en":"Sampling from the top layer alone would miss the heaviest grains.","cn":"只从表层抽样会漏掉最重的谷粒。"},{"en":"The team changed its sampling after the first results looked odd.","cn":"第一批结果显得异常后，团队改换了抽样方式。"},{"en":"Good sampling is invisible in the report and decisive in the conclusion.","cn":"好的抽样在报告里看不见，却对结论起决定作用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「散普令」——把样本散着取、按规矩取：抽样","word":"sampling"},"root":"这个词由「样本」一词加名词化后缀构成。该词是「例子」一词的缩略，源自拉丁 exemplum「样本、范型」，更早来自 eximere「取出」。统计抽样义在十九至二十世纪成形，信号采样与音频采样义为二十世纪发展；词源清楚，各义项最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one taking method: statistical sampling, a single taking, a sample survey, field collection, production spot checks, audio sampling, signal sampling, and finally the subject taught in a statistics course.","cn":"八个义项跟着同一种「取份」方法：统计抽样、单次取样、抽样调查、野外采集、生产抽检、音频采样、信号采样，最后是统计学课程里讲授的这门内容。"},"semanticMap":{"core":{"en":"CORE IMAGE: flags placed by a grid on a field, each flag marking where one small portion of soil is taken.","cn":"核心意象：田里按方格插上小旗，每面旗标出取一小份土的位置。"},"chain":["PORTION TAKING","STATISTICAL METHOD","FIELD COLLECTION","QUALITY CHECK","AUDIO CAPTURE","SIGNAL MEASUREMENT"],"branches":[{"senses":"01 · 08","en":"THE METHOD AND THE COURSE: choosing by rule, and the branch of statistics that teaches the rule.","cn":"方法与课程：按规则挑选，以及讲授这套规则的统计学分支。"},{"senses":"02 · 03","en":"THE ACT AND THE SURVEY: one taking, and the whole study that rests on such takings.","cn":"动作与调查：一次取样，以及建立在这种取样之上的整个研究。"},{"senses":"04","en":"THE FIELD BOTTLE: water, soil and air are carried away for later analysis.","cn":"野外的瓶子：水、土与空气被带走供日后分析。"},{"senses":"05","en":"THE FACTORY CHECK: a few bolts stand for a whole batch on the line.","cn":"工厂的抽检：几颗螺栓替整批产品说话。"},{"senses":"06 · 07","en":"THE TWO DIGITAL TAKINGS: a fragment of recorded sound and a slice of continuous signal.","cn":"两种数字取样：一段录音片段与一段连续信号。"}]},"affixes":{"intro":{"en":"Sampling is an English derivative: a clipped loanword plus the native ending -ing. The Latin list belongs to the base word.","cn":"sampling 是英语派生词：一个缩略借词加上本族后缀 -ing。拉丁词条属于它的基础词。"},"latinIntro":{"en":"The Latin ancestors are exemplum, eximere and emere, all behind the base sample.","cn":"拉丁祖先为 exemplum、eximere 与 emere，都在基础词 sample 背后。"},"items":[{"word":"exemplum","structure":"Latin noun, second declension","meaning":"sample; pattern","meaningCN":"样本；范型","example":"The base word descends from this noun.","exampleCN":"基础词由这个名词传下。"},{"word":"eximere","structure":"ex- out plus emere take","meaning":"to take out","meaningCN":"取出","example":"The verb gives the physical picture of taking a portion.","exampleCN":"这个动词提供「取出一份」的身体画面。"},{"word":"sample","structure":"English clipping of example","meaning":"a taken portion","meaningCN":"取出的一份","example":"The base word is shorter than its source.","exampleCN":"基础词比它的来源短。"},{"word":"-ing","structure":"Old English noun suffix","meaning":"an activity or its result","meaningCN":"活动或其结果","example":"The ending builds sampling, testing and measuring.","exampleCN":"这个后缀构成抽样、检验与测量等词。"},{"word":"sampling","structure":"sample plus -ing","meaning":"the activity of taking samples","meaningCN":"取样的活动","example":"The derived noun names the method.","exampleCN":"派生名词命名这套方法。"},{"word":"sampler","structure":"sample plus -er","meaning":"one who or that which samples","meaningCN":"取样者；采样器","example":"The agent suffix names the tool.","exampleCN":"施动后缀指工具。"},{"word":"resampling","structure":"re- again plus sampling","meaning":"a second round of sampling","meaningCN":"再次抽样","example":"The prefix marks a repeated round.","exampleCN":"前缀标出重复的一轮。"},{"word":"subsampling","structure":"sub- under plus sampling","meaning":"sampling within a sample","meaningCN":"在样本内部再抽样","example":"The prefix marks a level below the first taking.","exampleCN":"前缀标出低于第一次取样的层级。"},{"word":"oversampling","structure":"over- too much plus sampling","meaning":"sampling more than the usual share","meaningCN":"超出常规比例的抽样","example":"The prefix marks an excess of one group.","exampleCN":"前缀标出某一群体的过量。"}],"latinEntries":[{"word":"exemplum","structure":"exemplum, exempli (n., second declension)","meaning":"sample; pattern; copy","meaningCN":"样本；范型；副本"},{"word":"eximere","structure":"eximo, exemi, exemptum (v., third conjugation)","meaning":"to take out; remove","meaningCN":"取出；拿走"},{"word":"emere","structure":"emo, emi, emptum (v., third conjugation)","meaning":"to take; buy","meaningCN":"取；买"}],"derivatives":[{"word":"sample","pos":"n./v.","zh":"样本；取样"},{"word":"sampler","pos":"n.","zh":"采样器；取样者"},{"word":"resampling","pos":"n.","zh":"重采样"},{"word":"subsampling","pos":"n.","zh":"二次抽样"},{"word":"oversampling","pos":"n.","zh":"过采样"}]}},{"word":"sample size","ipa_uk":"/ˈsɑːmpl saɪz/","ipa_us":"/ˈsæmpl saɪz/","definition_zh":"样本量；样本容量；研究中受试者或观测的数量","definition_en":"the number of individuals or observations included in a sample","core_image":"一张摊开的表格上写着各组应收的份数，负责人用手指点着其中一行核对数目","scene":"项目组围着一张大桌子开会，桌上摊着一张列着各组份数的表格，负责人用手指点住其中一行，确认数目后才开始招募。The sample size was fixed at two hundred before the first participant was enrolled.","sceneCN":"这里指样本所包含的个体或观测数量（第 1 个义项：一个样本中包含的个体或观测的数目）；句意为在第一名参与者入组之前，样本量就已定为两百。图中可辨识物件：大桌、份数表格、笔、招募名单。","pos":[{"tag":"n.","zh":"样本量；样本容量"}],"collocations":[{"phrase":"adequate sample size","zh":"足够的样本量"},{"phrase":"sample size calculation","zh":"样本量计算"},{"phrase":"small sample size","zh":"小样本量"},{"phrase":"increase the sample size","zh":"增大样本量"},{"phrase":"effective sample size","zh":"有效样本量"},{"phrase":"sample size determination","zh":"样本量的确定"}],"forms":[{"label":"单数","form":"sample size"},{"label":"复数","form":"sample sizes"},{"label":"相关名词（样本）","form":"sample"},{"label":"相关名词（抽样）","form":"sampling"},{"label":"相关名词（规模）","form":"size"},{"label":"复合形式（样本量计算）","form":"sample size calculation"}],"derivatives":[{"word":"sample","pos":"n./v.","zh":"样本；取样"},{"word":"sampling","pos":"n.","zh":"抽样；采样"},{"word":"size","pos":"n./v.","zh":"规模；按尺寸制作"},{"word":"sizeable","pos":"adj.","zh":"相当大的"},{"word":"sized","pos":"adj.","zh":"有特定尺寸的"},{"word":"oversized","pos":"adj.","zh":"过大的"}],"senses":[{"no":"01","title":"The number in a sample","titleCN":"一个样本里的数目","definition":"the number of individuals or observations that a sample contains","definitionCN":"一个样本所包含的个体或观测的数目","example":"The sample size was fixed at two hundred before the first participant was enrolled.","exampleCN":"在第一名参与者入组之前，样本量就已定为两百。","why":"Size came to mean extent or bulk, and the phrase simply asks how much of a sample there is.","whyCN":"后一词指规模或份量，这个短语问的就是一份样本有多大。"},{"no":"02","title":"The number a study plans for","titleCN":"研究计划中的受试人数","definition":"the number of participants a study design requires or promises to recruit","definitionCN":"研究设计所需要或承诺招募的参与者人数","example":"The protocol states the sample size and the reason for it.","exampleCN":"研究方案写明了样本量以及这样定的理由。","why":"A plan must name a number in advance, so the phrase moved from description to design.","whyCN":"计划必须事先说出一个数目，短语于是从描述转为设计。"},{"no":"03","title":"The capacity in probability","titleCN":"概率论中的样本容量","definition":"the number of units in a sample treated as a quantity in mathematical statistics","definitionCN":"在数理统计中被当作一个量来处理的样本单位数","example":"In probability, the sample size enters every estimate of error.","exampleCN":"在概率论里，样本量进入每一个误差估计。","why":"Mathematics treats the count as a variable, so the phrase can name a symbol as well as a fact.","whyCN":"数学把这个数目当作变量，短语因此也能命名一个符号，而不只是事实。"},{"no":"04","title":"The count left after losses","titleCN":"剔除损耗后的有效数目","definition":"the number of usable cases that remain after missing or invalid data are removed","definitionCN":"在剔除缺失或无效数据之后剩下的可用案例数","example":"After missing forms were removed, the effective sample size fell by a third.","exampleCN":"剔除缺失表格后，有效样本量减少了三分之一。","why":"Real studies lose cases, so the phrase splits into the planned number and the number actually usable.","whyCN":"真实研究总会损失案例，短语于是分成计划数目与实际可用数目。"},{"no":"05","title":"A small study","titleCN":"规模很小的研究","definition":"a study whose small number of cases makes strong conclusions unsafe","definitionCN":"案例数目很少、因而难以支撑强结论的研究","example":"A small sample size makes the graph look certain when it is not.","exampleCN":"样本量小会让图表显得确定，其实并不确定。","why":"The phrase can stand for the study itself when smallness is the point being criticised.","whyCN":"当被批评的重点是规模太小时，这个短语可以代指研究本身。"},{"no":"06","title":"The calculation behind the number","titleCN":"得出数目的计算过程","definition":"the statistical work of deciding how many cases a study needs","definitionCN":"决定一项研究需要多少案例的统计工作","example":"The team used a pilot study to plan the sample size.","exampleCN":"团队用一项预试验来规划样本量。","why":"Once a number must be justified, the calculation that produces it takes the same name.","whyCN":"一旦数目需要理由，产生它的计算也就用了同一个名字。"},{"no":"07","title":"The number too low to answer","titleCN":"低到回答不了问题的数目","definition":"a number of cases too low for the effect being studied to show itself","definitionCN":"案例数目过低，使所研究的效应无法显现","example":"A sample size of ten cannot support such a strong claim.","exampleCN":"十例的样本量支撑不起这么强的结论。","why":"Smallness has a threshold, and below it the phrase turns into a criticism rather than a description.","whyCN":"「小」有一个门槛，低于门槛时，这个短语就变成批评而不是描述。"},{"no":"08","title":"The count tied to statistical power","titleCN":"与统计功效挂钩的数目","definition":"the number of cases needed for a study to detect an effect of a stated size","definitionCN":"为使研究能检出某一既定大小的效应所需的案例数","example":"Power analysis links the sample size to the smallest effect worth detecting.","exampleCN":"功效分析把样本量与值得检出的最小效应联系起来。","why":"Power is a function of numbers, so the phrase became the practical lever for planning a study.","whyCN":"功效是数目的函数，短语因此成了规划研究的实际杠杆。"}],"etymology":{"intro":{"en":"Sample size joins the clipped Latin loanword sample and the French loanword size. The source of both halves is clear; the compound itself is a modern statistical term whose first record date is uncertain.","cn":"这个短语把缩略的拉丁借词「样本」与法语借词「规模」合在一起。两部分的来源都清楚；复合词本身是近现代统计术语，最早记录的年代不确定。"},"items":[{"era":"LATIN EXEMPLUM","en":"Sample descends from exemplum, a sample or pattern, and from eximere, to take out.","cn":"前一词源自 exemplum「样本、范型」，更早来自 eximere「取出」。"},{"era":"OLD FRENCH SISE","en":"Size came from Old French sise, a shortened form of assise, a session or assessment of dimensions.","cn":"后一词来自古法语 sise，是 assise 的缩略，后者指一次评定或对尺寸的核定。"},{"era":"LATIN SEDERE","en":"Assise goes back to asseoir, to sit, and to Latin sedere, because a court or an assessment sits to settle a matter.","cn":"assise 可追到 asseoir「坐」与拉丁语 sedere，因为法庭或评定要坐下来定夺事情。"},{"era":"ENGLISH SIZE","en":"English size is recorded from the fourteenth century with the sense of extent or bulk; the exact first date is uncertain.","cn":"英语里表示规模或份量的这个词自十四世纪起有记录；确切的首见年代不确定。"},{"era":"STATISTICAL PHRASE","en":"Sample size became a fixed term with the growth of statistical design in the nineteenth and twentieth centuries.","cn":"随着十九至二十世纪统计设计的发展，这个短语成为固定术语。"},{"era":"POWER ANALYSIS","en":"Twentieth-century power analysis made the phrase a planning tool rather than a mere description.","cn":"二十世纪的功效分析使它成为规划工具，而不只是描述。"}]},"similar":{"note":{"en":"The first group looks or sounds like sample size; the second group names neighbouring quantities in a study.","cn":"第一组在形音上与「样本量」相近；第二组是研究里相邻的数量说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sample","ipa":"/ˈsɑːmpl/","tag":"same phrase","definition":"The portion itself, whose count the phrase measures.","definitionCN":"指样本本身，短语量的正是它的数目。"},{"word":"sampling","ipa":"/ˈsɑːmplɪŋ/","tag":"same root","definition":"The method by which the counted portion is chosen.","definitionCN":"选出这份被计数样本的方法。"},{"word":"size","ipa":"/saɪz/","tag":"same phrase","definition":"Extent or bulk; the second half of the phrase.","definitionCN":"规模或份量；短语的后一半。"},{"word":"sizeable","ipa":"/ˈsaɪzəbl/","tag":"same root","definition":"Fairly large in extent, a word often used of samples.","definitionCN":"规模相当大的，常用于形容样本。"},{"word":"sized","ipa":"/saɪzd/","tag":"same root","definition":"Having a stated size, as in a well sized sample.","definitionCN":"具有所述规模的，如规模合适的样本。"}]},{"heading":"NEAR MEANING","entries":[{"word":"number of subjects","ipa":"/ˈnʌmbə əv ˈsʌbdʒɪkts/","tag":"near meaning","definition":"The count of participants in a study, stated more plainly.","definitionCN":"研究参与者的数目，说法更直白。"},{"word":"sample","ipa":"/ˈsɑːmpl/","tag":"near meaning","definition":"The chosen set itself, which has a size.","definitionCN":"被选出的那批本身，它有大小。"},{"word":"power","ipa":"/ˈpaʊə/","tag":"near meaning","definition":"The chance of detecting a real effect, which depends on the count.","definitionCN":"检出真实效应的机会，取决于案例数。"},{"word":"study population","ipa":"/ˈstʌdi ˌpɒpjuˈleɪʃn/","tag":"near meaning","definition":"The whole group from which a sample and its size are drawn.","definitionCN":"样本及其数目所由取出的整个群体。"},{"word":"effective sample size","ipa":"/ɪˈfektɪv ˈsɑːmpl saɪz/","tag":"near meaning","definition":"The usable count after losses and weighting.","definitionCN":"经损耗与加权后仍可用的数目。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real halves of the compound, the real statistical term and real fixed phrases.","cn":"正常联想使用复合词两个真实的半、真实的统计术语与真实固定搭配。"},"normal":[{"en":"Sample size is literally the size of the sample: how many units it holds.","cn":"sample size 字面就是样本的规模：它装着多少个单位。"},{"en":"Size came from a word for an assessment that sits down to settle a matter.","cn":"size 来自「坐下来评定一件事」的说法。"},{"en":"Fixed phrases include adequate sample size, effective sample size and sample size calculation.","cn":"固定说法有足够样本量、有效样本量与样本量计算。"},{"en":"A pilot study can suggest the sample size before the main study begins.","cn":"预试验可以在主研究开始前提示样本量。"},{"en":"Power analysis ties the number to the smallest effect worth detecting.","cn":"功效分析把数目与值得检出的最小效应绑在一起。"}],"abstract":[{"en":"Sample size is a promise about how much evidence the study is willing to buy.","cn":"样本量是研究愿意买多少证据的承诺。"},{"en":"Too few cases make a clear answer impossible, however neat the table looks.","cn":"案例太少，无论表格多整齐，都给不出清楚答案。"},{"en":"Every extra case costs time, so the number is always a bargain with reality.","cn":"每多一个案例都要花时间，所以这个数目永远是与现实的讨价还价。"}]},"examples":[{"en":"The sample size was doubled after the first analysis looked weak.","cn":"第一次分析显得薄弱后，样本量被加倍。"},{"en":"A sample size stated in advance protects the study from wishful thinking.","cn":"事先写明样本量，可以保护研究不受一厢情愿之害。"},{"en":"The paper reports the sample size in the first line of its methods.","cn":"论文在方法部分第一行报告了样本量。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「三普赛兹」——样本的尺寸有多大：样本量","word":"sample size"},"root":"前一词源自拉丁 exemplum「样本」，更早为 eximere「取出」；后一词源自法语 sise，为 assise 的缩略，更早来自 asseoir「坐」与拉丁 sedere「坐」。短语 sample size 是十九至二十世纪统计设计的固定术语，词源清楚，最早记录的年代不确定。","sensesIntro":{"en":"Eight senses follow one count: the number in a sample, the number a study plans, the mathematical capacity, the usable count, a small study, the calculation, the number too low to answer, and the count tied to power.","cn":"八个义项跟着同一个数目：样本里的数目、研究计划的数目、数学容量、可用数目、规模很小的研究、得出数目的计算、低到回答不了问题的数目，以及与功效挂钩的数目。"},"semanticMap":{"core":{"en":"CORE IMAGE: a table of quotas on a table, and a finger pressing one row until the number is agreed.","cn":"核心意象：桌上一张份数表，一根手指按住其中一行，直到数目被确认。"},"chain":["COUNT OF UNITS","DESIGN NUMBER","MATHEMATICAL CAPACITY","USABLE COUNT","SMALL CASE","POWER LINK"],"branches":[{"senses":"01 · 02","en":"THE NUMBER AS FACT AND AS PLAN: what a sample holds, and what a study promises to recruit.","cn":"数目作为事实与计划：样本里装了多少，以及研究承诺招募多少。"},{"senses":"03","en":"THE SYMBOL IN PROBABILITY: the count becomes a variable in every error estimate.","cn":"概率里的符号：这个数目在每一个误差估计里成为变量。"},{"senses":"04","en":"THE COUNT THAT SURVIVES: missing cases are removed and the usable number remains.","cn":"留下来的数目：缺失案例被剔除，可用数目留下。"},{"senses":"05 · 07","en":"THE TOO SMALL STUDY: smallness turns the phrase from description into criticism.","cn":"太小的研究：规模小使这个短语从描述变成批评。"},{"senses":"06 · 08","en":"THE PLANNING LEVER: calculation and power analysis decide the number before data arrive.","cn":"规划的杠杆：计算与功效分析在数据到来之前定下数目。"}]},"affixes":{"intro":{"en":"The compound joins an English clipping of a Latin loanword to a French loanword; both halves are free words, and the Latin list covers the sample half only.","cn":"这个复合词把拉丁借词的英语缩略形式与一个法语借词合在一起；两半都是自由词，拉丁词条只覆盖 sample 一半。"},"latinIntro":{"en":"Latin exemplum, eximere and emere stand behind sample; size has no Latin ancestor in its immediate chain beyond sedere.","cn":"拉丁 exemplum、eximere 与 emere 在 sample 背后；size 的直接词链里除 sedere 外没有别的拉丁祖先。"},"items":[{"word":"exemplum","structure":"Latin noun, second declension","meaning":"sample; pattern","meaningCN":"样本；范型","example":"The first half descends from this noun.","exampleCN":"前半部分由这个名词传下。"},{"word":"eximere","structure":"ex- out plus emere take","meaning":"to take out","meaningCN":"取出","example":"The verb supplies the picture behind sample.","exampleCN":"这个动词提供「样本」一词背后的画面。"},{"word":"sample","structure":"English clipping of example","meaning":"a taken portion","meaningCN":"取出的一份","example":"The first half names the portion counted.","exampleCN":"前半部分指被计数的那一份。"},{"word":"sise","structure":"Old French noun","meaning":"assessment; extent","meaningCN":"评定；规模","example":"The second half came through French.","exampleCN":"后半部分经法语而来。"},{"word":"assise","structure":"Old French noun","meaning":"a sitting; a assessment","meaningCN":"一次坐定；一次评定","example":"The longer French form settled dimensions.","exampleCN":"较长的法语形式用来核定尺寸。"},{"word":"sedere","structure":"Latin verb, second conjugation","meaning":"to sit","meaningCN":"坐","example":"A court sits to settle a matter.","exampleCN":"法庭坐下来定夺事情。"},{"word":"size","structure":"English noun and verb","meaning":"extent; to arrange by size","meaningCN":"规模；按大小排列","example":"The second half is an ordinary English word.","exampleCN":"后半部分是一个普通英语词。"},{"word":"-able","structure":"Latin -abilis through French","meaning":"capable of being","meaningCN":"能够被……的","example":"It builds sizeable from size.","exampleCN":"它由「规模」一词构成表示「可观的」形容词。"},{"word":"sample size","structure":"noun compound","meaning":"the count in a sample","meaningCN":"样本中的数目","example":"The compound fixes the two halves into one term.","exampleCN":"复合词把两半固定成一个术语。"}],"latinEntries":[{"word":"exemplum","structure":"exemplum, exempli (n., second declension)","meaning":"sample; pattern","meaningCN":"样本；范型"},{"word":"eximere","structure":"eximo, exemi, exemptum (v., third conjugation)","meaning":"to take out","meaningCN":"取出"},{"word":"sedere","structure":"sedeo, sedi, sessum (v., second conjugation)","meaning":"to sit","meaningCN":"坐"}],"derivatives":[{"word":"sample","pos":"n./v.","zh":"样本；取样"},{"word":"sampling","pos":"n.","zh":"抽样"},{"word":"size","pos":"n./v.","zh":"规模；按尺寸制作"},{"word":"sizeable","pos":"adj.","zh":"相当大的"},{"word":"oversized","pos":"adj.","zh":"过大的"}]}},{"word":"population sample","ipa_uk":"/ˌpɒpjuˈleɪʃn ˈsɑːmpl/","ipa_us":"/ˌpɑːpjuˈleɪʃn ˈsæmpl/","definition_zh":"总体样本；从总体中抽取的样本；人口调查样本；生态学上的种群样本","definition_en":"a sample drawn from a defined population, usually to represent that population","core_image":"一张大网罩住整片湖面，网中取出一小格水草，格子里的小生物被倒进白盘清点","scene":"湖边铺开一张大网覆盖整片水域，研究人员从网中取出一小格水草，把格子里的生物倒进白盘逐一清点。A population sample of a thousand adults was drawn from four provinces.","sceneCN":"这里指从某一总体中抽取、用来代表该总体的样本（第 1 个义项：从既定总体中抽取的样本）；句意为从四个省抽取了一千名成年人构成总体样本。图中可辨识物件：大网、水草格、白盘、计数表。","pos":[{"tag":"n.","zh":"总体样本；人口样本；种群样本"}],"collocations":[{"phrase":"representative population sample","zh":"代表性总体样本"},{"phrase":"random population sample","zh":"随机总体样本"},{"phrase":"population sample survey","zh":"总体样本调查"},{"phrase":"draw a population sample","zh":"抽取总体样本"},{"phrase":"population sample size","zh":"总体样本量"},{"phrase":"large population sample","zh":"大总体样本"}],"forms":[{"label":"单数","form":"population sample"},{"label":"复数","form":"population samples"},{"label":"相关名词（总体）","form":"population"},{"label":"相关名词（样本）","form":"sample"},{"label":"相关名词（抽样）","form":"sampling"},{"label":"复合形式（总体抽样）","form":"population sampling"}],"derivatives":[{"word":"population","pos":"n.","zh":"人口；总体；种群"},{"word":"populate","pos":"v.","zh":"居住于；填充"},{"word":"populous","pos":"adj.","zh":"人口稠密的"},{"word":"sample","pos":"n./v.","zh":"样本；取样"},{"word":"sampling","pos":"n.","zh":"抽样"},{"word":"subpopulation","pos":"n.","zh":"亚群；子总体"}],"senses":[{"no":"01","title":"A part drawn from a defined whole","titleCN":"从既定总体中抽出的一份","definition":"a sample taken from a population that has been defined in advance","definitionCN":"从一个事先界定好的总体中取出的样本","example":"A population sample of a thousand adults was drawn from four provinces.","exampleCN":"从四个省抽取了一千名成年人，构成总体样本。","why":"Population in statistics means the whole set, so the phrase names a part of that whole.","whyCN":"前一词在统计里指整个集合，短语于是指这个整体的一部分。"},{"no":"02","title":"The sample in a census","titleCN":"人口普查里的样本","definition":"a sample used by a census or demographic survey to check or supplement a full count","definitionCN":"人口普查或人口调查用来核对、补充全面清点的样本","example":"The census uses a population sample to check its own totals.","exampleCN":"人口普查用总体样本来核对自己的总数。","why":"The word population kept its everyday sense of people, so the phrase also names a demographic tool.","whyCN":"前一词保留了「人」的日常义，短语因此也指一种人口统计工具。"},{"no":"03","title":"The sample in ecology","titleCN":"生态学里的种群样本","definition":"a set of organisms taken from a population of a species for counting or study","definitionCN":"从一个物种种群中取出、用于计数或研究的一批生物","example":"A population sample of beetles was counted in each meadow.","exampleCN":"每片草甸都对一个甲虫种群样本作了计数。","why":"Biology uses population for a breeding group, so the same phrase serves a meadow as well as a city.","whyCN":"生物学用前一词指繁殖群体，同一个短语因此既能用于草甸，也能用于城市。"},{"no":"04","title":"The sample that mirrors the whole","titleCN":"映照整体的代表性样本","definition":"a sample whose composition reflects the population closely enough for conclusions to be extended","definitionCN":"构成足够接近总体、可把结论向外推的样本","example":"A population sample is useful only when it mirrors the whole.","exampleCN":"总体样本只有映照整体时才有用。","why":"Representation is the point of the phrase, because a part that does not mirror the whole proves little.","whyCN":"代表性正是这个短语的要点，因为不映照整体的一份证明不了什么。"},{"no":"05","title":"The random sample from the whole","titleCN":"从整体中随机抽出的样本","definition":"a population sample obtained by a probability method, so that error can be estimated","definitionCN":"用概率方法取得的总体样本，因而可以估计误差","example":"Only a random population sample allows a margin of error to be stated.","exampleCN":"只有随机总体样本才允许写明误差范围。","why":"Randomness is what turns a part into a measurable representative of the whole.","whyCN":"随机性使一份样本变成可测量的整体代表。"},{"no":"06","title":"The size of such a sample","titleCN":"这种样本的规模","definition":"the number of cases included in a population sample","definitionCN":"一个总体样本所包含的案例数目","example":"The population sample was too small to separate the two regions.","exampleCN":"这个总体样本太小，无法区分两个地区。","why":"Once the sample exists, its count becomes a property that can be discussed on its own.","whyCN":"样本一旦存在，它的数目就成了可以单独讨论的属性。"},{"no":"07","title":"The sample that fails to represent","titleCN":"未能代表整体的样本","definition":"a population sample whose selection makes it unrepresentative of the population it claims to describe","definitionCN":"选取方式使它无法代表所声称总体的总体样本","example":"A population sample taken from one clinic cannot represent the country.","exampleCN":"只从一家诊所取得的总体样本代表不了全国。","why":"The phrase carries an expectation of representation, so its failure becomes a named problem.","whyCN":"短语本身带着代表性的期待，未能代表便成了一种被命名的问题。"},{"no":"08","title":"The sample seen against its target","titleCN":"与目标总体相对的样本","definition":"the sample considered in its relation to the target population it is meant to stand for","definitionCN":"在被拿来代表目标总体的关系中看待的样本","example":"The report compares the population sample with the target population.","exampleCN":"报告把这个总体样本与目标总体作了比较。","why":"Statistics always keeps two sets in view, and the phrase names one of them by its relation.","whyCN":"统计学始终看着两个集合，短语按关系命名其中一个。"}],"etymology":{"intro":{"en":"Population comes from Late Latin populatio and populus, people, while sample is the clipped Latin loanword from exemplum. The compound is modern and its source is clear; the first record date of the phrase is uncertain.","cn":"前一词源自晚期拉丁 populatio 与 populus「人民」，后一词则是来自 exemplum 的缩略借词。复合词是近现代的，来源清楚；短语最早记录的年代不确定。"},"items":[{"era":"LATIN POPULUS","en":"Populus meant the people of a place, and it stands at the head of the whole family.","cn":"populus 指一个地方的人民，是整个词族的头。"},{"era":"LATIN POPULATIO","en":"Classical populatio meant laying waste, while Late Latin populationem also meant a people or multitude; the two uses are not the same word in sense.","cn":"古典拉丁语 populatio 指蹂躏，晚期拉丁语 populationem 又指一群人、众多；两种用法在语义上并不是同一个词。"},{"era":"FRENCH POPULACION","en":"Old French populacion brought the word to English with the sense of a people or a inhabited region.","cn":"古法语 populacion 把这个词带进英语，义为一方人民或有人居住的地区。"},{"era":"LATIN EXEMPLUM","en":"Sample descends from exemplum, a sample or pattern, through the clipping of example.","cn":"后一词源自 exemplum「样本、范型」，经由「例子」一词的缩略而来。"},{"era":"STATISTICAL POPULATION","en":"Statistics widened population from people to any defined set of units, which made the phrase population sample possible.","cn":"统计学把前一词从人扩展到任何界定好的单位集合，这才使这个短语成立。"},{"era":"THE PHRASE","en":"Population sample became a standard term with modern survey and ecological sampling; its first recorded use is date uncertain.","cn":"这个短语随现代调查与生态抽样成为标准术语；其最早书面用例的年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like population sample; the second group names neighbouring ideas about representing a whole.","cn":"第一组在形音上与「总体样本」相近；第二组是「代表整体」这一意思附近的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"population","ipa":"/ˌpɒpjuˈleɪʃn/","tag":"same phrase","definition":"The whole set from which the sample is drawn, or the people living in a place.","definitionCN":"样本所由取出的整个集合，或居住在某地的人民。"},{"word":"populate","ipa":"/ˈpɒpjuleɪt/","tag":"same root","definition":"To fill a place with people or with data.","definitionCN":"使人居住于某地，或用数据填满。"},{"word":"populous","ipa":"/ˈpɒpjələs/","tag":"same root","definition":"Crowded with people; a description of a place, not a sample.","definitionCN":"人口稠密的；形容地方，不形容样本。"},{"word":"sample","ipa":"/ˈsɑːmpl/","tag":"same phrase","definition":"The part taken from the whole; the second half of the phrase.","definitionCN":"从整体中取出的一份；短语的后一半。"},{"word":"sampling","ipa":"/ˈsɑːmplɪŋ/","tag":"same root","definition":"The method by which such a part is chosen.","definitionCN":"选出这样一份样本的方法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"representative sample","ipa":"/ˌreprɪˈzentətɪv ˈsɑːmpl/","tag":"near meaning","definition":"A sample whose make-up matches the population it stands for.","definitionCN":"构成与所代表总体相符的样本。"},{"word":"random sample","ipa":"/ˈrændəm ˈsɑːmpl/","tag":"near meaning","definition":"A sample in which every unit has a known chance of being chosen.","definitionCN":"每个单位都有已知被抽中机会的样本。"},{"word":"survey sample","ipa":"/ˈsɜːveɪ ˈsɑːmpl/","tag":"near meaning","definition":"The set of respondents chosen for a survey.","definitionCN":"为调查选出的那批受访者。"},{"word":"cohort","ipa":"/ˈkəʊhɔːt/","tag":"near meaning","definition":"A group followed over time, often a part of a larger population.","definitionCN":"随时间被追踪的一组人，常是较大总体的一部分。"},{"word":"census sample","ipa":"/ˈsensəs ˈsɑːmpl/","tag":"near meaning","definition":"A sample used to check or supplement a full census.","definitionCN":"用于核对或补充全面普查的样本。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Late Latin source of population, the real clipping behind sample and real survey terms.","cn":"正常联想使用「人口」一词真实的晚期拉丁来源、「样本」一词真实的缩略路径与真实调查术语。"},"normal":[{"en":"Population came from populus, the people, and statistics widened it to any defined whole.","cn":"population 来自 populus「人民」，统计学又把它扩展到任何界定好的整体。"},{"en":"Population sample is the part drawn from that whole, and the phrase keeps both ends in view.","cn":"population sample 就是从那个整体里取出的一份，短语同时看着两端。"},{"en":"Fixed phrases include random population sample and population sample survey.","cn":"固定说法有随机总体样本与总体样本调查。"},{"en":"In ecology the same phrase counts beetles in a meadow instead of voters in a country.","cn":"在生态学里，同一个短语数的是草甸上的甲虫，而不是全国的选民。"},{"en":"Representation is the test: a part that does not mirror the whole proves little.","cn":"代表性就是考验：不映照整体的一份证明不了什么。"}],"abstract":[{"en":"A population sample is a small window cut into a very large room.","cn":"总体样本是在一间大屋子上开的一扇小窗。"},{"en":"What you see through the window depends on where the window was cut.","cn":"从窗口看到什么，取决于窗口开在哪里。"},{"en":"The phrase holds two sets at once: the whole that is claimed and the part that is actually seen.","cn":"这个短语同时握着两个集合：被声称的整体与真正被看见的部分。"}]},"examples":[{"en":"A population sample drawn from volunteers will flatter the survey.","cn":"从志愿者中抽出的总体样本会让调查结果偏好看。"},{"en":"The ecologist counted a population sample in every meadow.","cn":"生态学家在每片草甸都统计了一个种群样本。"},{"en":"The report warns that the population sample covers only coastal towns.","cn":"报告提醒说，这个总体样本只覆盖沿海城镇。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「总体三普」——从全体里取出一小份：总体样本","word":"population sample"},"root":"前一词源自拉丁 populus「人民」，经晚期拉丁 populatio 与古法语 populacion 进入英语，统计学又把它扩展为任何界定好的整体；后一词是「例子」一词的缩略，源自拉丁 exemplum「样本」。短语 population sample 随现代调查与生态抽样通行，词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one part of a whole: a drawn subset, a census sample, an ecological sample, a representative mirror, a random sample, its size, a sample that fails to represent, and the sample seen against its target.","cn":"八个义项跟着同一份「整体中的部分」：抽出的子集、普查样本、生态样本、代表性映照、随机样本、它的规模、未能代表的样本，以及与目标总体相对的样本。"},"semanticMap":{"core":{"en":"CORE IMAGE: a large net over a lake, one small square lifted out, and the creatures in it counted in a white dish.","cn":"核心意象：大网罩住湖面，取出一小格，把格里的生物倒进白盘清点。"},"chain":["WHOLE SET","DRAWN SUBSET","CENSUS SAMPLE","ECOLOGICAL SAMPLE","REPRESENTATIVE MIRROR","BIAS CHECK"],"branches":[{"senses":"01 · 08","en":"THE WHOLE AND ITS PART: a defined population and the sample held against it.","cn":"整体与部分：界定好的总体，以及拿来与它对照的样本。"},{"senses":"02","en":"THE CENSUS TOOL: a sample checks the totals of a full count of people.","cn":"普查工具：样本核对一次全面人口清点的总数。"},{"senses":"03","en":"THE ECOLOGICAL COUNT: the same phrase counts beetles rather than voters.","cn":"生态计数：同一个短语数的是甲虫而不是选民。"},{"senses":"04 · 05","en":"THE MIRROR AND THE LOTTERY: representation and probability are what make the part trustworthy.","cn":"镜子与抽签：代表性与概率使这一份可信。"},{"senses":"06 · 07","en":"THE COUNT AND ITS FAILURE: a size can be too small, and a selection can fail to represent.","cn":"数目与失败：规模可能太小，选取也可能代表不了整体。"}]},"affixes":{"intro":{"en":"Population sample joins a Late Latin people-word to a clipped Latin loanword; both halves are free words and the Latin list covers each source.","cn":"population sample 把晚期拉丁的「人民」词与一个缩略拉丁借词合在一起；两半都是自由词，拉丁词条覆盖各自的来源。"},"latinIntro":{"en":"Latin populus and populatio stand behind population, while exemplum and eximere stand behind sample.","cn":"拉丁 populus 与 populatio 在 population 背后，exemplum 与 eximere 在 sample 背后。"},"items":[{"word":"populus","structure":"Latin noun, second declension","meaning":"the people; a nation","meaningCN":"人民；民族","example":"The first half begins with a word for a people.","exampleCN":"前半部分从一个表示人民的词开始。"},{"word":"populatio","structure":"Late Latin noun of action","meaning":"a people; a multitude","meaningCN":"一群人；众多","example":"The late Latin noun carries the demographic sense.","exampleCN":"晚期拉丁名词带着人口义。"},{"word":"population","structure":"English noun","meaning":"the people of a place; a defined whole","meaningCN":"一地的人民；界定好的整体","example":"Statistics widened the word to any set of units.","exampleCN":"统计学把这个词扩展到任何单位集合。"},{"word":"exemplum","structure":"Latin noun, second declension","meaning":"sample; pattern","meaningCN":"样本；范型","example":"The second half descends from this noun.","exampleCN":"后半部分由这个名词传下。"},{"word":"eximere","structure":"ex- out plus emere take","meaning":"to take out","meaningCN":"取出","example":"The verb supplies the taking picture.","exampleCN":"这个动词提供「取出」的画面。"},{"word":"sample","structure":"English clipping of example","meaning":"a taken portion","meaningCN":"取出的一份","example":"The second half names the part.","exampleCN":"后半部分命名那一份。"},{"word":"sampling","structure":"sample plus -ing","meaning":"the method of taking samples","meaningCN":"取样的方法","example":"The ending turns the act into a method.","exampleCN":"后缀把动作变成方法。"},{"word":"-ation","structure":"Latin -atio through French","meaning":"an action or its result","meaningCN":"动作或其结果","example":"It builds population from a verb of peopling.","exampleCN":"它由表示「使人居住」的动词构成 population。"},{"word":"subpopulation","structure":"sub- under plus population","meaning":"a group within a population","meaningCN":"总体之内的一群","example":"The prefix marks a smaller set inside the whole.","exampleCN":"前缀标出整体之内较小的集合。"}],"latinEntries":[{"word":"populus","structure":"populus, populi (n., second declension)","meaning":"the people; nation","meaningCN":"人民；民族"},{"word":"populatio","structure":"populatio, populationis (n., third declension)","meaning":"a people; multitude","meaningCN":"一群人；众多"},{"word":"exemplum","structure":"exemplum, exempli (n., second declension)","meaning":"sample; pattern","meaningCN":"样本；范型"},{"word":"eximere","structure":"eximo, exemi, exemptum (v., third conjugation)","meaning":"to take out","meaningCN":"取出"}],"derivatives":[{"word":"population","pos":"n.","zh":"人口；总体"},{"word":"populate","pos":"v.","zh":"居住于；填充"},{"word":"populous","pos":"adj.","zh":"人口稠密的"},{"word":"sample","pos":"n./v.","zh":"样本；取样"},{"word":"sampling","pos":"n.","zh":"抽样"},{"word":"subpopulation","pos":"n.","zh":"亚群；子总体"}]}},{"word":"data collection","ipa_uk":"/ˈdeɪtə kəˈlekʃn/","ipa_us":"/ˈdeɪtə kəˈlekʃn/","definition_zh":"数据收集；数据采集；资料收集的过程","definition_en":"the process of gathering information or measurements for study or analysis","core_image":"一张长桌上摊着问卷、录音笔、笔记本与平板，几路材料被归进同一只文件箱","scene":"调查站里一张长桌摊满问卷与记录本，访员把当天收回的材料逐份编号，再装进同一只文件箱。Data collection lasted three months, from the first interview to the last blood test.","sceneCN":"这里指为研究或分析而收集信息与测量的整个过程（第 1 个义项：为研究收集资料与测量的活动）；句意为数据收集从第一次访谈持续到最后一次验血，共三个月。图中可辨识物件：问卷、录音笔、记录本、文件箱。","pos":[{"tag":"n.","zh":"数据收集；数据采集；资料收集"}],"collocations":[{"phrase":"data collection method","zh":"数据收集方法"},{"phrase":"data collection process","zh":"数据收集过程"},{"phrase":"data collection tool","zh":"数据收集工具"},{"phrase":"field data collection","zh":"现场数据收集"},{"phrase":"data collection period","zh":"数据收集期"},{"phrase":"automated data collection","zh":"自动数据采集"}],"forms":[{"label":"不可数名词","form":"data collection"},{"label":"相关名词（数据）","form":"data"},{"label":"相关名词（收集）","form":"collection"},{"label":"动词（收集）","form":"collect"},{"label":"名词（收集者）","form":"collector"},{"label":"复合形式（数据收集系统）","form":"data collection system"}],"derivatives":[{"word":"data","pos":"n.","zh":"数据；资料"},{"word":"datum","pos":"n.","zh":"单一数据；基准点"},{"word":"collect","pos":"v.","zh":"收集；采集"},{"word":"collection","pos":"n.","zh":"收集；收藏"},{"word":"collector","pos":"n.","zh":"收集者；采集器"},{"word":"collectible","pos":"adj./n.","zh":"可收集的；收藏品"}],"senses":[{"no":"01","title":"The whole activity of gathering","titleCN":"收集资料的整体活动","definition":"the activity of gathering information or measurements for a study","definitionCN":"为一项研究收集信息或测量的活动","example":"Data collection lasted three months, from the first interview to the last blood test.","exampleCN":"数据收集从第一次访谈持续到最后一次验血，共三个月。","why":"Data is the plural of datum, something given, and collection is a gathering together; the phrase names the gathering.","whyCN":"前一词是拉丁「给定之物」的复数，后一词意为聚拢在一起，短语命名的正是这个聚拢过程。"},{"no":"02","title":"Capture by instruments","titleCN":"由仪器完成的采集","definition":"the automatic recording of measurements by sensors or software rather than by hand","definitionCN":"由传感器或软件自动记录测量，而不是靠人手抄写","example":"The sensors handle data collection without any member of staff present.","exampleCN":"传感器在无人值守时也能完成数据采集。","why":"The same phrase covers machines, because gathering does not require a human hand.","whyCN":"同一个短语也覆盖机器，因为收集并不需要人手。"},{"no":"03","title":"Gathering from documents","titleCN":"从文献与档案中收集","definition":"the gathering of information from records, archives or published sources","definitionCN":"从记录、档案或已发表材料中收集信息","example":"Archive work is a slow kind of data collection.","exampleCN":"档案工作是速度很慢的一种资料收集。","why":"Collection covers any source, and paper can be gathered as well as people can be interviewed.","whyCN":"后一词覆盖任何来源，纸面材料能收集，人也能被访谈。"},{"no":"04","title":"The methods used","titleCN":"所采用的方法","definition":"the set of methods chosen for gathering information, such as interviews, tests or observation","definitionCN":"为收集信息而选定的一套方法，如访谈、测验或观察","example":"The paper explains its data collection and its coding rules.","exampleCN":"论文说明了它的数据收集方式与编码规则。","why":"A phase of work that must be defended turns into a method, and the phrase takes that sense too.","whyCN":"一项需要交代理由的工作会变成「方法」，短语也就带着这层意思。"},{"no":"05","title":"The stage of a project","titleCN":"项目中的一个阶段","definition":"the period in a project during which information is gathered, before analysis begins","definitionCN":"项目中收集信息、分析尚未开始的那段时间","example":"Data collection ended before the analysis began.","exampleCN":"数据收集在分析开始之前结束。","why":"Projects divide time into stages, and this phrase names one of them.","whyCN":"项目把时间分成阶段，这个短语命名其中一个。"},{"no":"06","title":"Work done in the field","titleCN":"野外完成的收集","definition":"the gathering of information at the place where the subjects or events actually are","definitionCN":"在被试或事件实际所在的地点收集信息","example":"Field data collection in the mountains required paper forms.","exampleCN":"在山里进行的现场数据收集需要用纸质表格。","why":"Fieldwork adds a place to the phrase, because some gathering cannot be done at a desk.","whyCN":"野外工作给短语添了一个地点，因为有些收集不能在书桌前完成。"},{"no":"07","title":"The tool that gathers","titleCN":"承担收集的工具","definition":"the application, device or system used to gather information","definitionCN":"用来收集信息的应用、设备或系统","example":"The app is only a data collection tool, not an analysis engine.","exampleCN":"这款应用只是数据收集工具，不是分析引擎。","why":"English lets a phrase for an activity stand in front of tool, and the tool takes over the name.","whyCN":"英语可以让表示活动的短语放到「工具」一词前面，工具便接过这个名字。"},{"no":"08","title":"The ethics of gathering","titleCN":"收集环节的伦理","definition":"the rules of consent, privacy and safety that govern how information is gathered","definitionCN":"约束信息如何收集的同意、隐私与安全规则","example":"The board reviewed the data collection plan for privacy risks.","exampleCN":"伦理委员会审查了数据收集计划中的隐私风险。","why":"Modern rules attach to the act itself, so the phrase can name the ethical side of gathering.","whyCN":"现代规则附着在行为本身，短语因此也能指收集的伦理一面。"}],"etymology":{"intro":{"en":"Data is the plural of Latin datum, something given, and collection comes from Latin colligere, to gather together. The compound is modern and its source is clear; the first record date of the phrase is uncertain.","cn":"前一词是拉丁 datum「给定之物」的复数，后一词源自拉丁 colligere「聚拢在一起」。复合词是近现代的，来源清楚；短语最早记录的年代不确定。"},"items":[{"era":"LATIN DARE","en":"Dare meant to give, and datum is its neuter past participle, a thing given.","cn":"dare 意为给，datum 是它的中性过去分词，即「被给出之物」。"},{"era":"LATIN DATA","en":"Data is the plural of datum; English now often treats it as a mass noun, but the plural origin remains visible.","cn":"data 是 datum 的复数；英语如今常把它当不可数名词，但复数来历仍看得见。"},{"era":"LATIN COLLIGERE","en":"Colligere joined com- together and legere to choose or gather, giving the picture of picking things into one place.","cn":"colligere 由意为「一起」的前缀与意为「挑选、收集」的词根合成，画出把东西捡到一处的画面。"},{"era":"FRENCH COLLECTION","en":"Old French collection brought the noun to English with the sense of a gathering or an assembled set.","cn":"古法语 collection 把名词带进英语，义为收集或聚成的一批。"},{"era":"SCIENTIFIC DATA","en":"Data became the standard word for recorded observations in the nineteenth century, when tables and instruments multiplied.","cn":"十九世纪表格与仪器激增，data 成为记录观测的标准词。"},{"era":"THE PHRASE","en":"Data collection became a fixed term with modern research and computing; its first recorded use is date uncertain.","cn":"这个短语随现代研究与计算成为固定术语；其最早书面用例的年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like data collection; the second names neighbouring activities in research.","cn":"第一组在形音上与「数据收集」相近；第二组是研究里相邻的活动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"data","ipa":"/ˈdeɪtə/","tag":"same phrase","definition":"The information itself, the plural of datum.","definitionCN":"信息本身，是 datum 的复数。"},{"word":"datum","ipa":"/ˈdeɪtəm/","tag":"same root","definition":"A single item of information or a fixed reference point.","definitionCN":"单条信息，或一个固定基准点。"},{"word":"collect","ipa":"/kəˈlekt/","tag":"same root","definition":"The verb for gathering things together.","definitionCN":"把东西聚拢起来的动词。"},{"word":"collection","ipa":"/kəˈlekʃn/","tag":"same phrase","definition":"A gathering or an assembled set; the second half of the phrase.","definitionCN":"收集，或聚成的一批；短语的后一半。"},{"word":"collector","ipa":"/kəˈlektə/","tag":"same root","definition":"A person or device that gathers things.","definitionCN":"收集东西的人或装置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"data gathering","ipa":"/ˈdeɪtə ˈɡæðərɪŋ/","tag":"near meaning","definition":"A plainer synonym for the same activity.","definitionCN":"同一活动的更直白说法。"},{"word":"fieldwork","ipa":"/ˈfiːldwɜːk/","tag":"near meaning","definition":"Research done at the site rather than at a desk.","definitionCN":"在实地而非书桌前完成的研究。"},{"word":"survey","ipa":"/ˈsɜːveɪ/","tag":"near meaning","definition":"A study that gathers answers from a chosen set of people.","definitionCN":"向选定的一批人收集回答的研究。"},{"word":"acquisition","ipa":"/ˌækwɪˈzɪʃn/","tag":"near meaning","definition":"The obtaining of data or material, often by an instrument.","definitionCN":"获取数据或材料，常指由仪器完成。"},{"word":"recording","ipa":"/rɪˈkɔːdɪŋ/","tag":"near meaning","definition":"The act of setting measurements down in a lasting form.","definitionCN":"把测量以可留存的形式记下来的行为。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin sources, the real plural history and real research terms.","cn":"正常联想使用真实的拉丁来源、真实的复数来历与真实研究术语。"},"normal":[{"en":"Data is the plural of datum, a thing given, so data collection is the gathering of things given by the world.","cn":"data 是 datum「给定之物」的复数，所以数据收集就是把世界给出的东西聚起来。"},{"en":"Collection comes from colligere, to pick things together into one place.","cn":"collection 来自 colligere，即把东西捡到一处。"},{"en":"Fixed phrases include data collection method, data collection period and field data collection.","cn":"固定说法有数据收集方法、数据收集期与现场数据收集。"},{"en":"A sensor can do data collection alone, which is why the phrase covers machines as well as people.","cn":"传感器可以独自完成数据采集，所以这个短语既指人也指机器。"},{"en":"Consent and privacy attach to data collection before anyone touches the data.","cn":"在任何人碰数据之前，同意与隐私就已经附着在数据收集上。"}],"abstract":[{"en":"Data collection is the part of research where the world is allowed to speak.","cn":"数据收集是研究里让世界开口说话的那一段。"},{"en":"What is not gathered cannot be analysed, and what is gathered badly cannot be repaired later.","cn":"没有收集到的无法分析，收集坏了的也无法在事后补救。"},{"en":"Every table in a paper begins as somebody's careful gathering.","cn":"论文里的每一张表，起初都是某个人仔细收集的结果。"}]},"examples":[{"en":"Data collection began after the ethics board gave its approval.","cn":"伦理委员会批准之后，数据收集才开始。"},{"en":"The team moved its data collection to a secure server.","cn":"团队把数据收集迁到了一台安全服务器。"},{"en":"Poor data collection at the start ruined the later analysis.","cn":"一开始糟糕的数据收集毁掉了后来的分析。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「数据靠捡」——把数据一点点捡到一起：数据收集","word":"data collection"},"root":"前一词是拉丁 datum「给定之物」的复数，来自 dare「给」；后一词源自拉丁 colligere「收集」（前缀意为「一起」加词根意为「选取」），经法语进入英语。短语 data collection 是近现代研究与计算语境的复合词，词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one gathering: the whole activity, capture by instruments, work in archives, the methods used, the project stage, fieldwork, the tool, and finally the ethics of gathering.","cn":"八个义项跟着同一个「聚拢」：整体活动、仪器采集、档案工作、所用方法、项目阶段、野外工作、工具，最后是收集环节的伦理。"},"semanticMap":{"core":{"en":"CORE IMAGE: questionnaires, a recorder and a notebook on one table, all sorted into a single file box.","cn":"核心意象：问卷、录音笔与记录本摊在同一张桌上，最后都归进一只文件箱。"},"chain":["GATHERING","AUTOMATED CAPTURE","DOCUMENT SEARCH","METHODS","FIELDWORK","ETHICS"],"branches":[{"senses":"01 · 05","en":"THE ACTIVITY AND THE STAGE: gathering as a whole, and the stretch of project time it occupies.","cn":"活动与阶段：作为整体的收集，以及它所占的那段项目时间。"},{"senses":"02 · 07","en":"THE MACHINE AND THE TOOL: sensors record, and an application is built for the gathering alone.","cn":"机器与工具：传感器记录，应用则专为收集而建。"},{"senses":"03","en":"THE PAPER SOURCE: archives and published records are gathered like any other material.","cn":"纸面来源：档案与已发表记录也像别的材料一样被收集。"},{"senses":"04","en":"THE METHODS: interviews, tests and observation are chosen and defended.","cn":"方法：访谈、测验与观察被选定并交代理由。"},{"senses":"06 · 08","en":"THE PLACE AND THE RULE: mountains demand paper forms, and consent limits what may be gathered.","cn":"地点与规则：山里要用纸表，同意则限制可以收集什么。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin plural with a Latin-derived noun; both halves are free words and the Latin list covers each source.","cn":"这个短语把拉丁复数与拉丁派生名词合在一起；两半都是自由词，拉丁词条覆盖各自的来源。"},"latinIntro":{"en":"Latin dare gives datum and data; Latin colligere and legere give collect and collection.","cn":"拉丁 dare 给出 datum 与 data；拉丁 colligere 与 legere 给出 collect 与 collection。"},"items":[{"word":"dare","structure":"Latin verb, first conjugation","meaning":"to give","meaningCN":"给","example":"The participle gives the word for a given thing.","exampleCN":"分词给出「被给出之物」这个词。"},{"word":"datum","structure":"Latin neuter past participle","meaning":"a thing given","meaningCN":"被给出之物","example":"One observation is one datum.","exampleCN":"一次观测就是一个「给定之物」。"},{"word":"data","structure":"Latin plural of datum","meaning":"things given","meaningCN":"被给出之物（复数）","example":"English often treats the plural as a mass noun.","exampleCN":"英语常把这个复数当作不可数名词。"},{"word":"colligere","structure":"com- together plus legere gather","meaning":"to gather together","meaningCN":"聚拢；收集","example":"The verb pictures things picked into one place.","exampleCN":"这个动词画出把东西捡到一处的画面。"},{"word":"legere","structure":"Latin verb, third conjugation","meaning":"to choose; to read","meaningCN":"挑选；读","example":"Choosing and reading share one Latin verb.","exampleCN":"挑选与阅读在拉丁语里共用一个动词。"},{"word":"collection","structure":"collect plus -ion","meaning":"a gathering","meaningCN":"收集；聚成的一批","example":"The noun names both the act and its result.","exampleCN":"这个名词既指动作也指结果。"},{"word":"-tion","structure":"Latin -tio through French","meaning":"an action or its result","meaningCN":"动作或其结果","example":"It builds collection, inspection and measurement.","exampleCN":"它能构成表示「收集」「检查」「测量」的三个名词。"},{"word":"collector","structure":"collect plus -or","meaning":"one who gathers","meaningCN":"收集者；采集器","example":"The agent suffix names the person or device.","exampleCN":"施动后缀指人或装置。"},{"word":"data collection","structure":"noun compound","meaning":"the gathering of information","meaningCN":"信息的收集","example":"The compound fixes the two halves into one term.","exampleCN":"复合词把两半固定成一个术语。"}],"latinEntries":[{"word":"dare","structure":"do, dedi, datum (v., first conjugation)","meaning":"to give","meaningCN":"给"},{"word":"datum","structure":"datum, dati (n., second declension)","meaning":"a thing given","meaningCN":"被给出之物"},{"word":"colligere","structure":"colligo, collegi, collectum (v., third conjugation)","meaning":"to gather together","meaningCN":"聚拢；收集"},{"word":"legere","structure":"lego, legi, lectum (v., third conjugation)","meaning":"to choose; read","meaningCN":"挑选；读"}],"derivatives":[{"word":"data","pos":"n.","zh":"数据"},{"word":"datum","pos":"n.","zh":"单条数据；基准点"},{"word":"collect","pos":"v.","zh":"收集"},{"word":"collection","pos":"n.","zh":"收集；收藏"},{"word":"collector","pos":"n.","zh":"收集者；采集器"},{"word":"collectible","pos":"adj./n.","zh":"可收集的；收藏品"}]}},{"word":"result","ipa_uk":"/rɪˈzʌlt/","ipa_us":"/rɪˈzʌlt/","definition_zh":"结果；成绩；后果；导致；由……造成；化验结果","definition_en":"something that happens or follows as a consequence of an action, event or process","core_image":"一只烧杯静置在台面上，底部分出两层，记录纸上写着最后读数","scene":"实验室台面上的一只烧杯静置了一夜，底部分出两层沉淀，技术员把最后读数抄进记录纸。The result surprised the whole lab, because the treated cells grew faster than expected.","sceneCN":"这里指某个过程结束时出现的结果（第 1 个义项：行动或过程造成的后果）；句意为这个结果让整个实验室意外，因为处理过的细胞长得比预期快。图中可辨识物件：烧杯、沉淀层、记录纸、笔。","pos":[{"tag":"n.","zh":"结果；成绩；后果"},{"tag":"v.","zh":"导致；由……造成"}],"collocations":[{"phrase":"as a result","zh":"因此；结果"},{"phrase":"result in","zh":"导致"},{"phrase":"result from","zh":"由……造成"},{"phrase":"test results","zh":"检验结果"},{"phrase":"final result","zh":"最终结果"},{"phrase":"exam results","zh":"考试成绩"},{"phrase":"result in failure","zh":"导致失败"}],"forms":[{"label":"单数","form":"result"},{"label":"复数","form":"results"},{"label":"动词","form":"result"},{"label":"过去式","form":"resulted"},{"label":"现在分词","form":"resulting"},{"label":"形容词（作为结果的）","form":"resultant"}],"derivatives":[{"word":"resultant","pos":"adj./n.","zh":"作为结果的；合力"},{"word":"resulting","pos":"adj.","zh":"由此产生的"},{"word":"resultless","pos":"adj.","zh":"无结果的"},{"word":"result-oriented","pos":"adj.","zh":"结果导向的"},{"word":"results","pos":"n.","zh":"结果（复数）；成绩"}],"senses":[{"no":"01","title":"What follows from an action","titleCN":"行动之后出现的结果","definition":"something that follows as a consequence of an action, event or process","definitionCN":"由某个行动、事件或过程带来的后果","example":"The result surprised the whole lab, because the treated cells grew faster than expected.","exampleCN":"这个结果让整个实验室意外，因为处理过的细胞长得比预期快。","why":"Resultare meant to spring back, and a result is what springs back from an action.","whyCN":"拉丁词根意为弹回，而结果就是从行动里弹回来的东西。"},{"no":"02","title":"A mark in an examination","titleCN":"考试或比赛的成绩","definition":"the mark or score obtained in a test, examination or competition","definitionCN":"在测验、考试或比赛中得到的分数或名次","example":"Her exam result was better than she had hoped.","exampleCN":"她的考试成绩比她期望的还好。","why":"A test is an action whose outcome must be recorded, so the general word became the name of a mark.","whyCN":"考试是一种必须记录结果的活动，笼统的词于是成了分数的名称。"},{"no":"03","title":"To bring something about","titleCN":"导致某事发生","definition":"to cause something to happen, used with in","definitionCN":"使某事发生，与表示「在……之中」的介词连用","example":"A missed step can result in a failed test.","exampleCN":"漏掉一步就可能导致检验失败。","why":"The verb reverses the noun: instead of what follows, it names the following itself.","whyCN":"动词把名词反过来：不再指随之而来之物，而指随之而来这件事。"},{"no":"04","title":"To come from a cause","titleCN":"由某原因造成","definition":"to arise as a consequence of something, used with from","definitionCN":"作为某事的后果而产生，与表示来源的介词连用","example":"The strange readings result from a loose cable.","exampleCN":"这些奇怪的读数是接头松动造成的。","why":"With from, the verb looks backwards along the same link that the noun looks forwards along.","whyCN":"与表示来源的介词连用时，动词沿着名词向前看的那条链往回看。"},{"no":"05","title":"The outcome of a study","titleCN":"研究得出的结果","definition":"the finding or measurement produced by an experiment or analysis","definitionCN":"实验或分析产生的发现或测量","example":"The study reports one result that contradicts the earlier paper.","exampleCN":"这项研究报告了一个与早先论文相矛盾的结果。","why":"Research speaks of results in the plural because one experiment yields many numbers.","whyCN":"研究报告常以复数形式出现，因为一次实验会产生许多数字。"},{"no":"06","title":"The value obtained by calculation","titleCN":"算出来的数值","definition":"the value produced when a calculation or operation is completed","definitionCN":"计算或运算完成后得到的数值","example":"Check your result against the answer key before moving on.","exampleCN":"继续之前先对照答案检查你算出的结果。","why":"Arithmetic also springs back an answer, and the same word covers the number.","whyCN":"算术也会弹回一个答案，同一个词也覆盖这个数值。"},{"no":"07","title":"The outcome of a vote","titleCN":"投票或选举的结果","definition":"the announced outcome of an election, vote or public decision","definitionCN":"选举、投票或公共决定公布的结局","example":"The election result was announced after midnight.","exampleCN":"选举结果在午夜之后公布。","why":"Public decisions have a single announced outcome, and the word names that moment.","whyCN":"公共决定有一个被公布的结局，这个词命名那个时刻。"},{"no":"08","title":"The final outcome","titleCN":"最终的结局","definition":"the final outcome of an effort, seen as success or failure","definitionCN":"一项努力的最终结局，被看作成功或失败","example":"The final result of the campaign was a narrow win.","exampleCN":"这场运动的最终结果是一场险胜。","why":"The word can stand alone for the end of a story, once all causes have worked themselves out.","whyCN":"当所有原因都走完，这个词可以单独指一个事情的终点。"},{"no":"09","title":"The reading from a test","titleCN":"化验或检验的读数","definition":"the recorded outcome of a medical or laboratory test","definitionCN":"医学或实验室检验记录下来的结果","example":"The blood result showed no sign of infection.","exampleCN":"血液化验结果没有显示感染迹象。","why":"Medicine turned the general noun into a countable report from the body.","whyCN":"医学把这个一般名词变成一份来自身体的可数报告。"}],"etymology":{"intro":{"en":"Result comes from Latin resultare, to spring back, built on re- back and saltare to leap. The source is clear; the date of its first English record is uncertain.","cn":"这个词源自拉丁 resultare「弹回」，由意为「回」的前缀与意为「跳」的词根构成。词源清楚，最早英语记录的年代不确定。"},"items":[{"era":"LATIN SALTARE","en":"Saltare meant to leap or dance, and it supplies the physical picture inside result.","cn":"saltare 意为跳、舞，提供这个词内部的物理画面。"},{"era":"LATIN RESULTARE","en":"Resultare joined re- back to saltare, meaning to spring back or rebound.","cn":"resultare 把意为「回」的前缀加到 saltare 上，意为弹回、反弹。"},{"era":"OLD FRENCH RESULTER","en":"Old French resulter carried the word to English, where it first described something springing back.","cn":"古法语 resulter 把这个词带进英语，最初描述某物弹回。"},{"era":"ENGLISH RESULT","en":"English result is recorded as both noun and verb; the exact date of its first record is uncertain.","cn":"英语里这个词名词与动词都有记录；确切的首见年代不确定。"},{"era":"SCHOOL AND SCIENCE","en":"Examinations and experiments gave the word its everyday senses of a mark and a measurement.","cn":"考试与实验给了它「成绩」与「测量值」两个日常义。"},{"era":"MODERN PHRASES","en":"Fixed phrases such as as a result, result in and result from fixed the word's grammar.","cn":"「作为结果」「导致」「由……产生」这类固定说法定下了它的语法。"}]},"similar":{"note":{"en":"The first group looks or sounds like result; the second names neighbouring ideas of outcome.","cn":"第一组在形音上与「本词」相近；第二组是「结局」附近的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"results","ipa":"/rɪˈzʌlts/","tag":"same root","definition":"The plural, common in research and examinations.","definitionCN":"复数形式，常见于研究与考试。"},{"word":"resultant","ipa":"/rɪˈzʌltənt/","tag":"same root","definition":"The adjective for something produced as a result, also a noun in physics.","definitionCN":"指作为结果产生的形容词，物理学中也作名词。"},{"word":"resulting","ipa":"/rɪˈzʌltɪŋ/","tag":"same root","definition":"The participle for what comes about because of something else.","definitionCN":"指因别的事情而产生的分词。"},{"word":"resolute","ipa":"/ˈresəluːt/","tag":"different root","definition":"Determined; it comes from resolvere, to loosen or settle, not from resultare.","definitionCN":"坚决的；来自 resolvere「松开、定下」，与 resultare 无关。"},{"word":"insult","ipa":"/ˈɪnsʌlt/","tag":"different root","definition":"An offensive remark, from insilire, to leap at; the leap is shared, the word is not.","definitionCN":"侮辱性言语，来自 insilire「扑向」；共享「跳」，但不是同一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"outcome","ipa":"/ˈaʊtkʌm/","tag":"near meaning","definition":"The final situation produced by a process, often less neutral than result.","definitionCN":"过程造成的最终局面，常比 result 更带评价色彩。"},{"word":"consequence","ipa":"/ˈkɒnsɪkwəns/","tag":"near meaning","definition":"What follows from an action, with a stronger sense of cause and effect.","definitionCN":"由行动带来之物，因果意味更强。"},{"word":"finding","ipa":"/ˈfaɪndɪŋ/","tag":"near meaning","definition":"A result discovered by study, usually stated as a conclusion.","definitionCN":"研究得出的结果，通常表达为结论。"},{"word":"score","ipa":"/skɔː/","tag":"near meaning","definition":"The numerical result of a test or game.","definitionCN":"测验或比赛的数值结果。"},{"word":"effect","ipa":"/ɪˈfekt/","tag":"near meaning","definition":"The change produced by a cause, often measured in an experiment.","definitionCN":"原因造成的变化，常在实验中测量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin leap, the real verb grammar and real fixed phrases.","cn":"正常联想使用真实的拉丁「跳」、真实的动词语法与真实固定搭配。"},"normal":[{"en":"Resultare meant to spring back, so a result is what bounces back at you after an action.","cn":"resultare 意为弹回，所以结果就是行动之后弹回到你面前的东西。"},{"en":"Result in points forward to the outcome; result from points backward to the cause.","cn":"result in 向前指着结果；result from 向后指着原因。"},{"en":"Research uses the plural results because one experiment yields many numbers.","cn":"研究用复数 results，因为一次实验会产生许多数字。"},{"en":"School reports an exam result, and the hospital reports a blood result.","cn":"学校报告考试成绩，医院报告血液化验结果。"},{"en":"Fixed phrases include as a result and the final result.","cn":"固定说法有因此与最终结果。"}],"abstract":[{"en":"A result is the footprint an action leaves after it has gone.","cn":"结果是行动走过后留下的脚印。"},{"en":"The same outcome can be a success to one person and a failure to another.","cn":"同一个结局，对一个人是成功，对另一个人是失败。"},{"en":"To read a result well, you must know which action it sprang from.","cn":"要读懂一个结果，必须知道它是从哪个行动弹回来的。"}]},"examples":[{"en":"The result of the trial was clear enough to stop it early.","cn":"试验结果足够清楚，因而提前终止。"},{"en":"A careless change in method can result in a false answer.","cn":"方法上不小心的改动可能导致假答案。"},{"en":"She read the result twice before believing the number.","cn":"她把结果读了两遍才相信那个数字。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「日造特」——事情做完后被造出来的那个东西：结果","word":"result"},"root":"这个词源自拉丁 resultare「弹回、跳回」，由意为「回」的前缀与意为「跳」的词根构成，经古法语 resulter 进入英语；由「反弹回来」引申为「事情产生的结果」。成绩、研究结果、化验结果等是后起的具体化用法；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Nine senses follow one consequence: the outcome of an action, a mark, the two verb links of cause, a study's outcome, a calculated value, a vote, a final outcome, and a reading from a test.","cn":"九个义项跟着同一个「后果」：行动的结果、分数、动词的两种因果连接、研究结果、计算值、投票结果、最终结局，以及化验读数。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beaker left overnight, two layers settled at the bottom, and a final reading copied onto paper.","cn":"核心意象：烧杯放了一夜，底部沉淀出两层，最后的读数被抄到纸上。"},"chain":["CONSEQUENCE","SCORE","CAUSE LINK","DATA OUTCOME","COMPUTED VALUE","FINAL OUTCOME"],"branches":[{"senses":"01 · 08","en":"THE CONSEQUENCE AND THE END: what follows an action, and the final shape an effort takes.","cn":"后果与终点：行动之后随之而来之物，以及努力最终形成的形状。"},{"senses":"02","en":"THE MARK: a test produces a number that stands for the person's performance.","cn":"分数：考试产生一个数字，代表此人的表现。"},{"senses":"03 · 04","en":"THE TWO DIRECTIONS OF CAUSE: result in looks forward, result from looks back.","cn":"因果的两个方向：表示「导致」的搭配向前看，表示「由……产生」的搭配向后看。"},{"senses":"05 · 06","en":"THE DATA AND THE NUMBER: an experiment yields measurements, and arithmetic yields a value.","cn":"数据与数值：实验产出测量，算术产出数值。"},{"senses":"07 · 09","en":"THE PUBLIC AND THE BODY: a vote is announced, and a blood test reports.","cn":"公众与身体：投票被公布，血液检验给出报告。"}]},"affixes":{"intro":{"en":"Result is a Latin verb turned English noun and verb; its affix story is re- plus saltare, with the English ending -ant in the adjective.","cn":"result 是拉丁动词变成英语名词与动词；它的词缀故事是 re- 加 saltare，形容词里再用英语后缀 -ant。"},"latinIntro":{"en":"Latin re- back, saltare to leap and resultare to spring back supply the whole word.","cn":"拉丁 re-「回」、saltare「跳」与 resultare「弹回」提供整个词。"},"items":[{"word":"re-","structure":"Latin prefix","meaning":"back; again","meaningCN":"回；再","example":"The prefix gives the bouncing-back motion.","exampleCN":"前缀给出弹回的动作。"},{"word":"saltare","structure":"Latin verb, first conjugation","meaning":"to leap; to dance","meaningCN":"跳；舞","example":"The verb supplies the leap inside the word.","exampleCN":"这个动词提供词里的那一跳。"},{"word":"resultare","structure":"re- plus saltare","meaning":"to spring back","meaningCN":"弹回；反弹","example":"The Latin verb is the direct source.","exampleCN":"这个拉丁动词是直接来源。"},{"word":"resulter","structure":"Old French verb","meaning":"to rebound; to follow","meaningCN":"反弹；随之而来","example":"French carried the word across the Channel.","exampleCN":"法语把词带过了海峡。"},{"word":"result","structure":"English noun and verb","meaning":"an outcome; to follow from","meaningCN":"结果；由……产生","example":"English kept the noun and the verb.","exampleCN":"英语保留了名词与动词。"},{"word":"-ant","structure":"Latin -ans through French","meaning":"being or doing","meaningCN":"处于……状态的","example":"It builds resultant from the verb.","exampleCN":"它由动词构成表示「作为结果的」形容词。"},{"word":"resultant","structure":"result plus -ant","meaning":"produced as a result","meaningCN":"作为结果产生的","example":"The adjective names what follows.","exampleCN":"这个形容词命名随之而来之物。"},{"word":"resulting","structure":"result plus -ing","meaning":"coming about because of","meaningCN":"由此产生的","example":"The participle links a cause to its effect.","exampleCN":"分词把原因与其效果连起来。"}],"latinEntries":[{"word":"resultare","structure":"resulto, resultavi, resultatum (v., first conjugation)","meaning":"to spring back","meaningCN":"弹回；反弹"},{"word":"saltare","structure":"salto, saltavi, saltatum (v., first conjugation)","meaning":"to leap; dance","meaningCN":"跳；舞"},{"word":"re-","structure":"Latin prefix","meaning":"back; again","meaningCN":"回；再"}],"derivatives":[{"word":"resultant","pos":"adj./n.","zh":"作为结果的；合力"},{"word":"resulting","pos":"adj.","zh":"由此产生的"},{"word":"resultless","pos":"adj.","zh":"无结果的"},{"word":"result-oriented","pos":"adj.","zh":"结果导向的"}]}},{"word":"finding","ipa_uk":"/ˈfaɪndɪŋ/","ipa_us":"/ˈfaɪndɪŋ/","definition_zh":"研究发现；调查结论；裁决；测得的数值；发现物","definition_en":"a fact or piece of information discovered as the result of study or investigation","core_image":"一本摊开的记录册上，一行被红笔圈起，旁边贴着一枚小标签","scene":"研究室的桌上摊着一本记录册，负责人用红笔圈住其中一行，又在旁边贴上一枚标签，准备写进报告。The main finding was that the drug lowered blood pressure without causing drowsiness.","sceneCN":"这里指研究或调查得出的一项发现（第 1 个义项：研究或调查中发现的事实）；句意为主要发现是这种药降低了血压，却没有引起嗜睡。图中可辨识物件：记录册、红笔、标签、报告草稿。","pos":[{"tag":"n.","zh":"发现；研究结论；裁决；发现物"}],"collocations":[{"phrase":"key finding","zh":"关键发现"},{"phrase":"main finding","zh":"主要发现"},{"phrase":"research finding","zh":"研究发现"},{"phrase":"official finding","zh":"官方认定"},{"phrase":"audit finding","zh":"审计发现"},{"phrase":"finding of fact","zh":"事实认定"}],"forms":[{"label":"单数","form":"finding"},{"label":"复数","form":"findings"},{"label":"动词（找到）","form":"find"},{"label":"过去式","form":"found"},{"label":"名词（发现物）","form":"find"},{"label":"复合形式（事实认定）","form":"finding of fact"}],"derivatives":[{"word":"find","pos":"v./n.","zh":"找到；发现物"},{"word":"findings","pos":"n.","zh":"研究发现（复数）"},{"word":"finder","pos":"n.","zh":"发现者；取景器"},{"word":"found","pos":"v.","zh":"找到（过去式与过去分词）"}],"senses":[{"no":"01","title":"A fact discovered by study","titleCN":"研究得出的一项事实","definition":"a fact or conclusion reached through study or investigation","definitionCN":"通过研究或调查得出的事实或结论","example":"The main finding was that the drug lowered blood pressure without causing drowsiness.","exampleCN":"主要发现是这种药降低了血压，却没有引起嗜睡。","why":"Find meant to come upon something, and the ending names the thing come upon.","whyCN":"动词词根意为碰到、找到，后缀命名被碰到的那件事。"},{"no":"02","title":"The conclusion of an inquiry","titleCN":"调查得出的结论","definition":"the formal conclusion of an official inquiry or review","definitionCN":"官方调查或审查的正式结论","example":"The commission published a finding that the bridge had been poorly maintained.","exampleCN":"委员会公布了一项认定，称这座桥维护不善。","why":"An inquiry is a search, and its end is the thing found, so the word moved into official reports.","whyCN":"调查是一次寻找，终点是被找到的东西，这个词于是走进官方报告。"},{"no":"03","title":"A ruling in a court","titleCN":"法庭的裁决或认定","definition":"a decision or determination made by a court or tribunal","definitionCN":"法院或裁判机构作出的决定或认定","example":"The court's finding changed the terms of the contract.","exampleCN":"法庭的认定改变了合同条款。","why":"Law borrowed the word for the fact a judge finds after hearing evidence.","whyCN":"法律借用这个词，指法官听取证据后认定的事实。"},{"no":"04","title":"A measured value","titleCN":"测得的数值","definition":"a value or observation obtained from an experiment or measurement","definitionCN":"从实验或测量中得到的数值或观测","example":"One finding stood out: the treated group slept longer.","exampleCN":"有一项发现很突出：处理组睡得更久。","why":"An experiment is a search for a number, and each number is something found.","whyCN":"实验是在寻找一个数字，每个数字都是一样被找到的东西。"},{"no":"05","title":"An object uncovered","titleCN":"挖掘出土的物件","definition":"an object discovered during excavation or exploration","definitionCN":"在发掘或勘探中发现的物件","example":"The excavation produced a finding that dated the site to an earlier period.","exampleCN":"这次发掘出的一件发现物把遗址的年代推得更早。","why":"Archaeology finds things in the ground, and the word stays close to its oldest physical sense.","whyCN":"考古学从地下找到东西，这个词贴近它最古老的实物义。"},{"no":"06","title":"Something seen on a scan","titleCN":"检查中看到的异常","definition":"an observation made during a medical examination or scan","definitionCN":"医学检查或扫描中观察到的情况","example":"A routine finding on the scan led to further tests.","exampleCN":"扫描中的一项常规发现引出了进一步检查。","why":"Medicine reports what the eye or instrument finds inside the body.","whyCN":"医学报告眼睛或仪器在体内找到的东西。"},{"no":"07","title":"A problem noted in an audit","titleCN":"审计中指出的问题","definition":"a problem or weakness identified during an audit","definitionCN":"审计过程中发现的问题或薄弱环节","example":"The audit reported a finding about missing receipts.","exampleCN":"审计报告了一项关于收据缺失的发现。","why":"An audit searches records, and what it turns up is reported as a finding.","whyCN":"审计是在翻查记录，翻出来的东西就作为发现报告。"},{"no":"08","title":"A lesson a learner takes away","titleCN":"学习者得到的体会","definition":"a conclusion a student draws from an experiment or reading","definitionCN":"学生从实验或阅读中得出的结论","example":"The students wrote one finding from the experiment in their journals.","exampleCN":"学生们把实验中的一项发现写进日志。","why":"When learners repeat a search, their conclusion is also something found.","whyCN":"学习者重复一次寻找，他们的结论也是一样被找到的东西。"}],"etymology":{"intro":{"en":"Finding is the English noun from find, an inherited Germanic verb, with the native ending -ing. It is not a Latin word; the source is clear, while the date of the noun's first record is uncertain.","cn":"这个词由英语动词 find 加本族名词化后缀构成，该动词是日耳曼语本族词，并非拉丁词；来源清楚，名词最早记录的年代不确定。"},"items":[{"era":"OLD ENGLISH FINDAN","en":"Findan meant to come upon or discover, and it is the direct ancestor of find.","cn":"findan 意为碰到、发现，是「找到」这个动词的直接祖先。"},{"era":"PROTO-GERMANIC","en":"The verb belongs to a Germanic family that also gives German finden and Dutch vinden.","cn":"该动词属于日耳曼词族，同族还有德语 finden 与荷兰语 vinden。"},{"era":"THE ENDING -ING","en":"The native suffix -ing turns the verb into the name of the act or its result.","cn":"本族的名词化后缀把动词变成动作或其结果的名称。"},{"era":"MIDDLE ENGLISH FINDING","en":"The noun finding is recorded from the Middle English period; the exact first date is uncertain.","cn":"这个名词在中古英语时期已有记录，确切首见年代不确定。"},{"era":"LEGAL FINDING","en":"Law gave the word a formal sense: the fact a court determines after hearing evidence.","cn":"法律给了它正式义：法庭听取证据后认定的事实。"},{"era":"RESEARCH FINDING","en":"Modern research made finding a standard countable unit of a paper, usually in the plural.","cn":"现代研究使这个名词成为论文里标准的可数单位，常用复数。"}]},"similar":{"note":{"en":"The first group looks or sounds like finding; the second names neighbouring ideas of discovery and conclusion.","cn":"第一组在形音上与「本词」相近；第二组是「发现与结论」附近的其他说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"find","ipa":"/faɪnd/","tag":"same root","definition":"The verb for coming upon something, and a noun for a discovery.","definitionCN":"碰到某物的动词，也作名词指发现物。"},{"word":"finder","ipa":"/ˈfaɪndə/","tag":"same root","definition":"A person who finds, or a device such as a viewfinder.","definitionCN":"发现者，或取景器之类的装置。"},{"word":"findings","ipa":"/ˈfaɪndɪŋz/","tag":"plural","definition":"The plural, used for a set of results in a report.","definitionCN":"复数形式，指报告中的一组结果。"},{"word":"found","ipa":"/faʊnd/","tag":"same root","definition":"The past tense of find; also a separate verb meaning to establish.","definitionCN":"find 的过去式；另有一个独立动词义为「建立」。"},{"word":"fond","ipa":"/fɒnd/","tag":"different root","definition":"Affectionate; it looks close but belongs to another history.","definitionCN":"喜爱的；形近却属于另一段词源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"discovery","ipa":"/dɪˈskʌvəri/","tag":"near meaning","definition":"The act or result of finding something previously unknown.","definitionCN":"发现此前未知之物的行为或结果。"},{"word":"conclusion","ipa":"/kənˈkluːʒn/","tag":"near meaning","definition":"The judgement reached at the end of an inquiry.","definitionCN":"调查结束时得出的判断。"},{"word":"verdict","ipa":"/ˈvɜːdɪkt/","tag":"near meaning","definition":"The formal decision of a court or jury.","definitionCN":"法院或陪审团的正式决定。"},{"word":"observation","ipa":"/ˌɒbzəˈveɪʃn/","tag":"near meaning","definition":"Something noticed and recorded during a study.","definitionCN":"研究中注意到并记录下来的情况。"},{"word":"result","ipa":"/rɪˈzʌlt/","tag":"near meaning","definition":"The broader word for any outcome, including one that is found.","definitionCN":"泛指任何结果的更宽说法，包括被找到的结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Germanic verb, the real legal sense and real research phrases.","cn":"正常联想使用真实的日耳曼动词、真实的法律义与真实研究说法。"},"normal":[{"en":"Finding is find plus -ing: the thing you come upon after searching.","cn":"finding 是 find 加 -ing：寻找之后碰到的那件事。"},{"en":"Find is a Germanic verb, not a Latin one, so the word feels native and short.","cn":"find 是日耳曼动词而非拉丁词，所以这个词短而本族。"},{"en":"Law uses a finding for the fact a court determines, as in finding of fact.","cn":"法律用 finding 指法院认定的事实，如事实认定。"},{"en":"Research papers report findings in the plural because a study usually yields several.","cn":"研究论文用复数 findings，因为一项研究通常产出好几条。"},{"en":"An audit finding is a problem the auditor turned up.","cn":"审计发现就是审计者翻出来的问题。"}],"abstract":[{"en":"A finding is a piece of the world that has been made to speak.","cn":"一项发现是一小块被弄开口说话的世界。"},{"en":"The same fact can be a discovery in one field and a commonplace in another.","cn":"同一个事实在一个领域是发现，在另一个领域是老生常谈。"},{"en":"Findings are only as good as the search that produced them.","cn":"发现的好坏，取决于产生它的那次寻找。"}]},"examples":[{"en":"The finding was checked against a second data set.","cn":"这项发现又用第二套数据作了核对。"},{"en":"A single finding rarely settles a question on its own.","cn":"单独一项发现很少能独自解决一个问题。"},{"en":"The report lists each finding with the evidence behind it.","cn":"报告列出每项发现及其背后的证据。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「翻顶」——翻找之后顶出来的一样东西：发现","word":"finding"},"root":"这个词由古英语动词 findan「找到、发现」加本族名词化后缀构成，该动词属日耳曼语本族词，不来自拉丁语；先指发现的动作，后指被发现的事实。法律认定与研究结论义为后起专门化；词源清楚，名词最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one thing found: a research fact, an inquiry conclusion, a court ruling, a measured value, an excavated object, a scan observation, an audit problem, and a lesson a learner keeps.","cn":"八个义项跟着同一件「被找到的东西」：研究发现、调查结论、法庭裁决、测得数值、出土物件、扫描所见、审计问题，以及学习者留下的体会。"},"semanticMap":{"core":{"en":"CORE IMAGE: one line in a notebook circled in red, with a small label pasted beside it.","cn":"核心意象：记录册里一行被红笔圈住，旁边贴着一枚小标签。"},"chain":["DISCOVERED FACT","OFFICIAL VERDICT","LEGAL RULING","MEASURED VALUE","PHYSICAL RELIC","PERSONAL LESSON"],"branches":[{"senses":"01 · 04","en":"THE STUDY AND THE NUMBER: a fact concluded from research, and a value read from an experiment.","cn":"研究与数值：从研究得出的事实，以及从实验读出的数值。"},{"senses":"02 · 07","en":"THE OFFICIAL SEARCH: an inquiry and an audit both report what they turned up.","cn":"官方查找：调查与审计都报告自己翻出来的东西。"},{"senses":"03","en":"THE COURT: a judge's determination of fact becomes a finding.","cn":"法庭：法官对事实的认定成为裁决。"},{"senses":"05 · 06","en":"THE OBJECT AND THE BODY: something dug up and something seen on a scan.","cn":"物件与身体：被挖出来的东西与被扫描看到的东西。"},{"senses":"08","en":"THE LEARNER'S OWN: a student repeats the search and keeps one conclusion.","cn":"学习者自己的一份：学生重复寻找，留下一条结论。"}]},"affixes":{"intro":{"en":"Finding is a native English formation, so the Latin list is empty; the word is find plus -ing.","cn":"finding 是英语本族构词，因此拉丁词条留空；这个词是 find 加 -ing。"},"latinIntro":{"en":"There is no Latin ancestor in the immediate history of find; the relevant family is Germanic.","cn":"find 的直接词史里没有拉丁语祖先；相关词族是日耳曼语。"},"items":[{"word":"findan","structure":"Old English verb","meaning":"to come upon; discover","meaningCN":"碰到；发现","example":"The Old English verb is the direct ancestor.","exampleCN":"这个古英语动词是直接祖先。"},{"word":"find","structure":"English verb and noun","meaning":"to discover; a discovery","meaningCN":"发现；发现物","example":"The verb stayed short and native.","exampleCN":"这个动词保持简短且为本族词。"},{"word":"-ing","structure":"Old English noun suffix","meaning":"an act or its result","meaningCN":"动作或其结果","example":"The suffix builds finding, building and meeting.","exampleCN":"这个后缀构成表示「发现」「建造」「会面」的三个名词。"},{"word":"finding","structure":"find plus -ing","meaning":"something discovered","meaningCN":"被发现之物","example":"The noun names the thing come upon.","exampleCN":"这个名词命名被碰到的那件事。"},{"word":"findings","structure":"finding plus plural -s","meaning":"a set of discoveries","meaningCN":"一组发现","example":"Reports usually use the plural.","exampleCN":"报告通常用复数。"},{"word":"finder","structure":"find plus -er","meaning":"one who finds","meaningCN":"发现者","example":"The agent suffix names the person.","exampleCN":"施动后缀指人。"},{"word":"found","structure":"irregular past of find","meaning":"discovered","meaningCN":"找到了","example":"The old verb keeps an irregular past.","exampleCN":"这个古老动词保留不规则过去式。"},{"word":"finding of fact","structure":"legal compound","meaning":"a court's determination of fact","meaningCN":"法院对事实的认定","example":"Law fixes the phrase for a formal determination.","exampleCN":"法律把这个短语固定为正式认定。"}],"latinEntries":[],"derivatives":[{"word":"find","pos":"v./n.","zh":"找到；发现物"},{"word":"findings","pos":"n.","zh":"研究发现（复数）"},{"word":"finder","pos":"n.","zh":"发现者；取景器"},{"word":"found","pos":"v.","zh":"找到（过去式）"},{"word":"finding","pos":"n.","zh":"发现；裁决"}]}},{"word":"findings","ipa_uk":"/ˈfaɪndɪŋz/","ipa_us":"/ˈfaɪndɪŋz/","definition_zh":"研究发现（复数）；调查结论汇编；裁决中的多项认定；审计问题清单；体检各项结果","definition_en":"the plural of finding; a set of facts or conclusions discovered by study or investigation","core_image":"一份报告末尾排着几条编号的结论，每条下面都跟着一行证据出处","scene":"报告打印出来后摊在桌上，末尾几条编号结论依次排列，每条下面都跟着一行证据出处。The findings were published in three tables, each with its own notes.","sceneCN":"这里指研究或调查得出的一组发现，用复数形式（第 1 个义项：一篇报告或一项研究中的多项发现）；句意为这些发现分三张表发表，每张表都有自己的注释。图中可辨识物件：报告、编号结论、证据行、表格。","pos":[{"tag":"n.","zh":"研究发现（复数）；结论汇编"}],"collocations":[{"phrase":"key findings","zh":"主要发现"},{"phrase":"research findings","zh":"研究结果"},{"phrase":"preliminary findings","zh":"初步结果"},{"phrase":"findings section","zh":"结果部分"},{"phrase":"report findings","zh":"报告结论"},{"phrase":"summarize the findings","zh":"概述发现"}],"forms":[{"label":"复数","form":"findings"},{"label":"单数","form":"finding"},{"label":"动词（找到）","form":"find"},{"label":"过去式","form":"found"},{"label":"名词（发现物）","form":"find"},{"label":"复合形式（结果部分）","form":"findings section"}],"derivatives":[{"word":"finding","pos":"n.","zh":"发现；裁决"},{"word":"find","pos":"v./n.","zh":"找到；发现物"},{"word":"finder","pos":"n.","zh":"发现者；取景器"},{"word":"found","pos":"v.","zh":"找到（过去式）"},{"word":"findable","pos":"adj.","zh":"可找到的"}],"senses":[{"no":"01","title":"The set of results in a study","titleCN":"一项研究的多项结果","definition":"the set of facts or conclusions produced by one study, taken together","definitionCN":"一项研究所产生的全部事实或结论，合在一起看","example":"The findings were published in three tables, each with its own notes.","exampleCN":"这些发现分三张表发表，每张表都有自己的注释。","why":"The plural is the normal form in research because one study yields several conclusions at once.","whyCN":"研究里通常用复数，因为一项研究一次会产出好几条结论。"},{"no":"02","title":"The conclusions of an inquiry","titleCN":"调查报告的结论条目","definition":"the formal conclusions listed at the end of an official inquiry","definitionCN":"官方调查结束时列出的正式结论","example":"The committee's findings filled twelve pages of the report.","exampleCN":"委员会的结论占了报告十二页。","why":"An official report lists its conclusions one by one, and the plural names that list.","whyCN":"官方报告把结论逐条列出，复数命名的正是这张清单。"},{"no":"03","title":"The results section of a paper","titleCN":"论文的结果部分","definition":"the part of a research paper that presents what was discovered","definitionCN":"研究论文中呈现所发现内容的那一部分","example":"The findings section lists every measure that changed.","exampleCN":"结果部分列出了每一项发生变化的指标。","why":"Journals fixed a place for the plural, and the section took the name of its contents.","whyCN":"期刊为这个复数固定了一个位置，那一节便以内容命名。"},{"no":"04","title":"The determinations of a court","titleCN":"法庭的多项认定","definition":"the several facts or rulings determined by a court in one judgement","definitionCN":"法院在一份判决中认定的多项事实或裁决","example":"The court recorded its findings in a written judgement.","exampleCN":"法院把各项认定写进一份书面判决。","why":"A judgement usually settles several points, so law speaks of findings in the plural.","whyCN":"一份判决通常要定下好几个点，所以法律用复数形式表述。"},{"no":"05","title":"The list from an audit","titleCN":"审计问题清单","definition":"the set of problems or weaknesses reported by auditors","definitionCN":"审计人员报告的一组问题或薄弱环节","example":"The auditors presented their findings to the board.","exampleCN":"审计人员向董事会提交了他们的发现。","why":"An audit rarely reports one problem, and the plural suits its list.","whyCN":"审计很少只报一个问题，复数正合它的清单形式。"},{"no":"06","title":"The results of medical tests","titleCN":"体检与化验的各项结果","definition":"the several results returned by a set of medical examinations","definitionCN":"一组医学检查返回的多项结果","example":"The clinic sent the findings to the patient's doctor.","exampleCN":"诊所把检查结果发给了病人的医生。","why":"A check-up produces many readings, so the plural covers the whole report.","whyCN":"一次体检会产生许多读数，复数覆盖整份报告。"},{"no":"07","title":"Early results not yet settled","titleCN":"尚未定论的初步结果","definition":"results reported before the study is complete or confirmed","definitionCN":"在研究完成或得到确认之前报告的结果","example":"These preliminary findings still need a larger sample.","exampleCN":"这些初步结果还需要更大的样本。","why":"The plural can carry a warning: several results exist, but none is final.","whyCN":"复数可以带着警告：结果已有好几条，但没有一条是定论。"},{"no":"08","title":"The plural as a grammatical choice","titleCN":"作为语法选择的复数","definition":"the plural form used when a study produces more than one conclusion, as opposed to the singular finding","definitionCN":"当研究产出一条以上结论时使用的复数形式，与单数形式相对","example":"The plural findings is used when a study produces more than one conclusion.","exampleCN":"当一项研究产出一条以上结论时，就用复数形式。","why":"English marks the difference between one discovered fact and the whole set with a single -s.","whyCN":"英语只用一个复数词尾 就区分了一条被发现的事实与整组事实。"}],"etymology":{"intro":{"en":"Findings is finding plus the plural -s. Finding is a native English noun from find, an inherited Germanic verb, so the Latin list is empty. The source is clear; the scientific plural use has no precisely known first date.","cn":"这个词是「发现」名词的复数，加的是常规复数词尾。该名词是英语本族词，来自日耳曼语动词 find，因此没有同源的拉丁词可列。来源清楚；作为科学术语的复数用法没有确切可考的首见年代。"},"items":[{"era":"OLD ENGLISH FINDAN","en":"Findan meant to come upon or discover and is the direct ancestor of find.","cn":"findan 意为碰到、发现，是「找到」这个动词的直接祖先。"},{"era":"THE SUFFIX -ING","en":"The native ending -ing turns the verb into a noun for the act or its result.","cn":"本族的名词化后缀把动词变成动作或其结果的名词。"},{"era":"THE PLURAL -S","en":"English marks the plural with -s, so one finding becomes several findings.","cn":"英语用常规复数词尾标复数，于是一条发现变成多条发现。"},{"era":"LEGAL AND OFFICIAL USE","en":"Courts and committees list several determinations at once, which made the plural a natural report form.","cn":"法庭与委员会一次列出好几项认定，复数因此成了自然的报告形式。"},{"era":"RESEARCH PLURAL","en":"Modern papers standardised findings as the name of a results section; the first date of this use is uncertain.","cn":"现代论文把复数形式固定为结果部分的名称；这一用法的起始年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like findings; the second names what a report actually contains.","cn":"第一组在形音上与「本词」相近；第二组是报告里实际装着的那些东西。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"finding","ipa":"/ˈfaɪndɪŋ/","tag":"singular","definition":"One discovered fact or one ruling, the singular of the entry.","definitionCN":"一条被发现的事实或一项裁决，是本词条的单数。"},{"word":"find","ipa":"/faɪnd/","tag":"same root","definition":"The verb for discovering, and a noun for a thing found.","definitionCN":"表示发现的动词，也作名词指发现物。"},{"word":"finder","ipa":"/ˈfaɪndə/","tag":"same root","definition":"A person who finds, or a viewing device.","definitionCN":"发现者，或取景装置。"},{"word":"found","ipa":"/faʊnd/","tag":"same root","definition":"The past tense of find; another verb with this form means to establish.","definitionCN":"find 的过去式；另一个同形动词义为建立。"},{"word":"fond","ipa":"/fɒnd/","tag":"different root","definition":"Affectionate; only the shape is close.","definitionCN":"喜爱的；只是形状接近。"}]},{"heading":"NEAR MEANING","entries":[{"word":"results","ipa":"/rɪˈzʌlts/","tag":"near meaning","definition":"The broad plural for outcomes, including numbers and conclusions.","definitionCN":"泛指多项结果的宽说法，包括数值与结论。"},{"word":"conclusions","ipa":"/kənˈkluːʒnz/","tag":"near meaning","definition":"The judgements drawn from the evidence, often listed at the end.","definitionCN":"从证据得出的判断，常列在末尾。"},{"word":"observations","ipa":"/ˌɒbzəˈveɪʃnz/","tag":"near meaning","definition":"Things noticed and recorded during a study.","definitionCN":"研究中注意到并记录下来的情况。"},{"word":"evidence","ipa":"/ˈevɪdəns/","tag":"near meaning","definition":"The material that supports a finding rather than the finding itself.","definitionCN":"支撑发现的材料，而不是发现本身。"},{"word":"data","ipa":"/ˈdeɪtə/","tag":"near meaning","definition":"The raw measurements from which findings are drawn.","definitionCN":"得出结论所依据的原始测量。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real native verb, the real plural ending and real report conventions.","cn":"正常联想使用真实的本族动词、真实的复数后缀与真实报告惯例。"},"normal":[{"en":"Findings is simply finding with an -s: one discovered fact becomes a set of them.","cn":"findings 就是 finding 加 -s：一条发现变成一组发现。"},{"en":"Find is a Germanic verb, so findings feels short, native and concrete.","cn":"find 是日耳曼动词，所以 findings 短、本族、具体。"},{"en":"Papers put findings in a fixed section, and reports list them with evidence lines.","cn":"论文把 findings 放进固定的一节，报告则在每条下面附证据。"},{"en":"Law, audit and medicine all report several findings at once, which is why the plural fits.","cn":"法律、审计与医学都一次报告好几条发现，复数因此合适。"},{"en":"Preliminary findings are results that exist but are not yet settled.","cn":"初步结果就是已经出现、但尚未定论的结果。"}],"abstract":[{"en":"Findings are the several pieces of the world that a study has made speak.","cn":"发现是一项研究让世界开口说出的几句话。"},{"en":"A list of findings is also a list of what the study did not settle.","cn":"一张发现清单，同时也是一张研究没有定下来的事的清单。"},{"en":"The plural reminds you that no single result carries the whole truth.","cn":"复数提醒你：没有任何单一结果承载全部真相。"}]},"examples":[{"en":"The findings contradicted the earlier report in two places.","cn":"这些发现有两处与早先的报告相矛盾。"},{"en":"She summarised the findings in one page for the director.","cn":"她把发现压缩成一页交给主管。"},{"en":"The findings were strong enough to change the clinic's practice.","cn":"这些发现足以改变诊所的做法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「翻顶斯」——翻出来的好几样东西：多项发现","word":"findings"},"root":"这个词是「发现」名词的复数；该名词由古英语 findan「发现」加本族名词化后缀构成，动词属日耳曼语本族词。常规复数词尾是英语的普通标记。词源清楚；作为研究报告术语的复数用法起始年代不确定。","sensesIntro":{"en":"Eight senses follow one set of discoveries: a study's results, an inquiry's conclusions, a paper's results section, a court's determinations, an audit list, medical results, preliminary results, and the plural choice itself.","cn":"八个义项跟着同一组发现：研究结果、调查结论、论文结果部分、法庭多项认定、审计清单、体检结果、初步结果，以及复数形式本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: numbered conclusions at the end of a report, each with one line of evidence beneath it.","cn":"核心意象：报告末尾排着编号的结论，每条下面有一行证据。"},"chain":["SET OF DISCOVERIES","REPORT CONCLUSIONS","PAPER SECTION","LEGAL DETERMINATIONS","AUDIT LIST","MEDICAL RESULTS"],"branches":[{"senses":"01 · 07","en":"THE WHOLE SET AND THE EARLY SET: results taken together, and results reported before they are settled.","cn":"整组与早期一组：合在一起的结果，以及尚未定论就报告的结果。"},{"senses":"02 · 05","en":"THE OFFICIAL LIST: an inquiry and an audit both number their conclusions.","cn":"官方清单：调查与审计都把结论编号。"},{"senses":"03","en":"THE PAPER SECTION: a journal gives the plural a fixed place in the article.","cn":"论文的一节：期刊为这个复数在文章里安排了固定位置。"},{"senses":"04","en":"THE COURT: one judgement settles several points and records them as findings.","cn":"法庭：一份判决定下几个点，并把它们记为多项认定。"},{"senses":"06 · 08","en":"THE BODY AND THE GRAMMAR: a check-up returns many readings, and the -s marks the many.","cn":"身体与语法：体检返回许多读数，而复数词尾标出这个「多」。"}]},"affixes":{"intro":{"en":"Findings is a native English plural, not a Latin formation; the Latin list is empty and the affix story is find plus -ing plus plural -s.","cn":"findings 是英语本族复数，不是拉丁构词；拉丁词条留空，词缀故事是 find 加 -ing 再加复数 -s。"},"latinIntro":{"en":"There is no Latin ancestor for find; the relevant family is Germanic, and the endings are native English.","cn":"find 没有拉丁语祖先；相关词族是日耳曼语，后缀是英语本族的。"},"items":[{"word":"findan","structure":"Old English verb","meaning":"to come upon","meaningCN":"碰到；发现","example":"The Old English verb is the direct source.","exampleCN":"这个古英语动词是直接来源。"},{"word":"find","structure":"English verb and noun","meaning":"to discover; a discovery","meaningCN":"发现；发现物","example":"The base stays short and native.","exampleCN":"基础词保持简短且为本族。"},{"word":"-ing","structure":"Old English noun suffix","meaning":"an act or its result","meaningCN":"动作或其结果","example":"The suffix builds the singular finding.","exampleCN":"这个后缀构成单数名词。"},{"word":"finding","structure":"find plus -ing","meaning":"one discovered fact","meaningCN":"一条被发现的事实","example":"The singular names one thing found.","exampleCN":"单数命名一样被找到的东西。"},{"word":"-s","structure":"English plural marker","meaning":"more than one","meaningCN":"一个以上","example":"The plural marker builds findings.","exampleCN":"复数标记构成复数形式。"},{"word":"findings","structure":"finding plus -s","meaning":"a set of discoveries","meaningCN":"一组发现","example":"Reports prefer the plural as a heading.","exampleCN":"报告喜欢用复数作小标题。"},{"word":"findings section","structure":"noun compound","meaning":"the part that presents results","meaningCN":"呈现结果的部分","example":"The compound names a fixed place in a paper.","exampleCN":"复合词命名论文里的固定位置。"},{"word":"finder","structure":"find plus -er","meaning":"one who finds","meaningCN":"发现者","example":"The agent suffix names the person.","exampleCN":"施动后缀指人。"}],"latinEntries":[],"derivatives":[{"word":"finding","pos":"n.","zh":"发现；裁决"},{"word":"find","pos":"v./n.","zh":"找到；发现物"},{"word":"finder","pos":"n.","zh":"发现者"},{"word":"found","pos":"v.","zh":"找到（过去式）"},{"word":"findable","pos":"adj.","zh":"可找到的"}]}},{"word":"validity","ipa_uk":"/vəˈlɪdəti/","ipa_us":"/vəˈlɪdəti/","definition_zh":"效度；有效性；正确性；可信度；有效期","definition_en":"the quality of being based on truth or reason, or of being legally or logically acceptable","core_image":"一台天平两端各放一只砝码盘，指针稳稳停在正中，旁边压着一张盖了印章的证书","scene":"检验室里一台天平两端放上砝码，指针停在正中，旁边压着一张已盖章的证书。The validity of the test depends on whether it measures what it claims to measure.","sceneCN":"这里指测量工具确实测到其所声称之物的程度（第 1 个义项：测量效度）；句意为这项测验的效度取决于它是否测到了自己声称要测的东西。图中可辨识物件：天平、砝码、指针、盖章证书。","pos":[{"tag":"n.","zh":"效度；有效性；正确性；有效期"}],"collocations":[{"phrase":"internal validity","zh":"内部效度"},{"phrase":"external validity","zh":"外部效度"},{"phrase":"construct validity","zh":"构念效度"},{"phrase":"face validity","zh":"表面效度"},{"phrase":"validity of the results","zh":"结果的有效性"},{"phrase":"validity period","zh":"有效期"}],"forms":[{"label":"不可数名词","form":"validity"},{"label":"形容词（有效的）","form":"valid"},{"label":"副词（有效地）","form":"validly"},{"label":"动词（使生效）","form":"validate"},{"label":"名词（验证）","form":"validation"},{"label":"形容词（无效的）","form":"invalid"}],"derivatives":[{"word":"valid","pos":"adj.","zh":"有效的；正确的"},{"word":"validly","pos":"adv.","zh":"有效地；有理地"},{"word":"validate","pos":"v.","zh":"验证；使生效"},{"word":"validation","pos":"n.","zh":"验证；确认"},{"word":"invalid","pos":"adj.","zh":"无效的"},{"word":"invalidity","pos":"n.","zh":"无效；失效"}],"senses":[{"no":"01","title":"The quality of measuring the right thing","titleCN":"测到该测之物的效度","definition":"the degree to which a test or instrument measures what it is intended to measure","definitionCN":"测验或仪器测到其预定测量对象的程度","example":"The validity of the test depends on whether it measures what it claims to measure.","exampleCN":"这项测验的效度取决于它是否测到了自己声称要测的东西。","why":"Validus meant strong, and a valid test is one strong enough to stand as a true measure.","whyCN":"拉丁词根意为强，而有效的测验就是强到能站住脚的真实测量。"},{"no":"02","title":"Legal force","titleCN":"法律上的有效性","definition":"the quality of being legally acceptable or enforceable","definitionCN":"在法律上可被接受或可被执行的属性","example":"The lawyer questioned the validity of the contract.","exampleCN":"律师质疑这份合同的有效性。","why":"Law was among the first places where a document had to be strong enough to hold.","whyCN":"法律是最早要求文件「强到能站住」的领域之一。"},{"no":"03","title":"Soundness of an argument","titleCN":"论点的站得住脚","definition":"the quality of being well founded in fact or reasoning","definitionCN":"在事实或推理上有充分根据的属性","example":"No one doubted the validity of her argument.","exampleCN":"没有人怀疑她的论点站不站得住。","why":"A claim that can stand up to attack keeps the same strength metaphor.","whyCN":"一个经得起攻击的说法，用的仍是同一个「强度」比喻。"},{"no":"04","title":"Trustworthiness of data","titleCN":"数据的可信度","definition":"the extent to which data or evidence can be relied on","definitionCN":"数据或证据可以被信赖的程度","example":"The validity of the data was checked before publication.","exampleCN":"数据在发表之前已核查过可信度。","why":"Data must stand before conclusions may lean on it, and the word names that standing.","whyCN":"数据必须先站住，结论才能靠上去，这个词命名的正是这种站住。"},{"no":"05","title":"The period a document is good for","titleCN":"证件的有效期","definition":"the period during which a document or ticket is officially acceptable","definitionCN":"证件或票券在官方上仍可被接受的那段时间","example":"Please check the validity of your passport before booking.","exampleCN":"订票之前请检查护照的有效期。","why":"A document's strength can expire, so the word also names the time it remains strong.","whyCN":"文件的效力会到期，所以这个词也指它保持有效的那段时间。"},{"no":"06","title":"Logical validity","titleCN":"逻辑上的有效性","definition":"the property of an argument whose conclusion must follow from its premises","definitionCN":"结论必然由前提推出的论证所具有的属性","example":"The validity of the argument rests on its form, not its content.","exampleCN":"这个论证的有效性取决于形式，而不是内容。","why":"Logic borrowed the word for a form that holds whatever the subject matter.","whyCN":"逻辑学借这个词指一种无论内容如何都成立的形式。"},{"no":"07","title":"Internal validity","titleCN":"研究的内部效度","definition":"the degree to which a study can show that its treatment caused the observed change","definitionCN":"一项研究能证明其处理造成了所观察变化的程度","example":"Internal validity asks whether the design really isolates the cause.","exampleCN":"内部效度问的是：这个设计是否真的把原因单独隔了出来。","why":"Modern design splits validity into parts, and the inside of a study is one of them.","whyCN":"现代设计把效度分成几部分，研究内部就是其中一部分。"},{"no":"08","title":"External validity","titleCN":"研究的外部效度","definition":"the degree to which a study's results can be extended beyond its own sample","definitionCN":"研究结果能超出自身样本向外推广的程度","example":"External validity asks whether the result travels beyond the sample.","exampleCN":"外部效度问的是：结果能否走出这个样本。","why":"A result that holds only inside the lab is strong there and weak outside, so the outside gets its own name.","whyCN":"只在实验室内成立的结果，在里面强、在外面弱，于是「外面」也单独有了名字。"}],"etymology":{"intro":{"en":"Validity comes from Latin validitas, strength, from validus, strong, and valere, to be strong or be worth. The source is clear; the date of its first English record is uncertain.","cn":"这个词源自拉丁 validitas「力量、有效」，来自 validus「强壮的」，更早为 valere「有力量、有价值」。词源清楚，最早英语记录的年代不确定。"},"items":[{"era":"LATIN VALERE","en":"Valere meant to be strong, to have force or to be worth something.","cn":"valere 意为强、有力量，或值某个价。"},{"era":"LATIN VALIDUS","en":"Validus was the adjective for strong or able to hold, and it stands behind the whole family.","cn":"validus 是表示强壮、站得住的形容词，整个词族都由它而来。"},{"era":"LATIN VALIDITAS","en":"Late Latin validitas named the quality of being strong, a word built with the abstract ending -itas.","cn":"晚期拉丁语 validitas 用表示性质的后缀命名「强」这一性质。"},{"era":"FRENCH VALIDITE","en":"French validite carried the word into English with the sense of legal force.","cn":"法语 validite 把这个词带进英语，义为法律效力。"},{"era":"ENGLISH VALIDITY","en":"English validity is recorded with both legal and logical senses; the exact first date is uncertain.","cn":"英语里这个词的法律义与逻辑义都有记录；确切首见年代不确定。"},{"era":"MEASUREMENT VALIDITY","en":"Psychology and statistics made validity a technical measure of tests in the twentieth century.","cn":"心理学与统计学在二十世纪把「效度」变成测验的技术指标。"}]},"similar":{"note":{"en":"The first group looks or sounds like validity; the second names qualities often confused with it.","cn":"第一组在形音上与「本词」相近；第二组是常与它混淆的其他性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"valid","ipa":"/ˈvælɪd/","tag":"same root","definition":"The adjective for something that holds legally, logically or as a measure.","definitionCN":"指在法律、逻辑或测量上站得住的形容词。"},{"word":"validate","ipa":"/ˈvælɪdeɪt/","tag":"same root","definition":"The verb for making or proving something valid.","definitionCN":"使某物生效或证明其有效的动词。"},{"word":"validation","ipa":"/ˌvælɪˈdeɪʃn/","tag":"same root","definition":"The act or process of validating.","definitionCN":"验证或使生效的行为与过程。"},{"word":"invalid","ipa":"/ɪnˈvælɪd/","tag":"same root","definition":"Not valid; the negative prefix reverses the strength.","definitionCN":"无效的；否定前缀把「强」反过来。"},{"word":"valued","ipa":"/ˈvæljuːd/","tag":"different sense","definition":"Prized or assessed at a price, from the same verb but another sense.","definitionCN":"受重视或已估价的，同源动词的另一义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reliability","ipa":"/rɪˈlaɪəˈbɪləti/","tag":"near meaning","definition":"Consistency of measurement; a test can be reliable without being valid.","definitionCN":"测量的稳定性；一个测验可以可靠却无效度。"},{"word":"accuracy","ipa":"/ˈækjərəsi/","tag":"near meaning","definition":"Closeness to the true value, a narrower idea than validity.","definitionCN":"接近真值的程度，比效度更窄。"},{"word":"soundness","ipa":"/ˈsaʊndnəs/","tag":"near meaning","definition":"The quality of being well founded in reason or structure.","definitionCN":"在理由或结构上有充分根据的性质。"},{"word":"legitimacy","ipa":"/lɪˈdʒɪtɪməsi/","tag":"near meaning","definition":"Acceptance under law or custom, close to the legal sense.","definitionCN":"在法律或惯例下被接受，接近法律义。"},{"word":"effectiveness","ipa":"/ɪˈfektɪvnəs/","tag":"near meaning","definition":"The power to produce a wanted result, which is not the same as being valid.","definitionCN":"产生想要结果的能力，与「有效度」并不相同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin strength word, the real legal sense and real measurement terms.","cn":"正常联想使用真实的拉丁「力量」词、真实法律义与真实测量术语。"},"normal":[{"en":"Validity comes from valere, to be strong: something valid is strong enough to stand.","cn":"validity 来自 valere「强」：有效的东西强到能站住。"},{"en":"Law asks whether a document stands; logic asks whether an argument stands; measurement asks whether a test stands.","cn":"法律问文件站不站住；逻辑问论证站不站住；测量问测验站不站住。"},{"en":"Fixed phrases include internal validity, external validity and construct validity.","cn":"固定说法有内部效度、外部效度与构念效度。"},{"en":"A passport has validity, and so does a contract, and the two senses are close.","cn":"护照有有效期，合同有法律效力，这两个义项彼此很近。"},{"en":"Reliability is steadiness; validity is whether the steady thing is the right thing.","cn":"可靠性是稳；效度是问这个稳的东西是不是对的东西。"}],"abstract":[{"en":"Validity is the question of whether the ruler is measuring length or only casting a shadow.","cn":"效度问的是：这把尺在量长度，还是只在投下影子。"},{"en":"A strong claim needs a strong instrument behind it.","cn":"强的主张背后需要强的工具。"},{"en":"A test can be perfectly consistent and still measure the wrong thing.","cn":"一个测验可以完全一致，却仍在测错东西。"}]},"examples":[{"en":"The study's validity was weakened by the missing control group.","cn":"缺少对照组削弱了这项研究的效度。"},{"en":"She tested the validity of the scale against a second measure.","cn":"她用另一种测量核对了这个量表的效度。"},{"en":"The visa's validity ends on the last day of the month.","cn":"签证的有效期在当月最后一天结束。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瓦立的题」——一块瓦立得住、题目站得稳：有效性","word":"validity"},"root":"这个词源自拉丁 validitas「力量、有效」，来自 validus「强壮的」，更早为 valere「有力量、有价值」，经法语 validite 进入英语。法律有效义较早，测量效度义在二十世纪心理学与统计中发展；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one kind of strength: measuring the right thing, legal force, sound argument, trustworthy data, a document's period, logical form, internal validity, and external validity.","cn":"八个义项跟着同一种「强」：测到该测之物、法律效力、论点站得住、数据可信、证件有效期、逻辑形式、内部效度，以及外部效度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a balance whose pointer rests exactly at the centre, with a stamped certificate beside it.","cn":"核心意象：天平指针正停在中间，旁边压着一张盖章证书。"},"chain":["STRENGTH TO STAND","MEASUREMENT TRUTH","LEGAL FORCE","LOGICAL FORM","DATA TRUST","GENERALISABILITY"],"branches":[{"senses":"01 · 07","en":"THE MEASURE AND THE DESIGN: whether a test measures the right thing, and whether a study isolates the cause.","cn":"测量与设计：测验是否测到对的东西，以及研究是否把原因隔开。"},{"senses":"02 · 05","en":"THE DOCUMENT AND ITS CLOCK: legal force, and the period during which that force lasts.","cn":"文件与它的时钟：法律效力，以及效力持续的期限。"},{"senses":"03 · 06","en":"THE ARGUMENT: a claim that stands in substance, and a form that holds whatever the content.","cn":"论证：在内容上站得住的主张，以及无论内容如何都成立的形式。"},{"senses":"04","en":"THE DATA: evidence must stand before a conclusion may lean on it.","cn":"数据：证据必须先站住，结论才能靠上去。"},{"senses":"08","en":"THE OUTSIDE: a result strong inside the sample may still fail beyond it.","cn":"外面：在样本内部很强的结果，出了样本仍可能不成立。"}]},"affixes":{"intro":{"en":"Validity is a Latin abstract noun built on validus and the ending -itas, which reached English through French -ite.","cn":"validity 是拉丁抽象名词，建立在 validus 与后缀 -itas 上，经法语 -ite 进入英语。"},"latinIntro":{"en":"Latin valere, validus and validitas supply the word, and the abstract ending -itas became English -ity.","cn":"拉丁 valere、validus 与 validitas 提供这个词，抽象后缀 -itas 变成英语 -ity。"},"items":[{"word":"valere","structure":"Latin verb, second conjugation","meaning":"to be strong; be worth","meaningCN":"强；值","example":"The verb gives the idea of standing strength.","exampleCN":"这个动词给出「站得住的强度」这一意思。"},{"word":"validus","structure":"Latin adjective","meaning":"strong; able to hold","meaningCN":"强壮的；站得住的","example":"The adjective supplies the family stem.","exampleCN":"这个形容词提供词族词干。"},{"word":"validitas","structure":"Late Latin abstract noun","meaning":"strength; validity","meaningCN":"力量；有效性","example":"The abstract noun is the direct source.","exampleCN":"这个抽象名词是直接来源。"},{"word":"-itas","structure":"Latin abstract suffix","meaning":"the quality of being","meaningCN":"……的性质","example":"It builds validitas and becomes English -ity.","exampleCN":"它构成拉丁语 validitas，并在英语里变为表示性质的后缀。"},{"word":"validite","structure":"French noun","meaning":"legal force; soundness","meaningCN":"法律效力；正当","example":"French carried the word into English.","exampleCN":"法语把这个词带进英语。"},{"word":"validity","structure":"English noun","meaning":"soundness; legal force","meaningCN":"有效性；法律效力","example":"English kept both the legal and logical senses.","exampleCN":"英语保留了法律义与逻辑义。"},{"word":"-ity","structure":"English abstract suffix","meaning":"a quality or state","meaningCN":"性质或状态","example":"It builds validity, reliability and clarity.","exampleCN":"它构成表示「效度」「可靠性」「清晰度」的三个名词。"},{"word":"invalidity","structure":"in- not plus validity","meaning":"lack of validity","meaningCN":"无效；失效","example":"The negative prefix reverses the quality.","exampleCN":"否定前缀把这性质反过来。"}],"latinEntries":[{"word":"valere","structure":"valeo, valui, valitum (v., second conjugation)","meaning":"to be strong; be worth","meaningCN":"强；值"},{"word":"validus","structure":"validus, valida, validum (adj.)","meaning":"strong; able to hold","meaningCN":"强壮的；站得住的"},{"word":"validitas","structure":"validitas, validitatis (n., third declension)","meaning":"strength; validity","meaningCN":"力量；有效性"}],"derivatives":[{"word":"valid","pos":"adj.","zh":"有效的；正确的"},{"word":"validly","pos":"adv.","zh":"有效地"},{"word":"validate","pos":"v.","zh":"验证；使生效"},{"word":"validation","pos":"n.","zh":"验证"},{"word":"invalid","pos":"adj.","zh":"无效的"},{"word":"invalidity","pos":"n.","zh":"无效"}]}},{"word":"valid","ipa_uk":"/ˈvælɪd/","ipa_us":"/ˈvælɪd/","definition_zh":"有效的；正确的；有法律效力的；合理的；合规的；逻辑上成立的","definition_en":"based on truth or reason; legally or officially acceptable","core_image":"一张盖了钢印的证件放在桌上，旁边一支笔与一枚日期戳","scene":"办事窗口的桌上放着一本盖了钢印的证件，工作人员翻到有效页，又用日期戳在表格上按下。Only a valid passport is accepted at the border.","sceneCN":"这里指证件在法律上仍被接受、仍然有效（第 1 个义项：证件或文件具有法律效力）；句意为只有有效的护照才会在边境被接受。图中可辨识物件：证件、钢印、日期戳、表格。","pos":[{"tag":"adj.","zh":"有效的；正确的；有法律效力的；合理的"}],"collocations":[{"phrase":"valid passport","zh":"有效护照"},{"phrase":"valid argument","zh":"站得住脚的论点"},{"phrase":"valid reason","zh":"正当理由"},{"phrase":"valid contract","zh":"有效合同"},{"phrase":"valid ticket","zh":"有效车票"},{"phrase":"valid for","zh":"有效期为"}],"forms":[{"label":"形容词","form":"valid"},{"label":"比较级","form":"more valid"},{"label":"最高级","form":"most valid"},{"label":"副词","form":"validly"},{"label":"名词","form":"validity"},{"label":"动词（使生效）","form":"validate"},{"label":"形容词（无效的）","form":"invalid"}],"derivatives":[{"word":"validity","pos":"n.","zh":"效度；有效性"},{"word":"validly","pos":"adv.","zh":"有效地；有理地"},{"word":"validate","pos":"v.","zh":"验证；使生效"},{"word":"validation","pos":"n.","zh":"验证；确认"},{"word":"invalid","pos":"adj.","zh":"无效的"},{"word":"invalidity","pos":"n.","zh":"无效；失效"}],"senses":[{"no":"01","title":"A document that still counts","titleCN":"仍然算数的证件","definition":"officially acceptable for use because it has not expired or been cancelled","definitionCN":"因未过期或未被注销而仍可正式使用","example":"Only a valid passport is accepted at the border.","exampleCN":"只有有效护照才会在边境被接受。","why":"Validus meant strong, and a valid document is one strong enough to be accepted.","whyCN":"拉丁词根意为强，有效证件就是强到能被接受的文件。"},{"no":"02","title":"Legally binding","titleCN":"在法律上有约束力","definition":"having legal force because the required conditions were met","definitionCN":"因满足法定条件而具有法律效力","example":"The contract is valid only if both parties sign it.","exampleCN":"只有双方签字，这份合同才有效。","why":"Law asks whether an agreement can stand, and the word answers that question.","whyCN":"法律问一份协议站不站得住，这个词回答的就是这个问题。"},{"no":"03","title":"An argument that holds","titleCN":"站得住脚的论点","definition":"well founded in fact or reasoning, so that it can withstand objection","definitionCN":"在事实或推理上有充分根据，因而经得起反驳","example":"Her objection was valid because the data had been misread.","exampleCN":"她的反对有道理，因为数据被读错了。","why":"The strength metaphor moves from paper to reasoning without changing.","whyCN":"「强」这个比喻从纸面移到推理，没有改变。"},{"no":"04","title":"A justified reason","titleCN":"正当的理由","definition":"acceptable and reasonable as an explanation or excuse","definitionCN":"作为解释或理由可以被接受、合乎情理","example":"He had a valid reason for missing the meeting.","exampleCN":"他缺席会议有一个正当理由。","why":"A reason must also stand up, so the same adjective covers excuses.","whyCN":"理由也得站得住，所以同一个形容词也覆盖各种解释。"},{"no":"05","title":"A test that measures the right thing","titleCN":"测到该测之物的测验","definition":"measuring what it claims to measure, as a test or instrument","definitionCN":"作为测验或仪器，确实测到其所声称之物","example":"A valid test measures the skill it claims to measure.","exampleCN":"有效的测验测的正是它声称要测的技能。","why":"Measurement borrowed the legal word because a test must also be able to stand as evidence.","whyCN":"测量借用了法律词，因为测验也必须能站住当证据。"},{"no":"06","title":"An argument valid in form","titleCN":"形式有效的论证","definition":"structured so that the conclusion must follow from the premises, whether or not they are true","definitionCN":"结构上使结论必然由前提推出，无论前提是否真实","example":"The argument is valid, but its premise may still be false.","exampleCN":"这个论证在形式上有效，但它的前提仍可能是假的。","why":"Logic separates form from truth, and valid belongs to the form alone.","whyCN":"逻辑把形式与真假分开，这个词只属于形式。"},{"no":"07","title":"Officially in order","titleCN":"手续合规的","definition":"meeting the official conditions for use or entry","definitionCN":"符合使用或入场所需的官方条件","example":"The permit is valid for one season only.","exampleCN":"这张许可证只在一个季节内有效。","why":"Bureaucracy turns validity into a checklist of conditions.","whyCN":"行政手续把「有效」变成一张条件清单。"},{"no":"08","title":"A concern worth answering","titleCN":"值得回应的合理担忧","definition":"justified enough to deserve attention or an answer","definitionCN":"有充分根据，值得被重视或回应的","example":"Their concern about cost is valid and should be answered.","exampleCN":"他们对成本的担忧是合理的，应当得到回应。","why":"Even a worry can stand up, and the adjective grants it standing.","whyCN":"连担忧也能站得住，这个形容词就是给它一个站住的位置。"}],"etymology":{"intro":{"en":"Valid comes from Latin validus, strong, from valere, to be strong or be worth. The source is clear; the date of its first English record is uncertain.","cn":"这个词源自拉丁 validus「强壮的」，更早为 valere「有力量、有价值」。词源清楚，最早英语记录的年代不确定。"},"items":[{"era":"LATIN VALERE","en":"Valere meant to be strong or to be worth, and it also gives value and valour.","cn":"valere 意为强或值，也衍生出表示「价值」与「勇武」的两个词。"},{"era":"LATIN VALIDUS","en":"Validus was the adjective for strong, healthy or able to hold, used of bodies and of arguments.","cn":"validus 是表示强壮、健康、站得住的形容词，既用于身体也用于论证。"},{"era":"FRENCH VALIDE","en":"Old French valide carried the word to English with the sense of being in force.","cn":"古法语 valide 把这个词带进英语，义为具有效力。"},{"era":"ENGLISH VALID","en":"English valid is recorded with legal and logical senses; the exact first date is uncertain.","cn":"英语里这个词的法律义与逻辑义都有记录；确切首见年代不确定。"},{"era":"SCIENTIFIC USE","en":"Psychology and statistics extended valid to tests that measure the right thing.","cn":"心理学与统计学把这个词扩展到「测到对的东西」的测验。"},{"era":"EVERYDAY USE","en":"Modern English also applies the word to reasons, tickets, permits and worries.","cn":"现代英语也把它用于理由、票证、许可证与担忧。"}]},"similar":{"note":{"en":"The first group looks or sounds like valid; the second names words close in meaning but different in scope.","cn":"第一组在形音上与「本词」相近；第二组是意思接近但范围不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"validity","ipa":"/vəˈlɪdəti/","tag":"same root","definition":"The noun for the quality that valid describes.","definitionCN":"valid 所描述的性质的名词形式。"},{"word":"validate","ipa":"/ˈvælɪdeɪt/","tag":"same root","definition":"The verb for making or proving something valid.","definitionCN":"使某物生效或证明其有效的动词。"},{"word":"validation","ipa":"/ˌvælɪˈdeɪʃn/","tag":"same root","definition":"The process of checking or confirming validity.","definitionCN":"检查或确认有效性的过程。"},{"word":"invalid","ipa":"/ɪnˈvælɪd/","tag":"same root","definition":"Not valid; the prefix in- reverses the adjective.","definitionCN":"无效的；前缀 in- 把这个形容词反过来。"},{"word":"valued","ipa":"/ˈvæljuːd/","tag":"different sense","definition":"Prized or priced, from value rather than from validity.","definitionCN":"受重视或已定价的，来自 value 而不是 validity。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sound","ipa":"/saʊnd/","tag":"near meaning","definition":"Well founded and free of obvious flaws, often used of reasoning.","definitionCN":"根据充分、无明显缺陷，常用于推理。"},{"word":"legitimate","ipa":"/lɪˈdʒɪtɪmət/","tag":"near meaning","definition":"Allowed by law or by accepted rules.","definitionCN":"被法律或公认规则允许的。"},{"word":"effective","ipa":"/ɪˈfektɪv/","tag":"near meaning","definition":"Able to produce a wanted result, which is not the same as being valid.","definitionCN":"能产生想要结果的，与「有效度」并不相同。"},{"word":"binding","ipa":"/ˈbaɪndɪŋ/","tag":"near meaning","definition":"Legally obliging, as a contract or promise.","definitionCN":"在法律上有约束力的，如合同或承诺。"},{"word":"acceptable","ipa":"/əkˈseptəbl/","tag":"near meaning","definition":"Good enough to be allowed or received.","definitionCN":"好到足以被允许或接受的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin strength word, the real legal use and real fixed phrases.","cn":"正常联想使用真实的拉丁「力量」词、真实法律用法与真实固定搭配。"},"normal":[{"en":"Valid comes from validus, strong: whatever is valid is strong enough to be accepted.","cn":"valid 来自 validus「强」：凡是有效的，都强到能被接受。"},{"en":"A valid passport, a valid contract and a valid argument all have to stand up.","cn":"有效护照、有效合同与有效论证，都得站得住。"},{"en":"Fixed phrases include valid passport, valid reason and valid contract.","cn":"固定说法有有效护照、正当理由与有效合同。"},{"en":"In logic, valid describes the form; the premises may still be false.","cn":"在逻辑里，valid 描述形式；前提仍可能是假的。"},{"en":"A valid test measures the skill it claims to measure.","cn":"有效的测验测的是它声称要测的技能。"}],"abstract":[{"en":"Valid is a word about standing: what cannot stand is not valid.","cn":"valid 是一个关于「站住」的词：站不住的就不是有效的。"},{"en":"A form can be valid while its content is wrong, which is why logic and truth are separate questions.","cn":"形式可以有效而内容错误，所以逻辑与真假是两个问题。"},{"en":"Everyday life asks the same question as law: does this still hold?","cn":"日常生活问的与法律同一个问题：这个还算数吗？"}]},"examples":[{"en":"The ticket is valid only on the day printed on it.","cn":"这张票只在票面印着的当天有效。"},{"en":"A valid objection deserves an answer, not silence.","cn":"合理的反对值得一个回应，而不是沉默。"},{"en":"The scale is valid for adults but not for children.","cn":"这个量表对成年人有效，对儿童则不然。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瓦立得」——瓦片立得住，事情也站得稳：有效的","word":"valid"},"root":"这个词源自拉丁 validus「强壮的」，更早为 valere「有力量、有价值」；同族还有表示「价值」与「勇武」的两个词。经古法语 valide 进入英语。法律有效义较早，逻辑与测量义为后起专门化；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one kind of standing: a document still in force, a binding contract, an argument that holds, a justified reason, a true measure, a valid logical form, an official permit, and a concern worth answering.","cn":"八个义项跟着同一种「站得住」：仍然算数的证件、有约束力的合同、站得住的论点、正当理由、真实测量、逻辑上成立的形式、合规许可，以及值得回应的担忧。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stamped document on a counter, a pen beside it and a date stamp pressed onto a form.","cn":"核心意象：柜台上放着盖章证件，旁边一支笔，日期戳正压在表格上。"},"chain":["STRONG ENOUGH","LEGAL FORCE","SOUND REASON","TRUE MEASURE","LOGICAL FORM","JUSTIFIED CONCERN"],"branches":[{"senses":"01 · 02 · 07","en":"THE DOCUMENT: a passport, a contract and a permit are all strong enough to be accepted.","cn":"文件：护照、合同与许可证都强到能被接受。"},{"senses":"03 · 04","en":"THE REASON: an objection and an excuse must both stand up to examination.","cn":"理由：反对与解释都必须经得起检查。"},{"senses":"05","en":"THE MEASURE: a test must measure the skill it claims to measure.","cn":"测量：测验必须测到它声称要测的技能。"},{"senses":"06","en":"THE FORM: logic cares whether the conclusion follows, not whether the premise is true.","cn":"形式：逻辑只看结论是否推出，不看前提是否真实。"},{"senses":"08","en":"THE WORRY: even a concern can be justified enough to demand an answer.","cn":"担忧：连担忧也可以合理到必须回应。"}]},"affixes":{"intro":{"en":"Valid is a Latin adjective that became an English adjective; its endings are Latin -us in the source and zero ending in English.","cn":"valid 是拉丁形容词变成英语形容词；来源里的词尾是拉丁 -us，英语里则是零词尾。"},"latinIntro":{"en":"Latin valere and validus supply the word, and the abstract noun validity adds -itas.","cn":"拉丁 valere 与 validus 提供这个词，抽象名词 validity 再加 -itas。"},"items":[{"word":"valere","structure":"Latin verb, second conjugation","meaning":"to be strong; be worth","meaningCN":"强；值","example":"The verb gives the strength inside the word.","exampleCN":"这个动词提供词里的那股力量。"},{"word":"validus","structure":"Latin adjective","meaning":"strong; able to hold","meaningCN":"强壮的；站得住的","example":"The adjective is the direct source.","exampleCN":"这个形容词是直接来源。"},{"word":"valide","structure":"Old French adjective","meaning":"in force; sound","meaningCN":"有效；健全","example":"French carried the word to English.","exampleCN":"法语把词带进英语。"},{"word":"valid","structure":"English adjective","meaning":"sound; legally acceptable","meaningCN":"正当；法律上可接受","example":"English dropped the Latin ending.","exampleCN":"英语去掉了拉丁词尾。"},{"word":"validly","structure":"valid plus -ly","meaning":"in a valid way","meaningCN":"以有效的方式","example":"The adverb marks the manner.","exampleCN":"副词标出方式。"},{"word":"validity","structure":"valid plus -ity","meaning":"the quality of being valid","meaningCN":"有效的性质","example":"The suffix turns the adjective into a quality.","exampleCN":"后缀把形容词变成一种性质。"},{"word":"validate","structure":"valid plus -ate","meaning":"to make or prove valid","meaningCN":"使生效；证明有效","example":"The verb names the act of confirming.","exampleCN":"动词指确认的行为。"},{"word":"invalid","structure":"in- not plus valid","meaning":"not valid","meaningCN":"无效的","example":"The negative prefix reverses the adjective.","exampleCN":"否定前缀把形容词反过来。"}],"latinEntries":[{"word":"valere","structure":"valeo, valui, valitum (v., second conjugation)","meaning":"to be strong; be worth","meaningCN":"强；值"},{"word":"validus","structure":"validus, valida, validum (adj.)","meaning":"strong; able to hold","meaningCN":"强壮的；站得住的"},{"word":"validitas","structure":"validitas, validitatis (n., third declension)","meaning":"strength; validity","meaningCN":"力量；有效性"}],"derivatives":[{"word":"validity","pos":"n.","zh":"效度；有效性"},{"word":"validly","pos":"adv.","zh":"有效地"},{"word":"validate","pos":"v.","zh":"验证；使生效"},{"word":"validation","pos":"n.","zh":"验证"},{"word":"invalid","pos":"adj.","zh":"无效的"},{"word":"invalidity","pos":"n.","zh":"无效"}]}},{"word":"reproducibility","ipa_uk":"/ˌriːprəˈdjuːsəbɪləti/","ipa_us":"/ˌriːprəˈduːsəbɪləti/","definition_zh":"可重复性；可复现性；再现性；复现能力","definition_en":"the ability of a result or experiment to be obtained again by the same or another researcher","core_image":"两间实验室各摆一套相同的仪器，两张记录纸上画着几乎一样的曲线","scene":"两间实验室各摆着一套相同的仪器，两位技术员按同一份步骤各做一遍，两张记录纸上画出几乎一样的曲线。The reproducibility of the assay was checked in two labs before the paper was submitted.","sceneCN":"这里指他人按同样条件能再次得到相同结果的程度（第 1 个义项：结果能被再次得到的性质）；句意为论文投稿之前，这项检测的可重复性已在两间实验室核对过。图中可辨识物件：两套仪器、记录纸、曲线、操作步骤单。","pos":[{"tag":"n.","zh":"可重复性；可复现性；再现性"}],"collocations":[{"phrase":"reproducibility crisis","zh":"可重复性危机"},{"phrase":"high reproducibility","zh":"高可重复性"},{"phrase":"reproducibility of results","zh":"结果的可复现性"},{"phrase":"reproducibility standard","zh":"可重复性标准"},{"phrase":"lack of reproducibility","zh":"缺乏可重复性"},{"phrase":"computational reproducibility","zh":"计算可复现性"}],"forms":[{"label":"不可数名词","form":"reproducibility"},{"label":"形容词（可复现的）","form":"reproducible"},{"label":"副词（可复现地）","form":"reproducibly"},{"label":"动词（再现）","form":"reproduce"},{"label":"名词（复制）","form":"reproduction"},{"label":"形容词（生殖的）","form":"reproductive"}],"derivatives":[{"word":"reproduce","pos":"v.","zh":"再现；复制；繁殖"},{"word":"reproducible","pos":"adj.","zh":"可复现的；可重复的"},{"word":"reproducibly","pos":"adv.","zh":"可复现地"},{"word":"reproduction","pos":"n.","zh":"复制；繁殖"},{"word":"reproductive","pos":"adj.","zh":"生殖的；复制的"},{"word":"reproducer","pos":"n.","zh":"复制者；再现装置"}],"senses":[{"no":"01","title":"The result can be obtained again","titleCN":"结果能被再次得到","definition":"the degree to which the same result can be obtained again under the same conditions","definitionCN":"在相同条件下能再次得到同一结果的程度","example":"The reproducibility of the assay was checked in two labs before the paper was submitted.","exampleCN":"论文投稿之前，这项检测的可重复性已在两间实验室核对过。","why":"Reproduce joins re- again to produce, so the noun names the ability to bring the same result forth again.","whyCN":"动词把表示「再次」的前缀加到「产出」之上，名词便命名「再次产出同一结果」的能力。"},{"no":"02","title":"The experiment can be repeated","titleCN":"实验能被重复","definition":"the quality of an experiment whose whole procedure can be followed again by another team","definitionCN":"整套步骤能被另一个团队照着再做一遍的性质","example":"Careful reproducibility requires a protocol that another team can follow.","exampleCN":"要做到可重复，研究方案必须详细到另一个团队能照着做。","why":"The word covers the procedure as well as the number, because a result cannot return without the steps.","whyCN":"这个词既覆盖步骤也覆盖数值，因为没有步骤，结果就回不来。"},{"no":"03","title":"The crisis of missing repeats","titleCN":"复现失败造成的危机","definition":"the public concern that many published findings cannot be repeated","definitionCN":"许多已发表发现无法被重复所引发的公共担忧","example":"The conference was called to discuss the reproducibility crisis in psychology.","exampleCN":"这次会议专门讨论心理学中的可重复性危机。","why":"When many claims fail the test, the quality becomes the name of a field-wide problem.","whyCN":"当许多主张都过不了这道检验，这种性质就成了整个领域的问题之名。"},{"no":"04","title":"The stability of an instrument","titleCN":"仪器的再现稳定性","definition":"the consistency of readings given by an instrument on repeated measurement","definitionCN":"仪器反复测量同一对象时读数的稳定性","example":"The reproducibility of the balance was tested with the same standard block.","exampleCN":"天平的再现性用同一块标准砝码作了检验。","why":"Instruments also produce again, and their reproducibility is a property of the machine.","whyCN":"仪器也会再次产出，它的再现性是机器本身的属性。"},{"no":"05","title":"Batch-to-batch repeatability","titleCN":"批与批之间的再现精度","definition":"the consistency of a manufactured product from one batch to the next","definitionCN":"制成品从一批到下一批的一致性","example":"The plant records the reproducibility of each batch within narrow limits.","exampleCN":"工厂把每一批的再现精度都记录在很窄的范围内。","why":"Manufacturing asks the same question as science: can the same thing be made again?","whyCN":"制造业问的与科学同一个问题：同样的东西还能再做一次吗？"},{"no":"06","title":"The same code gives the same output","titleCN":"同一代码给出同一输出","definition":"the ability to rerun an analysis from the same data and code and obtain the same output","definitionCN":"用同一数据与代码重跑分析、得到同一输出的能力","example":"Computational reproducibility means the same code gives the same output.","exampleCN":"计算可复现性意味着同一份代码给出同一份输出。","why":"Computers brought a new kind of repeatability, where the steps are files rather than hands.","whyCN":"计算机带来一种新的可重复性，步骤是文件而不是人手。"},{"no":"07","title":"The standard a journal demands","titleCN":"期刊要求的可重复标准","definition":"a formal requirement that authors provide enough material for others to repeat the work","definitionCN":"要求作者提供足够材料、使他人能重复这项工作的正式规定","example":"The journal now enforces a reproducibility standard for its papers.","exampleCN":"这家期刊现在对论文执行可重复性标准。","why":"Once the quality is valued, it becomes a rule that can be checked.","whyCN":"这种性质一旦被看重，就变成可以核查的规则。"},{"no":"08","title":"The failure to repeat","titleCN":"无法重复的失败","definition":"the absence of reproducibility, when a second attempt does not produce the same result","definitionCN":"缺乏可重复性，即第二次尝试没有得到同一结果","example":"The lack of reproducibility in the earlier study delayed the drug's approval.","exampleCN":"早先研究缺乏可重复性，拖延了这种药的批准。","why":"The noun can name the failure as well as the virtue, because both are measured by the second attempt.","whyCN":"这个名词既能命名美德也能命名失败，因为两者都由第二次尝试来衡量。"}],"etymology":{"intro":{"en":"Reproducibility is reproduce plus -ible plus -ity, a Latin-derived stack. Reproduce comes from re- again and Latin producere, to lead forward. The source is clear; the date of the noun's first record is uncertain.","cn":"这个词由「产出」动词先加表示「能够」的后缀，再加表示「性质」的后缀构成。该动词来自表示「再次」的前缀与拉丁 producere「向前引出」。词源清楚，名词最早记录的年代不确定。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant to lead, and it stands inside producere as the moving element.","cn":"ducere 意为引导，作为「带动」的成分藏在 producere 里。"},{"era":"LATIN PRODUCERE","en":"Producere joined pro- forward to ducere, meaning to lead or bring forth.","cn":"producere 把意为「向前」的前缀加到 ducere 上，意为引出、带出。"},{"era":"LATIN PRODUCERE AGAIN","en":"The prefix re- adds the sense of doing it once more, giving reproduce.","cn":"表示「再次」的前缀加上「再做一次」的意思，构成「再次产出」的动词。"},{"era":"THE SUFFIX -IBLE","en":"Latin -ibilis means able to be, so reproducible means able to be produced again.","cn":"拉丁语 -ibilis 意为「能够被……」，因此「可复现的」指能够被再次产出。"},{"era":"THE SUFFIX -ITY","en":"Latin -itas turns the adjective into the name of the quality.","cn":"拉丁语 -itas 把形容词变成这种性质的名称。"},{"era":"MODERN SCIENCE","en":"Twentieth-century science made reproducibility a technical demand; the phrase reproducibility crisis is recent, and its first date is uncertain.","cn":"二十世纪科学使这个词成为技术要求；「可重复性危机」这一说法出现较晚，起始年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like reproducibility; the second names qualities it is often confused with.","cn":"第一组在形音上与「本词」相近；第二组是常与它混淆的性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reproduce","ipa":"/ˌriːprəˈdjuːs/","tag":"same root","definition":"To produce again, or to make offspring.","definitionCN":"再次产出，或繁殖后代。"},{"word":"reproducible","ipa":"/ˌriːprəˈdjuːsəbl/","tag":"same root","definition":"The adjective for something that can be produced again.","definitionCN":"指能够被再次产出的形容词。"},{"word":"reproducibly","ipa":"/ˌriːprəˈdjuːsəbli/","tag":"same root","definition":"The adverb for doing something in a repeatable way.","definitionCN":"以可重复的方式做某事的副词。"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","tag":"same root","definition":"The act of copying or the process of producing offspring.","definitionCN":"复制行为或繁殖过程。"},{"word":"reproductive","ipa":"/ˌriːprəˈdʌktɪv/","tag":"same root","definition":"Relating to producing offspring.","definitionCN":"与繁殖后代有关的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"repeatability","ipa":"/ˌriːpiːtəˈbɪləti/","tag":"near meaning","definition":"The chance of getting the same result when one person repeats the same measurement.","definitionCN":"同一个人重复同一测量时得到同一结果的机会。"},{"word":"replicability","ipa":"/ˌreplɪkəˈbɪləti/","tag":"near meaning","definition":"The chance that another team can repeat a study and find the same result.","definitionCN":"另一个团队重复研究并得到同一结果的机会。"},{"word":"reliability","ipa":"/rɪˈlaɪəˈbɪləti/","tag":"near meaning","definition":"Consistency of measurement over time, a narrower quality.","definitionCN":"测量随时间的稳定性，是一种更窄的性质。"},{"word":"consistency","ipa":"/kənˈsɪstənsi/","tag":"near meaning","definition":"Agreement among repeated results, without saying they are right.","definitionCN":"多次结果彼此一致，但不说明它们是对的。"},{"word":"stability","ipa":"/stəˈbɪləti/","tag":"near meaning","definition":"The tendency to stay the same rather than to be produced again.","definitionCN":"倾向于保持不变，而不是再次被产出。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin produce word, the real -ible and -ity stack and real science terms.","cn":"正常联想使用真实的拉丁「产出」词、真实的「能够」与「性质」两个后缀叠加，以及真实科学术语。"},"normal":[{"en":"Reproducibility is reproduce plus -ible plus -ity: the ability to be produced again.","cn":"reproducibility 是 reproduce 加 -ible 再加 -ity：能够被再次产出的能力。"},{"en":"Producere meant to lead forward, and re- adds a second leading.","cn":"producere 意为向前引出，re- 又加上第二次引出。"},{"en":"Fixed phrases include reproducibility crisis, reproducibility standard and computational reproducibility.","cn":"固定说法有可重复性危机、可重复性标准与计算可复现性。"},{"en":"Two labs, one protocol and nearly one curve: that is reproducibility in a picture.","cn":"两间实验室、一份步骤、几乎一条曲线：这就是可重复性的画面。"},{"en":"A journal that enforces a reproducibility standard is asking for the steps, not just the answer.","cn":"执行可重复性标准的期刊，要的是步骤，不只是答案。"}],"abstract":[{"en":"Reproducibility is the promise that the second try will not tell a different story.","cn":"可重复性是那个承诺：第二次尝试不会讲出另一个故事。"},{"en":"A result that no one can produce again is a rumour with numbers attached.","cn":"没人能再次产出的结果，只是带着数字的传闻。"},{"en":"The word measures science against its own claim to be public knowledge.","cn":"这个词用科学自称的「公共知识」来衡量科学本身。"}]},"examples":[{"en":"The team improved the reproducibility by writing down every step.","cn":"团队把每一步都写下来，从而提高了可重复性。"},{"en":"Reproducibility is now a condition for funding in some fields.","cn":"在某些领域，可重复性如今是获得资助的条件。"},{"en":"The report ranked the studies by their reproducibility.","cn":"报告按可重复性对这些研究作了排序。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「再次产出的能力」——同一结果还能再做出来：可重复性","word":"reproducibility"},"root":"这个词由意为「再次」的前缀、意为「产出」的词根与表示「能够」「性质」的两个后缀叠加构成。词根源自拉丁 producere「向前引出」（前缀意为「向前」加词根意为「引导」）。二十世纪科学使它成为技术术语，二〇一〇年代前后出现「可重复性危机」说法；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one second attempt: the same result again, the repeatable experiment, the crisis of failed repeats, instrument stability, batch consistency, computational replay, a journal standard, and the failure to repeat.","cn":"八个义项跟着同一次「第二次尝试」：再次得到同一结果、可重复的实验、复现失败的危机、仪器稳定性、批次一致性、计算重跑、期刊标准，以及无法重复的失败。"},"semanticMap":{"core":{"en":"CORE IMAGE: two labs, one protocol, and two record sheets carrying almost the same curve.","cn":"核心意象：两间实验室、一份步骤，两张记录纸上画着几乎一样的曲线。"},"chain":["SAME RESULT AGAIN","SECOND LAB","MEASUREMENT STABILITY","COMPUTATIONAL REPLAY","STANDARD DEMAND","CRISIS"],"branches":[{"senses":"01 · 02","en":"THE RESULT AND THE PROCEDURE: the number returns, and the steps make its return possible.","cn":"结果与步骤：数值回来了，而步骤使这个回来成为可能。"},{"senses":"03","en":"THE CRISIS: when many results fail to return, the quality becomes a public problem.","cn":"危机：当许多结果回不来，这种性质就成了公共问题。"},{"senses":"04 · 05","en":"THE MACHINE AND THE FACTORY: instruments and batches must give the same reading or the same product.","cn":"仪器与工厂：仪器与批次必须给出同一读数或同一产品。"},{"senses":"06 · 07","en":"THE CODE AND THE RULE: a replay from files, and a journal that demands the files.","cn":"代码与规则：从文件重跑，以及要求交出文件的期刊。"},{"senses":"08","en":"THE FAILURE: the same word names the absence of the quality.","cn":"失败：同一个词也命名这种性质的缺失。"}]},"affixes":{"intro":{"en":"Reproducibility is a three-part Latin stack on an English verb: re- plus produce plus -ible plus -ity.","cn":"reproducibility 是在英语动词上叠三层拉丁成分：re- 加 produce 再加 -ible 与 -ity。"},"latinIntro":{"en":"Latin producere, ducere and the endings -ibilis and -itas supply the structure of the word.","cn":"拉丁 producere、ducere 与后缀 -ibilis、-itas 提供这个词的结构。"},"items":[{"word":"producere","structure":"pro- forward plus ducere lead","meaning":"to lead forth; bring out","meaningCN":"引出；带出","example":"The verb supplies the producing inside the word.","exampleCN":"这个动词提供词里的「产出」。"},{"word":"ducere","structure":"Latin verb, third conjugation","meaning":"to lead","meaningCN":"引导","example":"The root is the moving element in many English words.","exampleCN":"这个词根是许多英语词里的「带动」成分。"},{"word":"re-","structure":"Latin prefix","meaning":"again; back","meaningCN":"再次；回","example":"The prefix asks for a second producing.","exampleCN":"前缀要求第二次产出。"},{"word":"reproduce","structure":"re- plus produce","meaning":"to produce again","meaningCN":"再次产出；复制","example":"The verb names the act of bringing back a result.","exampleCN":"这个动词指把结果再次带回来的行为。"},{"word":"-ible","structure":"Latin -ibilis","meaning":"able to be","meaningCN":"能够被……","example":"It builds reproducible from the verb.","exampleCN":"它由动词构成表示「可复现的」形容词。"},{"word":"-ity","structure":"Latin -itas through French","meaning":"the quality of","meaningCN":"……的性质","example":"It builds reproducibility from the adjective.","exampleCN":"它由形容词构成表示「可重复性」的名词。"},{"word":"reproducible","structure":"reproduce plus -ible","meaning":"able to be produced again","meaningCN":"能够被再次产出的","example":"The adjective describes the result or the procedure.","exampleCN":"这个形容词描述结果或步骤。"},{"word":"reproducibly","structure":"reproducible plus -ly","meaning":"in a repeatable way","meaningCN":"以可重复的方式","example":"The adverb marks how the work was done.","exampleCN":"副词标出工作是怎样做的。"}],"latinEntries":[{"word":"producere","structure":"produco, produxi, productum (v., third conjugation)","meaning":"to lead forth; bring out","meaningCN":"引出；带出"},{"word":"ducere","structure":"duco, duxi, ductum (v., third conjugation)","meaning":"to lead","meaningCN":"引导"},{"word":"re-","structure":"Latin prefix","meaning":"again; back","meaningCN":"再次；回"}],"derivatives":[{"word":"reproduce","pos":"v.","zh":"再现；复制；繁殖"},{"word":"reproducible","pos":"adj.","zh":"可复现的"},{"word":"reproducibly","pos":"adv.","zh":"可复现地"},{"word":"reproduction","pos":"n.","zh":"复制；繁殖"},{"word":"reproductive","pos":"adj.","zh":"生殖的"}]}},{"word":"reproducible","ipa_uk":"/ˌriːprəˈdjuːsəbl/","ipa_us":"/ˌriːprəˈduːsəbl/","definition_zh":"可复现的；可重复的；可再生的；可复制的","definition_en":"able to be produced again, especially with the same result","core_image":"两台机器读同一张配方卡，出料口各吐出一件一模一样的成品","scene":"车间里两台机器读同一张配方卡，出料口各吐出一件成品，检验员把两件并排比对尺寸。The result was reproducible in every trial, even when the room temperature changed.","sceneCN":"这里指同样的结果能够被再次做出来（第 1 个义项：结果可被再次得到）；句意为每一次试验的结果都可复现，即使室温发生变化。图中可辨识物件：两台机器、配方卡、两件成品、卡尺。","pos":[{"tag":"adj.","zh":"可复现的；可重复的；可再生的；可复制的"}],"collocations":[{"phrase":"reproducible result","zh":"可复现的结果"},{"phrase":"reproducible experiment","zh":"可重复的实验"},{"phrase":"highly reproducible","zh":"高度可重复的"},{"phrase":"reproducible measurement","zh":"可再现的测量"},{"phrase":"reproducible code","zh":"可复现的代码"},{"phrase":"reproducible process","zh":"可重复的流程"}],"forms":[{"label":"形容词","form":"reproducible"},{"label":"比较级","form":"more reproducible"},{"label":"副词","form":"reproducibly"},{"label":"名词","form":"reproducibility"},{"label":"动词（再现）","form":"reproduce"},{"label":"名词（复制）","form":"reproduction"}],"derivatives":[{"word":"reproduce","pos":"v.","zh":"再现；复制；繁殖"},{"word":"reproducibly","pos":"adv.","zh":"可复现地"},{"word":"reproducibility","pos":"n.","zh":"可重复性"},{"word":"reproduction","pos":"n.","zh":"复制；繁殖"},{"word":"reproductive","pos":"adj.","zh":"生殖的"},{"word":"producer","pos":"n.","zh":"生产者；制作人"}],"senses":[{"no":"01","title":"The result can be obtained again","titleCN":"结果能被再次得到","definition":"able to be obtained again under the same conditions, as a result","definitionCN":"作为结果，能在相同条件下被再次得到","example":"The result was reproducible in every trial, even when the room temperature changed.","exampleCN":"每一次试验的结果都可复现，即使室温发生变化。","why":"Reproduce is to produce again, and -ible says the producing can be done again.","whyCN":"动词表示再次产出，后缀表示这件事能够被再做一次。"},{"no":"02","title":"The experiment can be repeated","titleCN":"实验能被重复","definition":"described fully enough for another team to repeat the whole procedure","definitionCN":"描述得足够完整，使另一个团队能重复整套步骤","example":"A reproducible experiment must describe every step in detail.","exampleCN":"可重复的实验必须把每一步都详细写清。","why":"A procedure that cannot be followed again cannot produce the result again.","whyCN":"步骤无法被照着再做，结果也就无法再次产出。"},{"no":"03","title":"Able to produce offspring","titleCN":"能够繁殖后代的","definition":"able to produce new individuals, as a living thing","definitionCN":"作为生物，能够产生新的个体","example":"These plants are reproducible from seed within one season.","exampleCN":"这些植物在一个季节内就能由种子繁殖。","why":"Biology uses reproduce for making offspring, so the adjective also means able to breed.","whyCN":"生物学用该动词指繁殖后代，所以这个形容词也指能够繁殖。"},{"no":"04","title":"Able to be printed again","titleCN":"能够再次印制的","definition":"able to be copied from an original plate or file without loss","definitionCN":"能够从原版或文件复制而不失真","example":"The map is reproducible from the original plate.","exampleCN":"这张地图可以从原版重新印制。","why":"Printing was one of the first technologies to make copying a routine, and the word followed it.","whyCN":"印刷是最早使复制变得常规的技术之一，这个词也跟着走。"},{"no":"05","title":"An instrument that reads the same","titleCN":"读数稳定的仪器","definition":"giving the same reading when the same object is measured again","definitionCN":"再次测量同一对象时给出同一读数","example":"The balance gave reproducible readings on the same block.","exampleCN":"这台天平对同一块砝码给出可再现的读数。","why":"The adjective can describe the machine as well as the result it produces.","whyCN":"这个形容词既能描述结果，也能描述产出结果的机器。"},{"no":"06","title":"Code that can be rerun","titleCN":"可以重跑的代码","definition":"able to be rerun from shared data and code to give the same output","definitionCN":"能从共享的数据与代码重跑，并给出同一输出","example":"The analysis is reproducible from the shared code.","exampleCN":"这项分析可以用共享的代码重跑。","why":"Digital work made the steps into files, so reproducibility became a property of code.","whyCN":"数字工作把步骤变成文件，可复现性于是成了代码的属性。"},{"no":"07","title":"A process that repeats in production","titleCN":"生产中可重复的流程","definition":"giving the same product or measurement across repeated production runs","definitionCN":"在反复生产中给出一致的产品或测量","example":"The coating process is reproducible across the whole line.","exampleCN":"这道涂层工艺在整条生产线上都可重复。","why":"Industry asks whether the same process can be trusted to give the same thing twice.","whyCN":"工业要问的是：同一流程能不能被信任地做出两次同样的东西。"},{"no":"08","title":"Sound or image copied without loss","titleCN":"无损复制的声音或图像","definition":"able to be copied again without a noticeable loss of quality","definitionCN":"能够再次复制而不出现明显质量损失","example":"The recording is reproducible without any loss of quality.","exampleCN":"这段录音可以无损复制。","why":"Digital copying separated the copy from the decay that paper copies suffer.","whyCN":"数字复制把复制品与纸面复制品的损耗分开了。"}],"etymology":{"intro":{"en":"Reproducible is reproduce plus the Latin ending -ible, able to be. Reproduce comes from re- again and Latin producere, to lead forth. The source is clear; the first record date of the adjective is uncertain.","cn":"这个词由「产出」动词加表示「能够」的后缀构成。该动词来自表示「再次」的前缀与拉丁 producere「向前引出」。词源清楚，形容词最早记录的年代不确定。"},"items":[{"era":"LATIN PRODUCERE","en":"Producere joined pro- forward to ducere lead, meaning to bring forth.","cn":"producere 把意为「向前」的前缀加到意为「引导」的词根上，意为带出。"},{"era":"THE PREFIX RE-","en":"Re- adds the sense of a second producing, giving reproduce.","cn":"表示「再次」的前缀加上第二次产出的意思，构成「再次产出」的动词。"},{"era":"THE SUFFIX -IBLE","en":"Latin -ibilis means able to be, so reproducible is able to be produced again.","cn":"拉丁语 -ibilis 意为「能够被……」，因此「可复现的」指能够被再次产出。"},{"era":"ENGLISH REPRODUCIBLE","en":"English reproducible is recorded from the modern period with copying and biological senses; the exact first date is uncertain.","cn":"英语里这个形容词在近现代有复制与生物两类用法记录；确切首见年代不确定。"},{"era":"PRINTING AND BREEDING","en":"Printing and biology each gave the adjective a concrete home before science made it abstract.","cn":"印刷与生物学各自给了它一个具体归宿，科学随后把它抽象化。"},{"era":"MODERN SCIENCE","en":"Twentieth-century research made reproducible a standard requirement for results and methods.","cn":"二十世纪的研究使它成为结果与方法的标准要求。"}]},"similar":{"note":{"en":"The first group looks or sounds like reproducible; the second names adjectives close in meaning but different in scope.","cn":"第一组在形音上与「本词」相近；第二组是意思接近但范围不同的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reproduce","ipa":"/ˌriːprəˈdjuːs/","tag":"same root","definition":"The verb for producing again or breeding.","definitionCN":"再次产出或繁殖的动词。"},{"word":"reproducibly","ipa":"/ˌriːprəˈdjuːsəbli/","tag":"same root","definition":"The adverb for doing something in a repeatable way.","definitionCN":"以可重复的方式做某事的副词。"},{"word":"reproducibility","ipa":"/ˌriːprəˈdjuːsəbɪləti/","tag":"same root","definition":"The noun for the quality itself.","definitionCN":"这种性质本身的名词形式。"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","tag":"same root","definition":"A copy or the process of breeding.","definitionCN":"复制品，或繁殖过程。"},{"word":"produce","ipa":"/prəˈdjuːs/","tag":"same root","definition":"To make or bring forth; the base without re-.","definitionCN":"制造或产出；去掉 re- 的基础词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"repeatable","ipa":"/riːˈpiːtəbl/","tag":"near meaning","definition":"Able to be done again by the same person, often narrower than reproducible.","definitionCN":"能被同一个人再做一次，范围常比 reproducible 窄。"},{"word":"replicable","ipa":"/ˈreplɪkəbl/","tag":"near meaning","definition":"Able to be copied or repeated by another team.","definitionCN":"能被另一个团队复制或重复。"},{"word":"consistent","ipa":"/kənˈsɪstənt/","tag":"near meaning","definition":"Giving the same result each time, without claiming it is right.","definitionCN":"每次都给出同一结果，但不声称它是对的。"},{"word":"reliable","ipa":"/rɪˈlaɪəbl/","tag":"near meaning","definition":"Trustworthy over repeated use, a broader quality.","definitionCN":"在反复使用中可信，是一种更宽的性质。"},{"word":"duplicable","ipa":"/ˈdjuːplɪkəbl/","tag":"near meaning","definition":"Able to be copied exactly, with emphasis on the copy rather than the result.","definitionCN":"能够被精确复制，强调复制品而非结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin producing verb, the real -ible ending and real technical phrases.","cn":"正常联想使用真实的拉丁「产出」动词、真实的「能够」后缀与真实技术搭配。"},"normal":[{"en":"Reproducible is reproduce plus -ible: able to be produced again.","cn":"reproducible 是 reproduce 加 -ible：能够被再次产出。"},{"en":"Producere meant to lead forth, and re- asks for a second leading.","cn":"producere 意为向前引出，re- 要求第二次引出。"},{"en":"Fixed phrases include reproducible result, reproducible experiment and reproducible code.","cn":"固定说法有可复现结果、可重复实验与可复现代码。"},{"en":"A plant that is reproducible from seed and a map that is reproducible from a plate share the same ending but not the same field.","cn":"能由种子繁殖的植物与能从原版印出的地图，共享同一个词尾，却不在同一领域。"},{"en":"A balance with reproducible readings is trusted with the same block again and again.","cn":"读数可再现的天平，才被信任地反复称同一块砝码。"}],"abstract":[{"en":"Reproducible is a promise made to the next person who tries.","cn":"可复现是对下一个尝试者作出的承诺。"},{"en":"A copy that can be made again is worth more than a copy that cannot.","cn":"能再复制一次的复制品，比不能再复制的更值钱。"},{"en":"The adjective asks not whether something happened, but whether it can happen twice.","cn":"这个形容词不问某事是否发生过，而问它能不能发生两次。"}]},"examples":[{"en":"The method is reproducible enough for a teaching lab.","cn":"这个方法足够可重复，适合教学实验室。"},{"en":"A reproducible figure should come with the data behind it.","cn":"可复现的图应当附上其背后的数据。"},{"en":"The effect was small but reproducible across three sites.","cn":"效应不大，但在三个地点都可复现。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「能再产出的」——同一结果还能再做出来：可复现的","word":"reproducible"},"root":"这个词由意为「再次」的前缀、意为「产出」的词根与表示「能够」的后缀构成。词根源自拉丁 producere「向前引出」（前缀意为「向前」加词根意为「引导」）。印刷与生物学先有具体用法，现代科学又把它变成结果与方法的标准要求；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one repeatable thing: a result obtained again, a repeatable experiment, a breeding plant, a reprinted map, a stable instrument, rerunnable code, a repeatable process, and a lossless copy.","cn":"八个义项跟着同一件「可再做一次」的东西：再次得到的结果、可重复的实验、能繁殖的植物、可重印的地图、稳定的仪器、可重跑的代码、可重复的流程，以及无损复制。"},"semanticMap":{"core":{"en":"CORE IMAGE: two machines read the same recipe card and turn out two identical parts.","cn":"核心意象：两台机器读同一张配方卡，各吐出一件一模一样的零件。"},"chain":["SAME RESULT AGAIN","SECOND RUN","LIVING OFFSPRING","PRINTED COPY","STABLE MEASURE","REPLAYABLE CODE"],"branches":[{"senses":"01 · 02","en":"THE RESULT AND THE RUN: the same number returns, and the steps allow the run to happen again.","cn":"结果与重跑：同一个数值回来，而步骤让重跑成为可能。"},{"senses":"03","en":"THE LIVING KIND: plants and animals reproduce, so the adjective means able to breed.","cn":"活物一类：植物与动物会繁殖，于是形容词也指能繁殖。"},{"senses":"04 · 08","en":"THE COPY: a plate reprints a map, and a digital file copies a recording without loss.","cn":"复制品：原版重印地图，数字文件无损复制录音。"},{"senses":"05","en":"THE INSTRUMENT: a balance repeats its reading on the same block.","cn":"仪器：天平对同一块砝码重复给出读数。"},{"senses":"06 · 07","en":"THE CODE AND THE LINE: shared files rerun an analysis, and a process repeats across a production line.","cn":"代码与生产线：共享文件重跑分析，流程在整条生产线上重复。"}]},"affixes":{"intro":{"en":"Reproducible is an English verb with Latin affixes: re- plus produce plus -ible.","cn":"reproducible 是一个带拉丁词缀的英语动词形式：re- 加 produce 再加 -ible。"},"latinIntro":{"en":"Latin producere and ducere supply the stem, re- supplies the repetition, and -ibilis supplies the ability.","cn":"拉丁 producere 与 ducere 提供词干，re- 提供重复，-ibilis 提供能力。"},"items":[{"word":"producere","structure":"pro- forward plus ducere lead","meaning":"to lead forth","meaningCN":"引出；带出","example":"The verb gives the producing inside the word.","exampleCN":"这个动词提供词里的「产出」。"},{"word":"ducere","structure":"Latin verb, third conjugation","meaning":"to lead","meaningCN":"引导","example":"The root leads many English words.","exampleCN":"这个词根引导出许多英语词。"},{"word":"re-","structure":"Latin prefix","meaning":"again","meaningCN":"再次","example":"The prefix asks for a second producing.","exampleCN":"前缀要求第二次产出。"},{"word":"reproduce","structure":"re- plus produce","meaning":"to produce again","meaningCN":"再次产出","example":"The verb names the act.","exampleCN":"这个动词命名动作。"},{"word":"-ible","structure":"Latin -ibilis","meaning":"able to be","meaningCN":"能够被……","example":"The suffix turns the act into a possibility.","exampleCN":"后缀把动作变成一种可能。"},{"word":"reproducible","structure":"reproduce plus -ible","meaning":"able to be produced again","meaningCN":"能够被再次产出的","example":"The adjective describes results and procedures.","exampleCN":"这个形容词描述结果与步骤。"},{"word":"reproducibly","structure":"reproducible plus -ly","meaning":"in a repeatable way","meaningCN":"以可重复的方式","example":"The adverb marks the manner.","exampleCN":"副词标出方式。"},{"word":"reproducibility","structure":"reproducible plus -ity","meaning":"the quality itself","meaningCN":"这种性质本身","example":"The noun names the quality.","exampleCN":"名词命名这种性质。"}],"latinEntries":[{"word":"producere","structure":"produco, produxi, productum (v., third conjugation)","meaning":"to lead forth","meaningCN":"引出；带出"},{"word":"ducere","structure":"duco, duxi, ductum (v., third conjugation)","meaning":"to lead","meaningCN":"引导"},{"word":"re-","structure":"Latin prefix","meaning":"again","meaningCN":"再次"}],"derivatives":[{"word":"reproduce","pos":"v.","zh":"再现；复制；繁殖"},{"word":"reproducibly","pos":"adv.","zh":"可复现地"},{"word":"reproducibility","pos":"n.","zh":"可重复性"},{"word":"reproduction","pos":"n.","zh":"复制；繁殖"},{"word":"reproductive","pos":"adj.","zh":"生殖的"},{"word":"producer","pos":"n.","zh":"生产者；制作人"}]}},{"word":"replication","ipa_uk":"/ˌreplɪˈkeɪʃn/","ipa_us":"/ˌreplɪˈkeɪʃn/","definition_zh":"复制；重复实验；复现研究；复制品；自我复制","definition_en":"the act of copying something, or of repeating an experiment to see whether the result holds","core_image":"一只模具压出两件相同的零件，旁边一张卡片记着两次相同的测量值","scene":"工作台上摆着一只模具和两件刚压出的零件，检验员用卡尺量过两件，把同样的读数记在卡片上。The replication failed to confirm the original result, so the team repeated the whole procedure.","sceneCN":"这里指为验证原结果而重复整项研究或实验（第 1 个义项：重复实验以检验原结果是否成立）；句意为这次重复未能确认原结果，于是团队又把整套步骤重做了一遍。图中可辨识物件：模具、两件零件、卡尺、记录卡。","pos":[{"tag":"n.","zh":"复制；重复实验；复现研究；复制品"}],"collocations":[{"phrase":"replication study","zh":"重复研究"},{"phrase":"replication crisis","zh":"复现危机"},{"phrase":"successful replication","zh":"成功复现"},{"phrase":"replication of results","zh":"结果的复现"},{"phrase":"replication fork","zh":"复制叉"},{"phrase":"data replication","zh":"数据复制"}],"forms":[{"label":"不可数名词","form":"replication"},{"label":"动词（复制）","form":"replicate"},{"label":"形容词（可复制的）","form":"replicable"},{"label":"名词（复制品）","form":"replica"},{"label":"名词（复制者）","form":"replicator"},{"label":"名词（可复制性）","form":"replicability"}],"derivatives":[{"word":"replicate","pos":"v.","zh":"复制；重复"},{"word":"replicable","pos":"adj.","zh":"可复制的；可重复的"},{"word":"replicability","pos":"n.","zh":"可复制性；可重复性"},{"word":"replica","pos":"n.","zh":"复制品；仿制品"},{"word":"replicator","pos":"n.","zh":"复制者；复制因子"}],"senses":[{"no":"01","title":"Repeating a study to test it","titleCN":"为检验而重复研究","definition":"the act of repeating an experiment or study to see whether its result holds","definitionCN":"重复一项实验或研究，以检验其结果是否成立","example":"The replication failed to confirm the original result, so the team repeated the whole procedure.","exampleCN":"这次重复未能确认原结果，于是团队又把整套步骤重做了一遍。","why":"Replicare meant to fold back, and a replication folds the same procedure back onto itself.","whyCN":"拉丁词根意为折回，而一次重复就是把同一套步骤折回到自己身上。"},{"no":"02","title":"Copying in general","titleCN":"一般的复制动作","definition":"the act of making something that matches an original","definitionCN":"制造与原件相符之物的行为","example":"Careful replication of the method is easier when the protocol is public.","exampleCN":"当研究方案公开时，仔细复制这套方法会更容易。","why":"The general sense is older than the scientific one: any copy is a folding back of the original.","whyCN":"一般义比科学义更早：任何复制品都是原件的折回。"},{"no":"03","title":"A copy of an object","titleCN":"物件的复制品","definition":"an object made to look like another object","definitionCN":"造得与另一件物件相像的物品","example":"The museum displayed a replication of the ancient vase.","exampleCN":"博物馆展出了那只古代花瓶的复制品。","why":"Museums need a word for a stand-in that is honest about being a copy.","whyCN":"博物馆需要一个词来指一个坦承自己是复制品的替身。"},{"no":"04","title":"Copying inside a living cell","titleCN":"活细胞内的自我复制","definition":"the process by which genetic material or a cell makes a copy of itself","definitionCN":"遗传物质或细胞制造自身副本的过程","example":"Cell replication is the process by which one cell becomes two.","exampleCN":"细胞复制就是一个细胞变成两个的过程。","why":"Biology uses the word for a molecule folding out a copy of itself.","whyCN":"生物学用这个词指分子展开出一个自身副本。"},{"no":"05","title":"A duplicate legal document","titleCN":"法律文件的副本","definition":"a copy of a document kept for legal or official use","definitionCN":"为法律或官方用途保存的文件副本","example":"The lawyer kept a replication of the signed deed.","exampleCN":"律师保存了一份已签署契据的副本。","why":"Law has long needed exact copies, and the word covers the paper as well as the act.","whyCN":"法律早就需要精确副本，这个词既指行为也指那张纸。"},{"no":"06","title":"Copying data across systems","titleCN":"跨系统的数据复制","definition":"the process of keeping an identical copy of data on another system","definitionCN":"在另一个系统上保存同一份数据的过程","example":"Data replication keeps a second copy on another server.","exampleCN":"数据复制在另一台服务器上保留第二份副本。","why":"Computing borrows the biological and legal idea of an exact second copy.","whyCN":"计算借用了生物与法律里「精确第二份」的想法。"},{"no":"07","title":"A published repeat study","titleCN":"公开发表的重复研究","definition":"a study published specifically to repeat and check an earlier study","definitionCN":"专门为重复并核对早先研究而发表的论文","example":"The journal published a replication of the famous experiment.","exampleCN":"这家期刊发表了那项著名实验的重复研究。","why":"The scientific sense became a genre of paper, and the word names the genre.","whyCN":"科学义变成了一种论文类型，这个词也就命名这一类型。"},{"no":"08","title":"Reproducing an image layer","titleCN":"图像或版画的复制过程","definition":"the process of reproducing an image, colour layer or print from an original","definitionCN":"从原件复制图像、色层或版画的过程","example":"The printmaker checked the replication of each colour layer.","exampleCN":"版画家检查了每一层颜色的复制效果。","why":"Printmaking made replication a craft, with each layer folded back onto the sheet.","whyCN":"版画使复制成为一门手艺，每一层都折回到纸上。"}],"etymology":{"intro":{"en":"Replication comes from Latin replicatio, a folding back, from replicare, re- back plus plicare to fold. The source is clear; the date of its first English record is uncertain, and the scientific sense is much later.","cn":"这个词源自拉丁 replicatio「折回」，来自 replicare（前缀意为「回」加词根意为「折」）。词源清楚，最早英语记录的年代不确定，科学义出现得晚得多。"},"items":[{"era":"LATIN PLICARE","en":"Plicare meant to fold, and it gives the physical picture inside replication.","cn":"plicare 意为折，提供这个词内部的身体画面。"},{"era":"LATIN REPLICARE","en":"Replicare joined re- back to plicare, meaning to fold back or turn over.","cn":"replicare 把意为「回」的前缀加到 plicare 上，意为折回、翻转。"},{"era":"LATIN REPLICATIO","en":"Replicatio named a folding back; in later Latin it also served as a term in replies and legal answers.","cn":"replicatio 命名「折回」；在后来的拉丁语里也用于答复与法律答辩。"},{"era":"FRENCH REPLICATION","en":"French replication carried the word into English, where it first meant a reply or a copy.","cn":"法语 replication 把词带进英语，最初指答复或副本。"},{"era":"ENGLISH REPLICATION","en":"English replication is recorded with copying and answering senses; the exact first date is uncertain.","cn":"英语里这个词的复制义与答复义都有记录；确切首见年代不确定。"},{"era":"SCIENTIFIC REPLICATION","en":"Twentieth-century science made replication the standard name for repeating a study, and biology gave it the sense of self-copying.","cn":"二十世纪科学使这个词成为重复研究的标准说法，生物学又赋予它自我复制的义项。"}]},"similar":{"note":{"en":"The first group looks or sounds like replication; the second names nearby acts of copying or repeating.","cn":"第一组在形音上与「本词」相近；第二组是附近表示复制或重复的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"replicate","ipa":"/ˈreplɪkeɪt/","tag":"same root","definition":"The verb for copying or repeating.","definitionCN":"复制或重复的动词。"},{"word":"replicable","ipa":"/ˈreplɪkəbl/","tag":"same root","definition":"Able to be copied or repeated.","definitionCN":"可被复制或重复的。"},{"word":"replicability","ipa":"/ˌreplɪkəˈbɪləti/","tag":"same root","definition":"The quality of being replicable.","definitionCN":"可复制或可重复的性质。"},{"word":"replica","ipa":"/ˈreplɪkə/","tag":"same root","definition":"A copy of an object, often made to look exact.","definitionCN":"物件的复制品，常做得外观精确。"},{"word":"replicator","ipa":"/ˈreplɪkeɪtə/","tag":"same root","definition":"Something that copies itself, or a person who replicates.","definitionCN":"自我复制之物，或进行复制的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","tag":"near meaning","definition":"The broader word for producing a copy or offspring.","definitionCN":"产生副本或后代的更宽说法。"},{"word":"repetition","ipa":"/ˌrepəˈtɪʃn/","tag":"near meaning","definition":"Doing the same thing again, without necessarily copying an original.","definitionCN":"再做一遍同样的事，不必然复制原件。"},{"word":"duplication","ipa":"/ˌdjuːplɪˈkeɪʃn/","tag":"near meaning","definition":"The act of making an exact second copy.","definitionCN":"制造精确第二份副本的行为。"},{"word":"copy","ipa":"/ˈkɒpi/","tag":"near meaning","definition":"A reproduction of an original, or the act of making one.","definitionCN":"原件的复制品，或复制的行为。"},{"word":"repeat study","ipa":"/rɪˈpiːt ˈstʌdi/","tag":"near meaning","definition":"A study run again to check an earlier one.","definitionCN":"为核对早先研究而再做一次的研究。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real folding source, the real copy senses and real scientific terms.","cn":"正常联想使用真实的「折」来源、真实的复制义与真实科学术语。"},"normal":[{"en":"Replication comes from replicare, to fold back: a copy is the original folded over itself.","cn":"replication 来自 replicare「折回」：复制品就是原件折回到自己身上。"},{"en":"The same word covers a museum copy, a cell copying itself and a second experiment.","cn":"同一个词覆盖博物馆复制品、细胞自我复制与第二次实验。"},{"en":"Fixed phrases include replication study, replication crisis and data replication.","cn":"固定说法有重复研究、复现危机与数据复制。"},{"en":"A replication is not the same as a reproduction: the first repeats a study, the second produces a copy.","cn":"重复研究与复制并不相同：前者重做研究，后者产出副本。"},{"en":"Science made replication a genre of paper, not just an act.","cn":"科学使重复研究成为一种论文类型，而不只是一个动作。"}],"abstract":[{"en":"Replication is the second voice that asks whether the first voice told the truth.","cn":"重复研究是第二个声音，问第一个声音有没有说真话。"},{"en":"A copy can be exact and still prove nothing about the original's claim.","cn":"复制品可以很精确，却仍证明不了原结果的结论。"},{"en":"The fold is the picture: the same path taken again, back onto itself.","cn":"「折」就是画面：同一条路再走一次，折回到自身。"}]},"examples":[{"en":"The replication used a larger sample than the original.","cn":"这次重复研究用了比原研究更大的样本。"},{"en":"A failed replication is information, not an insult.","cn":"一次失败的重复是信息，不是侮辱。"},{"en":"The lab keeps a replication of every signed record.","cn":"实验室保存每一份已签记录的副本。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「来复利一份」——把原样再折回来一份：复制","word":"replication"},"root":"这个词源自拉丁 replicatio「折回」，来自 replicare（前缀意为「回」加词根意为「折」），经法语进入英语；原义与答复、折回相关，后发展出复制与重复义。生物自我复制义与科学研究复现义为近现代专门化；词源清楚，最早记录年代不确定。","sensesIntro":{"en":"Eight senses follow one fold: a repeated study, copying in general, a museum copy, a cell copying itself, a legal duplicate, data mirroring, a published repeat study, and the copying of an image layer.","cn":"八个义项跟着同一个「折」：重复研究、一般复制、博物馆复制品、细胞自我复制、法律副本、数据镜像、公开发表的重复研究，以及图像色层的复制。"},"semanticMap":{"core":{"en":"CORE IMAGE: one mould presses out two identical parts, and a card records the same measurement twice.","cn":"核心意象：一只模具压出两件相同的零件，一张卡片记下两次相同的测量。"},"chain":["COPY AGAIN","SECOND EXPERIMENT","PHYSICAL COPY","BIOLOGICAL SELF-COPY","LEGAL DUPLICATE","DATA MIRROR"],"branches":[{"senses":"01 · 07","en":"THE SECOND STUDY: repeating a procedure, and publishing the repeat as a study.","cn":"第二次研究：重复一套步骤，并把这次重复作为论文发表。"},{"senses":"02 · 08","en":"THE ACT OF COPYING: any copy made by hand or by a printing layer.","cn":"复制的动作：靠手或靠印版色层做出的任何副本。"},{"senses":"03 · 05","en":"THE PHYSICAL DUPLICATE: a museum vase and a signed deed both have stand-ins.","cn":"实物副本：博物馆花瓶与已签契据都有替身。"},{"senses":"04","en":"THE CELL: genetic material folds out a copy of itself.","cn":"细胞：遗传物质展开出一个自身副本。"},{"senses":"06","en":"THE SERVER: an identical second copy of data lives on another machine.","cn":"服务器：同一份数据的第二副本活在另一台机器上。"}]},"affixes":{"intro":{"en":"Replication is a Latin noun built on re- plus plicare, with the abstract ending -atio.","cn":"replication 是拉丁名词，建立在 re- 加 plicare 上，并用抽象后缀 -atio。"},"latinIntro":{"en":"Latin plicare, replicare and replicatio supply the word, and -atio became English -ation.","cn":"拉丁 plicare、replicare 与 replicatio 提供这个词，-atio 变成英语 -ation。"},"items":[{"word":"plicare","structure":"Latin verb, first conjugation","meaning":"to fold","meaningCN":"折","example":"The verb gives the physical picture of folding.","exampleCN":"这个动词给出「折」的身体画面。"},{"word":"re-","structure":"Latin prefix","meaning":"back","meaningCN":"回","example":"The prefix turns folding into folding back.","exampleCN":"前缀把「折」变成「折回」。"},{"word":"replicare","structure":"re- plus plicare","meaning":"to fold back","meaningCN":"折回；翻转","example":"The verb supplies the act behind the noun.","exampleCN":"这个动词提供名词背后的动作。"},{"word":"replicatio","structure":"Latin noun of action","meaning":"a folding back","meaningCN":"折回","example":"The noun is the direct source.","exampleCN":"这个名词是直接来源。"},{"word":"-ation","structure":"Latin -atio through French","meaning":"an action or its result","meaningCN":"动作或其结果","example":"The suffix builds replication, duplication and creation.","exampleCN":"这个后缀构成表示「复制」「加倍」「创造」的三个名词。"},{"word":"replicate","structure":"English verb","meaning":"to copy; repeat","meaningCN":"复制；重复","example":"The verb names the act.","exampleCN":"这个动词命名动作。"},{"word":"replica","structure":"Italian replica, from replicare","meaning":"a copy of an object","meaningCN":"物件的复制品","example":"The noun names the copy itself.","exampleCN":"这个名词命名复制品本身。"},{"word":"replicable","structure":"replicate plus -able","meaning":"able to be copied","meaningCN":"可被复制的","example":"The adjective marks the possibility.","exampleCN":"这个形容词标出可能性。"}],"latinEntries":[{"word":"plicare","structure":"plico, plicavi, plicatum (v., first conjugation)","meaning":"to fold","meaningCN":"折"},{"word":"replicare","structure":"replico, replicavi, replicatum (v., first conjugation)","meaning":"to fold back","meaningCN":"折回"},{"word":"replicatio","structure":"replicatio, replicationis (n., third declension)","meaning":"a folding back","meaningCN":"折回"}],"derivatives":[{"word":"replicate","pos":"v.","zh":"复制；重复"},{"word":"replicable","pos":"adj.","zh":"可复制的"},{"word":"replicability","pos":"n.","zh":"可复制性"},{"word":"replica","pos":"n.","zh":"复制品"},{"word":"replicator","pos":"n.","zh":"复制因子；复制者"}]}}]);
